import { createHash } from "node:crypto";

import { NextResponse } from "next/server";

import {
  decryptIntegrationToken,
  getUserIntegration,
} from "@/lib/gitlab/service";
import {
  getGitLabUserInstanceToken,
  markGitLabUserInstanceTokenStale,
  upsertGitLabUserInstanceToken,
} from "@/lib/gitlab/user-token";
import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance";
import {
  createMergeRequestDiscussion,
  MergeRequestDiscussionError,
} from "@/lib/gitlab/merge-request-discussions";
import { getSessionUserId } from "@/lib/session";
import { runWithApiRequestLog } from "@/lib/utils/logger";

type GitLabAction =
  | "projects"
  | "merge-requests"
  | "merge-request"
  | "merge-request-diff"
  | "create-merge-request-discussion"
  | "update-merge-request-description"
  | "validate-token"
  | "recent-merge-requests";

type GitLabDiscussionSide = "additions" | "deletions";

type GitLabProjectPayload = {
  action: GitLabAction;
  instanceUrl: string;
  token?: string;
  integrationId?: string;
  forceRefresh?: boolean;
  projectId?: string;
  mergeRequestIid?: string;
  streamDiff?: boolean;
  perPage?: number;
  search?: string;
  commentBody?: string;
  commentLine?: number;
  commentSide?: GitLabDiscussionSide;
  commentFilePath?: string;
  commentOldPath?: string;
  commentNewPath?: string;
  description?: string;
  allowEmptyDescription?: boolean;
};

type Project = {
  id: string;
  name: string;
  path: string;
  webUrl: string;
  defaultBranch?: string;
};

type MergeRequest = {
  id: string;
  iid: string;
  title: string;
  state: string;
  author: string;
  webUrl: string;
  projectId?: string;
  authoredByCurrentUser?: boolean;
  assignedToCurrentUser?: boolean;
  reviewRequestedFromCurrentUser?: boolean;
};

type GitLabCurrentUser = {
  id: number | null;
  username: string | null;
  name: string | null;
};

type GitLabRouteErrorCode =
  | "GITLAB_TOKEN_REQUIRED"
  | "GITLAB_TOKEN_STALE"
  | "GITLAB_TOKEN_INVALID"
  | "GITLAB_TOKEN_SCOPE_INVALID"
  | "GITLAB_HOST_UNREACHABLE"
  | "GITLAB_NETWORK_VPN_REQUIRED"
  | "GITLAB_TIMEOUT"
  | "GITLAB_RESOURCE_UNAUTHORIZED"
  | "GITLAB_RATE_LIMITED"
  | "GITLAB_UPSTREAM_TRANSIENT"
  | "GITLAB_UPSTREAM_ERROR";

type GitLabRouteErrorOptions = {
  status: number;
  code: GitLabRouteErrorCode;
  retryable?: boolean;
  reconnectRequired?: boolean;
  details?: Record<string, unknown>;
};

const MAX_PATCH_BYTES = 50_000_000;
const MAX_CACHED_PATCH_BYTES = 2_500_000;
const MERGE_REQUESTS_PER_PAGE_DEFAULT = 5;
const MERGE_REQUESTS_PER_PAGE_MAX = 100;
const PROJECTS_PER_PAGE_DEFAULT = 5;
const PROJECTS_PER_PAGE_MAX = 100;
const GITLAB_CACHE_TTL_MS = 15_000;
const GITLAB_PATCH_CACHE_TTL_MS = 60_000;
const GITLAB_CACHE_MAX_ENTRIES = 128;
const GITLAB_REQUEST_TIMEOUT_MS = 12_000;
const GITLAB_PROJECTS_REQUEST_TIMEOUT_MS = 45_000;
const GITLAB_RECENT_MERGE_REQUESTS_TIMEOUT_MS = 20_000;
const GITLAB_DIFF_REQUEST_TIMEOUT_MS = 60_000;
const GITLAB_VALIDATE_TIMEOUT_MS = 6_000;
const DIFF_TOO_LARGE_ERROR =
  "Diff exceeds maximum supported size of 50 MB.";

const DIFF_RESPONSE_CACHE_CONTROL =
  "private, max-age=120, stale-while-revalidate=600";

const TOKEN_STALE_CODES = new Set<GitLabRouteErrorCode>([
  "GITLAB_TOKEN_INVALID",
  "GITLAB_TOKEN_SCOPE_INVALID",
]);

type CacheEntry = {
  expiresAt: number;
  value: Promise<unknown>;
};

const gitLabResponseCache = new Map<string, CacheEntry>();

class GitLabRouteError extends Error {
  status: number;
  code: GitLabRouteErrorCode;
  retryable: boolean;
  reconnectRequired: boolean;
  details: Record<string, unknown> | null;

  constructor(message: string, options: GitLabRouteErrorOptions) {
    super(message);
    this.status = options.status;
    this.code = options.code;
    this.retryable = options.retryable ?? false;
    this.reconnectRequired = options.reconnectRequired ?? false;
    this.details = options.details ?? null;
  }
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  return value as Record<string, unknown>;
};

const normalizeDiscussionBody = (value: unknown) => {
  if (typeof value !== "string") {
    return "";
  }
  return value.trim();
};

const parseMergeRequestDescription = (value: unknown) => {
  if (typeof value !== "string") {
    return null;
  }
  return value;
};

const normalizeDiscussionLine = (value: unknown) => {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return null;
  }

  const normalized = Math.floor(value);
  if (normalized < 1) {
    return null;
  }
  return normalized;
};

const normalizeDiscussionSide = (value: unknown): GitLabDiscussionSide | null => {
  if (value === "additions" || value === "deletions") {
    return value;
  }
  return null;
};

const normalizeDiscussionPath = (value: unknown) => {
  if (typeof value !== "string") {
    return "";
  }
  return value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "");
};

const hashTokenForCache = (token: string) =>
  createHash("sha256").update(token).digest("hex");

const invalidateGitLabTokenScopedCache = ({
  instanceUrl,
  token,
}: {
  instanceUrl: string;
  token: string;
}) => {
  const tokenHash = hashTokenForCache(token);
  const cacheScopeFragment = `::${instanceUrl}::${tokenHash}::`;
  let invalidatedEntries = 0;

  for (const key of gitLabResponseCache.keys()) {
    if (!key.includes(cacheScopeFragment)) {
      continue;
    }

    if (gitLabResponseCache.delete(key)) {
      invalidatedEntries += 1;
    }
  }

  return invalidatedEntries;
};

const invalidateGitLabProjectListCache = ({
  instanceUrl,
  token,
}: {
  instanceUrl: string;
  token: string;
}) => {
  const tokenHash = hashTokenForCache(token);
  const projectCachePrefix = `json::${instanceUrl}::${tokenHash}::/api/v4/projects?`;
  let invalidatedEntries = 0;

  for (const key of gitLabResponseCache.keys()) {
    if (!key.startsWith(projectCachePrefix)) {
      continue;
    }

    if (gitLabResponseCache.delete(key)) {
      invalidatedEntries += 1;
    }
  }

  return invalidatedEntries;
};

const normalizePerPage = (value: unknown, fallback: number, max: number) => {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return fallback;
  }

  const normalized = Math.floor(value);
  return Math.min(max, Math.max(1, normalized));
};

const buildRouteError = (message: string, options: GitLabRouteErrorOptions) =>
  new GitLabRouteError(message, options);

const getRequestTimeoutMs = (action: GitLabAction) => {
  if (action === "validate-token") {
    return GITLAB_VALIDATE_TIMEOUT_MS;
  }

  if (action === "merge-request-diff") {
    return GITLAB_DIFF_REQUEST_TIMEOUT_MS;
  }

  if (action === "projects") {
    return GITLAB_PROJECTS_REQUEST_TIMEOUT_MS;
  }

  if (action === "recent-merge-requests") {
    return GITLAB_RECENT_MERGE_REQUESTS_TIMEOUT_MS;
  }

  return GITLAB_REQUEST_TIMEOUT_MS;
};

const getTruncatedBodyMessage = async (response: Response) => {
  const responseText = await response.text().catch(() => "");
  return responseText.length > 0 ? responseText.slice(0, 400) : "";
};

const classifyGitLabHttpError = (

  status: number,
  bodyMessage: string,
  action: GitLabAction,
) => {
  const normalizedBody = bodyMessage.toLowerCase();

  if (status === 401) {
    return buildRouteError(
      "GitLab token is invalid or expired. Reconnect your instance.",
      {
        status: 401,
        code: "GITLAB_TOKEN_INVALID",
        reconnectRequired: true,
      },
    );
  }

  if (status === 403) {
    if (
      normalizedBody.includes("scope") ||
      normalizedBody.includes("insufficient")
    ) {
      return buildRouteError(
        "GitLab token is missing required scope. Reconnect with api scope.",
        {
          status: 403,
          code: "GITLAB_TOKEN_SCOPE_INVALID",
          reconnectRequired: true,
        },
      );
    }

    if (action !== "projects" && action !== "validate-token") {
      return buildRouteError(
        "You do not have access to this project or merge request.",
        {
          status: 403,
          code: "GITLAB_RESOURCE_UNAUTHORIZED",
        },
      );
    }
  }

  if (status === 404 && action !== "projects") {
    return buildRouteError(
      "Project or merge request not found or access is restricted.",
      {
        status: 404,
        code: "GITLAB_RESOURCE_UNAUTHORIZED",
      },
    );
  }

  if (status === 429) {
    return buildRouteError("GitLab rate limit reached. Wait and retry.", {
      status: 429,
      code: "GITLAB_RATE_LIMITED",
      retryable: true,
    });
  }

  if (status === 408) {
    return buildRouteError(
      "GitLab request timed out upstream. Try again shortly.",
      {
        status: 408,
        code: "GITLAB_UPSTREAM_TRANSIENT",
        retryable: true,
      },
    );
  }

  if (status >= 500) {
    return buildRouteError(
      "GitLab is temporarily unavailable. Try again shortly.",
      {
        status,
        code: "GITLAB_UPSTREAM_TRANSIENT",
        retryable: true,
      },
    );
  }

  return buildRouteError(
    bodyMessage
      ? `GitLab request failed (${status}): ${bodyMessage}`
      : `GitLab request failed (${status}).`,
    {
      status,
      code: "GITLAB_UPSTREAM_ERROR",
    },
  );
};

const isLikelyVpnHost = (instanceUrl: string) => {
  try {
    const host = new URL(instanceUrl).hostname.toLowerCase();
    return host.endsWith(".lmco.com");
  } catch {
    return false;
  }
};

const classifyNetworkError = (error: unknown, instanceUrl: string) => {
  const message = error instanceof Error ? error.message : String(error);
  const normalized = message.toLowerCase();

  if (error instanceof Error && error.name === "AbortError") {
    return buildRouteError(
      "GitLab request timed out. Check host connectivity and retry.",
      {
        status: 504,
        code: "GITLAB_TIMEOUT",
        retryable: true,
      },
    );
  }

if (
  normalized.includes("enotfound") ||
  normalized.includes("eai_again") ||
  normalized.includes("dns")
) {
  const vpnLikely = isLikelyVpnHost(instanceUrl);
  return buildRouteError(
    vpnLikely
      ? "Cannot reach GitLab host. Connect to the required network or VPN and retry."
      : "GitLab host could not be resolved. Verify the instance URL and network.",
    {
      status: 502,
      code: vpnLikely
        ? "GITLAB_NETWORK_VPN_REQUIRED"
        : "GITLAB_HOST_UNREACHABLE",
      retryable: true,
    },
  );
}

if (
  normalized.includes("timeout") ||
  normalized.includes("timed out") ||
  normalized.includes("econnrefused") ||
  normalized.includes("econnreset")
) {
  const vpnLikely = isLikelyVpnHost(instanceUrl);
  return buildRouteError(
    vpnLikely
      ? "GitLab host is unreachable from this network. Connect VPN and retry."
      : "GitLab host is unreachable. Verify URL and network.",
    {
      status: 502,
      code: vpnLikely
        ? "GITLAB_NETWORK_VPN_REQUIRED"
        : "GITLAB_HOST_UNREACHABLE",
      retryable: true,
    },
  );
}

return buildRouteError("Unable to reach GitLab host.", {
  status: 502,
  code: "GITLAB_HOST_UNREACHABLE",
  retryable: true,
  details: {
    cause: message,
  },
});

};

const getGitLabRequest = async ({
  instanceUrl,
  token,
  apiPath,
  action,
  method = "GET",
  body,
}: {
  instanceUrl: string;
  token: string;
  apiPath: string;
  action: GitLabAction;
  method?: "GET" | "POST" | "PUT";
  body?: Record<string, unknown> | undefined;
}) => {
  const controller = new AbortController();
  const timeoutMs = getRequestTimeoutMs(action);
  const timeout = setTimeout(() => {
    controller.abort();
  }, timeoutMs);

  try {
    const headers: Record<string, string> = {
      "PRIVATE-TOKEN": token,
      "User-Agent": "argus-app",
    };
    if (body !== undefined) {
      headers["content-type"] = "application/json";
    }

    const response = await fetch(`${instanceUrl}${apiPath}`, {
      headers,
      method,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      signal: controller.signal,
    });

    if (!response.ok) {
      const bodyMessage = await getTruncatedBodyMessage(response);
      throw classifyGitLabHttpError(response.status, bodyMessage, action);
    }

    return response;
  } catch (error) {
    if (error instanceof GitLabRouteError) {
      throw error;
    }

    throw classifyNetworkError(error, instanceUrl);
  } finally {
    clearTimeout(timeout);
  }
};

