const trimGitLabResponseCache = () => {
  const now = Date.now();
  for (const [key, value] of gitLabResponseCache.entries()) {
    if (value.expiresAt <= now) {
      gitLabResponseCache.delete(key);
    }
  }

  while (gitLabResponseCache.size > GITLAB_CACHE_MAX_ENTRIES) {
    const oldestKey = gitLabResponseCache.keys().next().value;
    if (!oldestKey) {
      return;
    }
    gitLabResponseCache.delete(oldestKey);
  }
};

const getCachedGitLabValue = <T>(
  key: string,
  load: () => Promise<T>,
  options?: { shouldCacheValue?: (value: T) => boolean; ttlMs?: number },
) => {
  const now = Date.now();
  const cached = gitLabResponseCache.get(key);
  if (cached && cached.expiresAt > now) {
    return cached.value as Promise<T>;
  }
  if (cached) {
    gitLabResponseCache.delete(key);
  }

  const promise = load();
  gitLabResponseCache.set(key, {
    expiresAt: now + (options?.ttlMs ?? GITLAB_CACHE_TTL_MS),
    value: promise,
  });
  trimGitLabResponseCache();

  promise
    .then((value) => {
      if (!options?.shouldCacheValue || options.shouldCacheValue(value)) {
        return;
      }
      const current = gitLabResponseCache.get(key);
      if (current?.value === promise) {
        gitLabResponseCache.delete(key);
      }
    })
    .catch(() => {
      const current = gitLabResponseCache.get(key);
      if (current?.value === promise) {
        gitLabResponseCache.delete(key);
      }
    });

  return promise;
};

const getPatchSizeBytes = (patch: string) => Buffer.byteLength(patch, "utf8");

const shouldCachePatchPayload = (payload: { patch: string }) =>
  getPatchSizeBytes(payload.patch) <= MAX_CACHED_PATCH_BYTES;

const buildDiffTooLargeError = () =>
  new GitLabRouteError(DIFF_TOO_LARGE_ERROR, {
    status: 413,
    code: "GITLAB_UPSTREAM_ERROR",
  });

const getCachedGitLabJson = <T>({
  instanceUrl,
  token,
  apiPath,
  action,
  forceRefresh = false,
}: {
  instanceUrl: string;
  token: string;
  apiPath: string;
  action: GitLabAction;
  forceRefresh?: boolean;
}) => {
  const tokenHash = hashTokenForCache(token);
  const cacheKey = `json::${instanceUrl}::${tokenHash}::${apiPath}`;
  if (forceRefresh) {
    gitLabResponseCache.delete(cacheKey);
  }

  return getCachedGitLabValue(
    cacheKey,
    () =>
      getGitLabJson<T>({
        instanceUrl,
        token,
        apiPath,
        action,
      }),
  );
};

const normalizeGitLabUser = (value: unknown): GitLabCurrentUser => {
  const root = asRecord(value);
  if (!root) {
    return {
      id: null,
      username: null,
      name: null,
    };
  }

  return {
    id:
      typeof root.id === "number" && Number.isFinite(root.id) ? root.id : null,
    username:
      typeof root.username === "string" && root.username.trim().length > 0
        ? root.username.toLowerCase()
        : null,
    name:
      typeof root.name === "string" && root.name.trim().length > 0
        ? root.name.toLowerCase()
        : null,
  };
};

const isSameGitLabUser = (
  candidate: unknown,
  currentUser: GitLabCurrentUser,
) => {
  const root = asRecord(candidate);
  if (!root) {
    return false;
  }

  if (
    currentUser.id !== null &&
    typeof root.id === "number" &&
    root.id === currentUser.id
  ) {
    return true;
  }

  const username =
    typeof root.username === "string" && root.username.trim().length > 0
      ? root.username.toLowerCase()
      : null;
  if (username && currentUser.username && username === currentUser.username) {
    return true;
  }

  const name =
    typeof root.name === "string" && root.name.trim().length > 0
      ? root.name.toLowerCase()
      : null;

  return Boolean(name && currentUser.name && name === currentUser.name);
};

const mapMergeRequest = (
  row: Record<string, unknown>,
  currentUser: GitLabCurrentUser,
): MergeRequest => {
  const assignees = Array.isArray(row.assignees) ? row.assignees : [];
  const reviewers = Array.isArray(row.reviewers) ? row.reviewers : [];

  const authorRecord = asRecord(row.author);
  const authorName =
    typeof authorRecord?.name === "string" &&
    authorRecord.name.trim().length > 0
      ? authorRecord.name
      : "Unknown author";

  return {
    id: String(row.id),
    iid: String(row.iid),
    title: String(row.title ?? ""),
    state: String(row.state ?? "unknown"),
    author: authorName,
    webUrl: String(row.web_url ?? ""),
    projectId:
      typeof row.project_id === "number" || typeof row.project_id === "string"
        ? String(row.project_id)
        : undefined,
    authoredByCurrentUser: isSameGitLabUser(row.author, currentUser),
    assignedToCurrentUser: assignees.some((assignee) =>
      isSameGitLabUser(assignee, currentUser),
    ),
    reviewRequestedFromCurrentUser: reviewers.some((reviewer) =>
      isSameGitLabUser(reviewer, currentUser),
    ),
  };
};

const buildPatchFromChanges = (payload: unknown) => {
  const root =
    payload && typeof payload === "object"
      ? (payload as Record<string, unknown>)
      : null;

  const changes = Array.isArray(root?.changes)
    ? root.changes.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object",
      )
    : [];

  return changes
    .map((change) => {
      const rawDiff = String(change.diff ?? "").trimEnd();
      if (!rawDiff) {
        return null;
      }

      if (rawDiff.startsWith("diff --git ")) {
        return rawDiff;
      }

      const oldPath = String(change.old_path ?? change.new_path ?? "unknown");
      const newPath = String(change.new_path ?? change.old_path ?? "unknown");
      const oldHeader = change.new_file === true ? "/dev/null" : `a/${oldPath}`;
      const newHeader =
        change.deleted_file === true ? "/dev/null" : `b/${newPath}`;
      const diffHeader = `diff --git a/${oldPath} b/${newPath}`;
      const includesFileHeaders =
        /^---\s/m.test(rawDiff) && /^\+\+\+\s/m.test(rawDiff);

      if (includesFileHeaders) {
        return `${diffHeader}\n${rawDiff}`;
      }

      return `${diffHeader}\n--- ${oldHeader}\n+++ ${newHeader}\n${rawDiff}`;
    })
    .filter((value): value is string => Boolean(value))
    .join("\n\n");
};

const getMergeRequestPatchFromChanges = async ({
  instanceUrl,
  token,
  encodedProjectId,
  encodedMergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  encodedProjectId: string;
  encodedMergeRequestIid: string;
}) => {
  const changesPayload = await getGitLabJson<Record<string, unknown>>({
    instanceUrl,
    token,
    action: "merge-request-diff",
    apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/changes?access_raw_diffs=true`,
  });
  const fallbackPatch = buildPatchFromChanges(changesPayload);

  if (!fallbackPatch.trim()) {
    throw new GitLabRouteError("Merge request has no diff content to render.", {
      status: 404,
      code: "GITLAB_RESOURCE_UNAUTHORIZED",
    });
  }

  if (getPatchSizeBytes(fallbackPatch) > MAX_PATCH_BYTES) {
    throw buildDiffTooLargeError();
  }

  return fallbackPatch;
};

const getMergeRequestPatchStreamResponse = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
}) => {
  const encodedProjectId = encodeURIComponent(projectId);
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid);

  try {
    const rawDiffResponse = await getGitLabRequest({
      instanceUrl,
      token,
      apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/raw_diffs`,
      action: "merge-request-diff",
    });

    const contentLength = Number(rawDiffResponse.headers.get("content-length"));

if (Number.isFinite(contentLength) && contentLength > MAX_PATCH_BYTES) {
  throw buildDiffTooLargeError();
}

if (rawDiffResponse.body) {
  const reader = rawDiffResponse.body.getReader();
  const firstRead = await reader.read();

if (!firstRead.done && firstRead.value && firstRead.value.byteLength > 0) {
  let bytesRead = firstRead.value.byteLength;
  if (bytesRead > MAX_PATCH_BYTES) {
    throw buildDiffTooLargeError();
  }

  const firstChunk = firstRead.value;
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(firstChunk);
      void (async () => {
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) {
              break;
            }
            if (!value || value.byteLength === 0) {
              continue;
            }
            bytesRead += value.byteLength;
            if (bytesRead > MAX_PATCH_BYTES) {
              throw buildDiffTooLargeError();
            }
            controller.enqueue(value);
          }
          controller.close();
        } catch (error) {
          controller.error(error);
        } finally {
          reader.releaseLock();
        }
      })();
    },
    cancel(reason) {
      return reader.cancel(reason);
    },
  });

  return new Response(stream, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": DIFF_RESPONSE_CACHE_CONTROL,
      "x-diff-source": "raw_diffs",
    },
  });
}
reader.releaseLock();

  } else {
    const patch = await rawDiffResponse.text();
    if (getPatchSizeBytes(patch) > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }
    if (patch.trim().length > 0) {
      return new Response(patch, {
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "cache-control": DIFF_RESPONSE_CACHE_CONTROL,
          "x-diff-source": "raw_diffs",
        },
      });
    }
  }
} catch (rawDiffError) {
  if (
    rawDiffError instanceof GitLabRouteError &&
    rawDiffError.status === 413
  ) {
    throw rawDiffError;
  }
}

const fallbackPatch = await getMergeRequestPatchFromChanges({
  instanceUrl,
  token,
  encodedProjectId,
  encodedMergeRequestIid,
});

return new Response(fallbackPatch, {
  headers: {
    "content-type": "text/plain; charset=utf-8",
    "cache-control": DIFF_RESPONSE_CACHE_CONTROL,
    "x-diff-source": "changes",
  },
});

};

const getMergeRequestPatch = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
}) => {
  const encodedProjectId = encodeURIComponent(projectId);
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid);

  try {
    const rawDiffResponse = await getGitLabRequest({
      instanceUrl,
      token,
      apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/raw_diffs`,
      action: "merge-request-diff",
    });
    const contentLength = Number(rawDiffResponse.headers.get("content-length"));
    if (Number.isFinite(contentLength) && contentLength > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }

    const patch = await rawDiffResponse.text();
    if (getPatchSizeBytes(patch) > MAX_PATCH_BYTES) {
      throw buildDiffTooLargeError();
    }

    if (patch.trim().length > 0) {
      return { patch, source: "raw_diffs" as const };
    }
  } catch (rawDiffError) {
    if (
      rawDiffError instanceof GitLabRouteError &&
      rawDiffError.status === 413
    ) {
      throw rawDiffError;
    }
  }

  const fallbackPatch = await getMergeRequestPatchFromChanges({
    instanceUrl,
    token,
    encodedProjectId,
    encodedMergeRequestIid,
  });

  return { patch: fallbackPatch, source: "changes" as const };
};

const getCachedMergeRequestPatch = ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string;
  token: string;
  projectId: string;
  mergeRequestIid: string;
