  const tokenHash = hashTokenForCache(token);
  return getCachedGitLabValue(
    `patch::${instanceUrl}::${tokenHash}::${projectId}::${mergeRequestIid}`,
    () =>
      getMergeRequestPatch({
        instanceUrl,
        token,
        projectId,
        mergeRequestIid,
      }),
    {
      shouldCacheValue: shouldCachePatchPayload,
      ttlMs: GITLAB_PATCH_CACHE_TTL_MS,
    },
  );
};

const resolveTokenForRequest = async ({
  userId,
  instanceUrl,
  requestToken,
  integrationId,
  projectId,
}: {
  userId: string;
  instanceUrl: string;
  requestToken: string | undefined;
  integrationId?: string;
  projectId?: string;
}) => {
  const normalizedRequestToken = requestToken?.trim();
  if (normalizedRequestToken) {
    // Token persistence is best-effort. Read actions should still work even if
    // the optional user-token cache table is unavailable/misaligned.
    await upsertGitLabUserInstanceToken({
      userId,
      instanceUrl,
      token: normalizedRequestToken,
    }).catch(() => null);
    return {
      token: normalizedRequestToken,
      source: "request" as const,
    };
  }

  let storedToken = null as Awaited<
    ReturnType<typeof getGitLabUserInstanceToken>
  >;
  try {
    storedToken = await getGitLabUserInstanceToken(userId, instanceUrl);
  } catch {
    storedToken = null;
  }

  if (!storedToken) {
    const normalizedIntegrationId = integrationId?.trim();
    const normalizedProjectId = projectId?.trim();

    if (normalizedIntegrationId) {
      const integration = await getUserIntegration(
        normalizedIntegrationId,
        userId,
      );
      const matchesScope =
        integration &&
        integration.instanceUrl === instanceUrl &&
        (!normalizedProjectId || integration.projectId === normalizedProjectId);

      if (matchesScope && integration) {
        try {
          const integrationToken = decryptIntegrationToken(integration);
          if (integrationToken.trim()) {
            return {
              token: integrationToken,
              source: "integration" as const,
            };
          }
        } catch {
          // Fall through to token-required error below.
        }
      }
    }

    throw buildRouteError(
      "Personal access token is required. Reconnect your GitLab instance.",
      {
        status: 400,
        code: "GITLAB_TOKEN_REQUIRED",
        reconnectRequired: true,
      },
    );
  }

  if (storedToken.staleAt) {
    throw buildRouteError(
      "Stored GitLab token is stale. Reconnect your GitLab instance.",
      {
        status: 401,
        code: "GITLAB_TOKEN_STALE",
        reconnectRequired: true,
        details: {
          staleAt: storedToken.staleAt.toISOString(),
          staleReason: storedToken.staleReason,
        },
      },
    );
  }

  return {
    token: storedToken.token,
    source: "stored" as const,
  };
};

export async function POST(request: Request) {

return runWithApiRequestLog({
  request,
  path: "/api/gitlab",
  event: "api.gitlab.proxy",
  handler: async ({ logger }) => {
    const [userId, rawPayload] = await Promise.all([
      getSessionUserId(),
      request.json().catch(() => null),
    ]);

    if (!userId) {
      return {
        status: 401,
        outcome: "unauthorized",
        response: NextResponse.json(
          { error: "Unauthorized" },
          { status: 401 },
        ),
      };
    }

    const payload = rawPayload as GitLabProjectPayload | null;

    if (!payload || payload.action === undefined) {
      return {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json(
          { error: "Invalid request payload." },
          { status: 400 },
        ),
      };
    }

    if (
      payload.action !== "projects" &&
      payload.action !== "merge-requests" &&
      payload.action !== "merge-request" &&
      payload.action !== "merge-request-diff" &&
      payload.action !== "create-merge-request-discussion" &&
      payload.action !== "update-merge-request-description" &&
      payload.action !== "validate-token" &&
      payload.action !== "recent-merge-requests"
    ) {
      return {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json(
          { error: "Unsupported action." },
          { status: 400 },
        ),
      };
    }

if (!isNonEmptyString(payload.instanceUrl)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "GitLab instance URL is required." },
      { status: 400 },
    ),
  };
}

let normalizedInstanceUrl: string;
try {
  normalizedInstanceUrl = normalizeGitLabInstanceUrl(payload.instanceUrl);
} catch (error) {
  const message =
    error instanceof Error
      ? error.message
      : "GitLab instance URL is invalid.";
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      {
        error: message,
        code: "GITLAB_UPSTREAM_ERROR",
      },
      { status: 400 },
    ),
  };
}

try {
  const resolvedToken = await resolveTokenForRequest({
    userId,
    instanceUrl: normalizedInstanceUrl,
    requestToken: payload.token,
    integrationId: payload.integrationId,
    projectId: payload.projectId,
  });

  logger.set({
    action: payload.action,
    instanceUrl: normalizedInstanceUrl,
    tokenSource: resolvedToken.source,
  });

if (payload.action === "validate-token") {
  const currentUserData = await getCachedGitLabJson<
    Record<string, unknown>
  >({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    apiPath: "/api/v4/user",
  });
  const currentUser = normalizeGitLabUser(currentUserData);

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        id: currentUser.id,
        username: currentUser.username,
        name: currentUser.name,
      },
    }),
  };
}

if (payload.action === "projects") {
  const perPage = normalizePerPage(
    payload.perPage,
    PROJECTS_PER_PAGE_DEFAULT,
    PROJECTS_PER_PAGE_MAX,
  );
  const forceRefresh = payload.forceRefresh === true;
  const forceRefreshInvalidatedEntries = forceRefresh
    ? invalidateGitLabProjectListCache({
        instanceUrl: normalizedInstanceUrl,
        token: resolvedToken.token,
      })
    : 0;
  const normalizedSearch = payload.search?.trim() ?? "";
  const useSearch = normalizedSearch.length >= 3;
  const searchParam = useSearch
    ? `&search=${encodeURIComponent(normalizedSearch)}`
    : "";

const primaryProjectsApiPath = `/api/v4/projects?membership=true&simple=true&per_page=${perPage}&order_by=last_activity_at&sort=desc${searchParam}`;
const fallbackProjectsApiPath = `/api/v4/projects?membership=true&simple=true&per_page=${perPage}${searchParam}`;

let projectsApiPathUsed = primaryProjectsApiPath;
let responseData: Array<Record<string, unknown>>;

try {
  responseData = await getCachedGitLabJson<Array<Record<string, unknown>>>({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    forceRefresh,
    apiPath: primaryProjectsApiPath,
  });
} catch (error) {
  const shouldUseFallback =
    error instanceof GitLabRouteError &&
    (error.code === "GITLAB_UPSTREAM_TRANSIENT" ||
      error.code === "GITLAB_TIMEOUT");

  if (!shouldUseFallback) {
    throw error;
  }

  projectsApiPathUsed = fallbackProjectsApiPath;
  responseData = await getCachedGitLabJson<Array<Record<string, unknown>>>({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    forceRefresh,
    apiPath: fallbackProjectsApiPath,
  });
}

const projects: Project[] = responseData
  .filter((item) => item && typeof item === "object")
  .map((item) => ({
    id: String(item.id),
    name: String(item.name_with_namespace ?? item.name ?? item.path),
    path: String(item.path_with_namespace ?? item.path),
    webUrl: String(item.web_url ?? ""),
    defaultBranch:
      typeof item.default_branch === "string" &&
      item.default_branch.trim().length > 0
        ? item.default_branch
        : undefined,
  }));

logger.set({
  count: projects.length,
  searchApplied: useSearch,
  forceRefresh,
  forceRefreshInvalidatedEntries,
  projectsApiPathUsed,
  projectsFallbackUsed: projectsApiPathUsed !== primaryProjectsApiPath,
});
return {
  status: 200,
  outcome: "success",
  response: NextResponse.json({ data: projects }),
};

}

if (payload.action === "recent-merge-requests") {
  const perPage = normalizePerPage(
    payload.perPage,
    MERGE_REQUESTS_PER_PAGE_DEFAULT,
    MERGE_REQUESTS_PER_PAGE_MAX,
  );
  const [responseData, currentUserData] = await Promise.all([
    getCachedGitLabJson<Array<Record<string, unknown>>>({
      instanceUrl: normalizedInstanceUrl,
      token: resolvedToken.token,
      action: payload.action,
      apiPath: `/api/v4/merge_requests?scope=all&state=opened&per_page=${perPage}&order_by=updated_at&sort=desc`,
    }),
    getCachedGitLabJson<Record<string, unknown>>({
      instanceUrl: normalizedInstanceUrl,
      token: resolvedToken.token,
      action: payload.action,
      apiPath: "/api/v4/user",
    }).catch(() => ({})),
  ]);

  const currentUser = normalizeGitLabUser(currentUserData);
  const mergeRequests: MergeRequest[] = responseData
    .filter((item) => item && typeof item === "object")
    .map((item) => mapMergeRequest(item, currentUser));

  logger.set({ count: mergeRequests.length });
  return {
    status: 200,
    outcome: "success",
