export const shouldSkipPollingRequest = ({
  isVisible,
  inFlightRequestKey,
  nextRequestKey,
}: {
  isVisible: boolean
  inFlightRequestKey: string | null
  nextRequestKey: string
}) => {
  if (!isVisible) {
    return true
  }

  return inFlightRequestKey !== null && inFlightRequestKey === nextRequestKey
}

