const resolveProcessLike = (): ProcessLike => {
  const processLike = (globalThis as { process?: ProcessLike }).process
  if (!processLike) {
    throw new Error("[indexer-worker] process APIs are unavailable")
  }
  return processLike
}

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

export const runIndexerWorkerRuntime = async <TLogger extends ScopedLogger>(
  deps: IndexerWorkerRuntimeDeps<TLogger>,
) => {
  const env = deps.env ?? resolveDefaultEnv()
  const processLike = deps.processLike ?? resolveProcessLike()
  const sleep = deps.sleep ?? defaultSleep
  const now = deps.now ?? Date.now
  let shutdownInProgress = false

  const flushAndExit = (signal: SignalName) => {
    if (shutdownInProgress) {
      return
    }
    shutdownInProgress = true

    void (async () => {
      deps.appLogInfo({
        event: "indexer.worker.shutdown_signal",
        signal,
      })
      try {
        await deps.flushAppLogger()
      } finally {
        processLike.exit(0)
      }
    })()
  }

  try {
    const workerConfig = resolveIndexerWorkerConfig(env)

    deps.initAppLogger({
      service: workerConfig.service,
      environment: workerConfig.environment,
      version: workerConfig.version,
      pretty: workerConfig.pretty,
      initEvent: "indexer.worker.observability_initialized",
    })

    processLike.once("SIGINT", () => flushAndExit("SIGINT"))
    processLike.once("SIGTERM", () => flushAndExit("SIGTERM"))

deps.appLogInfo({
  event: "indexer.worker.started",
  batchSize: workerConfig.batchSize,
  pollIntervalMs: workerConfig.pollIntervalMs,
  continuous: workerConfig.continuous,
})

do {
  const batchId = deps.createCorrelationId()
  const cycleLog = deps.createScopedLogger({
    method: "INDEXER",
    path: "/workers/indexer/cycle",
    requestId: batchId,
  })
  const cycleStartedAt = now()
  cycleLog.set({
    event: "indexer.worker.batch_cycle",
    batchId,
    batchSize: workerConfig.batchSize,
    continuous: workerConfig.continuous,
  })
  let cycleStatus = 500
  try {
    const summary = await deps.runIndexingWorkerBatch(workerConfig.batchSize, { batchId })
    cycleLog.set({
      summary,
    })
    cycleStatus =
      summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
        ? 207
        : 200

    if (!workerConfig.continuous) {
      break
    }

    await sleep(workerConfig.pollIntervalMs)
  } finally {
    cycleLog.emit({
      status: cycleStatus,
      durationMs: now() - cycleStartedAt,
    })
  }
} while (true)

await deps.flushAppLogger()

  } catch (error) {
    const errorToLog = toError(error, "Indexer worker crashed.")
    const fatalLog = deps.createScopedLogger({
      method: "INDEXER",
      path: "/workers/indexer",
      requestId: deps.createCorrelationId(),
    })
    fatalLog.set({
      event: "indexer.worker.fatal",
      outcome: "crashed",
    })
    deps.logScopedError(fatalLog, errorToLog, {
      code: "INDEXER_WORKER_FATAL",
      why: "Unhandled exception escaped the indexer worker loop.",
      fix: "Inspect preceding batch/job events and dependency health.",
    })
    fatalLog.emit({
      status: 500,
    })

    await deps.flushAppLogger()
    throw errorToLog
  }
}

"use client"

import Link from "next/link"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"

type IndexRun = {
  id: string
  branch: string
  status: string
  mode: string
  headSha: string
  updatedAt: string
}

type QueueStats = {
  pending: number
  processing: number
  failed: number
  dead: number
  oldestPendingAt: string | null
  lastProcessedAt: string | null
} | null

type WorkerStats = {
  staleAfterMs: number
  lastHeartbeatAt: string | null
  heartbeatAgeMs: number | null
  isOnline: boolean
} | null

type RepoIndexingPanelProps = {
  indexRuns: IndexRun[]
  queue: QueueStats
  worker: WorkerStats
  fullConsoleHref: string
  isLoading: boolean
  lastRefreshedAt: Date | null
}

const statusVariant = (status: string): React.ComponentProps<typeof Badge>["variant"] => {
  if (status === "ready" || status === "succeeded" || status === "active" || status === "opened") {
    return "default"
  }
  if (status === "failed" || status === "dead") {
    return "destructive"
  }
  if (status === "planned" || status === "pending" || status === "processing" || status === "indexing" || status === "ingesting") {
    return "secondary"
  }
  return "outline"
}

const formatDateTime = (value: string | null | undefined) => {
  if (!value) return "Never"
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return "Unknown"
  return parsed.toLocaleString()
}

const shortSha = (sha: string | null | undefined) => {
  if (!sha) return "n/a"
  return sha.slice(0, 12)
}

export type { IndexRun, QueueStats, WorkerStats }

export function RepoIndexingPanel({
  indexRuns,
  queue,
  worker,
  fullConsoleHref,
  isLoading,
  lastRefreshedAt,
}: RepoIndexingPanelProps) {
  const latestRun = indexRuns[0] ?? null

  const workerLabel = (() => {
    if (!worker) return { label: "unknown", variant: "outline" as const }
    if (worker.isOnline) return { label: "online", variant: "default" as const }
    if ((queue?.pending ?? 0) > 0 || (queue?.processing ?? 0) > 0) {
      return { label: "offline", variant: "destructive" as const }
    }
    return { label: "idle", variant: "secondary" as const }
  })()

  return (
    <div className="space-y-4">
      {/* Worker + latest run status */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex items-center gap-1.5">
          <span className="text-xs font-medium text-muted-foreground">Worker</span>
          <Badge variant={workerLabel.variant}>{workerLabel.label}</Badge>
        </div>
        {latestRun ? (
          <div className="flex items-center gap-1.5">
            <span className="text-xs font-medium text-muted-foreground">Latest</span>
            <Badge variant={statusVariant(latestRun.status)}>{latestRun.status}</Badge>
          </div>
        ) : null}
      </div>

      {/* Queue stats grid */}

{isLoading ? (
  <p className="text-sm text-muted-foreground">Loading indexing summary…</p>
) : indexRuns.length === 0 ? (
  <p className="text-sm text-muted-foreground">No indexing runs yet.</p>
) : (
  <div className="space-y-1.5">
    <p className="text-xs font-medium text-muted-foreground">Recent runs</p>
    <ul className="space-y-1.5">
      {indexRuns.map((run) => (
        <li
          key={run.id}
          className="flex items-center justify-between gap-2 rounded-lg border border-border/60 px-3 py-2"
        >
          <div className="min-w-0">
            <p className="truncate text-sm font-medium">{run.branch}</p>
            <p className="text-xs text-muted-foreground">
              {run.mode} · {shortSha(run.headSha)}
            </p>
          </div>
          <div className="shrink-0 text-right">
