import { useEffect } from "react"
import type { QueryClient } from "@tanstack/react-query"

import type {
  MergeRequest,
  OnboardingRouteStep,
  Project,
} from "@/components/onboarding/onboarding-types"
import {
  MERGE_REQUESTS_PRELOAD_CONCURRENCY,
  MERGE_REQUESTS_PRELOAD_LIMIT,
  MERGE_REQUESTS_PRELOAD_PROJECTS_LIMIT,
  ONBOARDING_PREFETCH_STALE_TIME,
  ONBOARDING_QUERY_GC_TIME,
} from "@/components/onboarding/onboarding-flow.utils"

type UseOnboardingMrPrefetchOptions = {
  isHydrated: boolean
  routeStep: OnboardingRouteStep
  projectsCacheKey: string
  projects: Project[]
  selectedProjectId: string
  queryClient: QueryClient
  mergeRequestsQueryKey: (projectId: string, perPage: number) => readonly [
    "onboarding",
    "merge-requests",
    string,
    string,
    number,
  ]
  callGitLab: (
    action: "projects" | "merge-requests" | "recent-merge-requests",
    params?: { projectId?: string; perPage?: number; search?: string },
  ) => Promise<unknown>
}

const shouldPrefetchMergeRequestQuery = ({
  queryClient,
  queryKey,
}: {
  queryClient: QueryClient
  queryKey: readonly unknown[]
}) => {
  const state = queryClient.getQueryState(queryKey)
  if (!state) {
    return true
  }

  if (state.fetchStatus === "fetching") {
    return false
  }

  if (!state.dataUpdatedAt) {
    return true
  }

  return Date.now() - state.dataUpdatedAt >= ONBOARDING_PREFETCH_STALE_TIME
}

export function useOnboardingMrPrefetch({

  isHydrated,
  routeStep,
  projectsCacheKey,
  projects,
  selectedProjectId,
  queryClient,
  mergeRequestsQueryKey,
  callGitLab,
}: UseOnboardingMrPrefetchOptions) {
  useEffect(() => {
    if (!isHydrated || routeStep !== "projects" || !projectsCacheKey || projects.length === 0) {
      return
    }

    const projectIds = projects
      .slice(0, MERGE_REQUESTS_PRELOAD_PROJECTS_LIMIT)
      .map((project) => project.id)
    if (selectedProjectId.trim().length > 0 && !projectIds.includes(selectedProjectId)) {
      projectIds.push(selectedProjectId)
    }
    let cancelled = false

    const preloadMergeRequests = async () => {
      const workerCount = Math.min(MERGE_REQUESTS_PRELOAD_CONCURRENCY, projectIds.length)
      let nextProjectIndex = 0

      const workers = Array.from({ length: workerCount }, () => async () => {
        while (!cancelled) {
          const projectId = projectIds[nextProjectIndex]
          nextProjectIndex += 1

          if (!projectId) {
            return
          }

          const queryKey = mergeRequestsQueryKey(projectId, MERGE_REQUESTS_PRELOAD_LIMIT)
          if (!shouldPrefetchMergeRequestQuery({ queryClient, queryKey })) {
            continue
          }

          await queryClient
            .prefetchQuery({
              queryKey,
              queryFn: () =>
                callGitLab("merge-requests", {
                  projectId,
                  perPage: MERGE_REQUESTS_PRELOAD_LIMIT,
                }) as Promise<MergeRequest[]>,
              staleTime: ONBOARDING_PREFETCH_STALE_TIME,
              gcTime: ONBOARDING_QUERY_GC_TIME,
            })
            .catch(() => null)
        }
      })

      await Promise.allSettled(workers.map((worker) => worker()))
    }

    void preloadMergeRequests()

    return () => {
      cancelled = true
    }
  }, [
    callGitLab,
    isHydrated,
    mergeRequestsQueryKey,
    projects,
    projectsCacheKey,
    queryClient,
    routeStep,
    selectedProjectId,
  ])
}

import type { ObservabilityLlmMetrics } from "@/lib/observability/types"

type UsageRecord = {
  promptTokens: number
  completionTokens: number
  totalTokens: number
}

type UsageLikePayload = {
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
    promptTokens?: unknown
    completionTokens?: unknown
    totalTokens?: unknown
  } | null
}

const asNonNegativeInt = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.floor(value)
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed
    }
  }

  return null
}

const toUsd = (value: number) => Number(value.toFixed(8))

const normalizeModelEnvKey = (model: string) =>
  model
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")

const resolveUsdPer1kFromEnv = (args: {
  prefix: string
  model: string | null
}): number | null => {
  const modelKey = args.model ? normalizeModelEnvKey(args.model) : ""
  const modelEnvKey = modelKey ? `${args.prefix}_${modelKey}` : ""
  const rawModelRate = modelEnvKey ? process.env[modelEnvKey] : undefined
  const rawGlobalRate = process.env[args.prefix]
  const rawRate = rawModelRate ?? rawGlobalRate
  if (!rawRate || rawRate.trim().length === 0) {
    return null
  }

  const parsed = Number.parseFloat(rawRate)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return null
  }

  return parsed
}

export const resolveLlmProviderLabel = (apiUrl: string): string => {
  try {
    const hostname = new URL(apiUrl).hostname.trim().toLowerCase()
    if (!hostname) {
      return "openai-compatible"
    }
    if (hostname.includes("openai.com")) {
      return "openai"
    }
    return `openai-compatible:${hostname}`
  } catch {
    return "openai-compatible"
  }
}

export const extractUsageFromOpenAiCompatiblePayload = (payload: unknown): UsageRecord => {
  const usage = (payload as UsageLikePayload | null)?.usage ?? null
  if (!usage || typeof usage !== "object" || Array.isArray(usage)) {
    return {
      promptTokens: 0,
      completionTokens: 0,
      totalTokens: 0,
    }
  }

  const promptTokens =
    asNonNegativeInt(usage.prompt_tokens) ??
    asNonNegativeInt(usage.promptTokens) ??
    0
  const completionTokens =
    asNonNegativeInt(usage.completion_tokens) ??
    asNonNegativeInt(usage.completionTokens) ??
    0
  const totalTokens =
    asNonNegativeInt(usage.total_tokens) ??
    asNonNegativeInt(usage.totalTokens) ??
    promptTokens + completionTokens

  return {
    promptTokens,
    completionTokens,
    totalTokens,
  }
}

export const estimateLlmCostUsd = (args: {
  model: string | null
  promptTokens: number
  completionTokens: number
}): number | null => {
  const promptUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_PROMPT_USD_PER_1K",
    model: args.model,
  })
  const completionUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_COMPLETION_USD_PER_1K",
    model: args.model,
  })

  if (promptUsdPer1k === null && completionUsdPer1k === null) {
    return null
  }

  const promptCost = ((promptUsdPer1k ?? 0) * Math.max(0, args.promptTokens)) / 1_000
  const completionCost = ((completionUsdPer1k ?? 0) * Math.max(0, args.completionTokens)) / 1_000
  return toUsd(promptCost + completionCost)
}

export const estimateEmbeddingCostUsd = (args: {
  model: string | null
  totalTokens: number
}): number | null => {
  const usdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_EMBEDDING_COST_USD_PER_1K",
    model: args.model,
  })
  if (usdPer1k === null) {
    return null
  }

  const totalCost = (usdPer1k * Math.max(0, args.totalTokens)) / 1_000
  return toUsd(totalCost)
}

