import { execFile } from "node:child_process"
import { promisify } from "node:util"

import { z } from "zod"

import { resolveCodeIntelConfigPath, resolveCodeIntelRoot } from "@/lib/argus-search/code-intel-root"

const execFileAsync = promisify(execFile)

const positionSchema = z.object({
  row: z.number().int().nonnegative(),
  column: z.number().int().nonnegative(),
})

const rangeSchema = z.object({
  start: positionSchema,
  end: positionSchema,
})

const traceNodeSchema = z.object({
  id: z.string().min(1),
  kind: z.string().min(1),
  name: z.string().min(1),
  filePath: z.string().min(1),
  rangeJson: z.string().min(1),
})

const traceNodesSchema = z.array(traceNodeSchema)
const traceImpactItemSchema = z.object({
  depth: z.number().int().positive(),
  node: traceNodeSchema,
})
const traceImpactItemsSchema = z.array(traceImpactItemSchema)

type TraceNodeRecord = z.infer<typeof traceNodeSchema>

type TraceErrorCode = "binary_missing" | "command_failed" | "invalid_output"

export class CodeTraceError extends Error {
  readonly code: TraceErrorCode
  readonly details: Record<string, unknown> | null

  constructor(code: TraceErrorCode, message: string, details: Record<string, unknown> | null = null) {
    super(message)
    this.code = code
    this.details = details
  }
}

export type TraceCaller = {
  id: string
  kind: string
  name: string
  filePath: string
  range: z.infer<typeof rangeSchema> | null
}

export type TraceCallersInput = {
  symbol?: string
  nodeId?: string
  limit?: number
}

export type TraceMode = "callers" | "impact"

export type TraceGraphNode = TraceCaller & {
  depth: number
}

export type TraceGraphInput = TraceCallersInput & {
  mode?: TraceMode
  depth?: number
}

const parseRange = (rangeJson: string): z.infer<typeof rangeSchema> | null => {
  let parsed: unknown
  try {
    parsed = JSON.parse(rangeJson) as unknown
  } catch {
    return null
  }

  const result = rangeSchema.safeParse(parsed)
  if (!result.success) {
    return null
  }

  return result.data
}

const normalizeNode = (node: TraceNodeRecord): TraceCaller => ({
  id: node.id,
  kind: node.kind,
  name: node.name,
  filePath: node.filePath,
  range: parseRange(node.rangeJson),
})

const resolveConfigPath = () => resolveCodeIntelConfigPath()

const normalizeStderr = (stderr: string | undefined) => {
  const trimmed = stderr?.trim()
  if (!trimmed) {
    return null
  }

  return trimmed.slice(0, 1_500)
}

export const traceGraph = async (input: TraceGraphInput): Promise<TraceGraphNode[]> => {
  const rootDir = resolveCodeIntelRoot()
  const hasNodeId = Boolean(input.nodeId && input.nodeId.trim().length > 0)
  const symbol = input.symbol?.trim()
  const nodeId = input.nodeId?.trim()
  const mode = input.mode ?? "callers"

  if (!hasNodeId && !symbol) {
    throw new CodeTraceError("command_failed", "A symbol or nodeId is required.", null)
  }

  const args: string[] = ["trace", mode]
  if (!hasNodeId && symbol) {
    args.push(symbol)
  }

  if (hasNodeId && nodeId) {
    args.push("--node-id", nodeId)
  }

  if (input.limit) {
    args.push("--limit", String(input.limit))
  }

if (mode === "impact" && input.depth) {
  args.push("--depth", String(input.depth))
}

args.push("--config", resolveConfigPath(), "--json")

try {
  const { stdout } = await execFileAsync("ci", args, {
    cwd: rootDir,
    timeout: 30_000,
    maxBuffer: 4 * 1024 * 1024,
  })

  let parsed: unknown
  try {
    parsed = JSON.parse(stdout)
  } catch {
    throw new CodeTraceError("invalid_output", "Failed to parse trace output JSON.", {
      preview: stdout.slice(0, 1_000),
    })
  }

  if (mode === "impact") {
    const validatedImpact = traceImpactItemsSchema.safeParse(parsed)
    if (!validatedImpact.success) {
      throw new CodeTraceError("invalid_output", "Trace output did not match expected schema.", {
        issues: validatedImpact.error.issues.map((issue) => issue.message),
      })
    }

    return validatedImpact.data.map((item) => ({
      ...normalizeNode(item.node),
      depth: item.depth,
    }))
  }

  const validatedCallers = traceNodesSchema.safeParse(parsed)
  if (!validatedCallers.success) {
    throw new CodeTraceError("invalid_output", "Trace output did not match expected schema.", {
      issues: validatedCallers.error.issues.map((issue) => issue.message),
    })
  }

  return validatedCallers.data.map((node) => ({
    ...normalizeNode(node),
    depth: 1,
  }))
} catch (error) {

    if (error instanceof CodeTraceError) {
      throw error
    }

    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: string }).code === "ENOENT"
    ) {
      throw new CodeTraceError("binary_missing", "The `ci` binary is not available on PATH.", null)
    }

    const commandError = error as { stderr?: string; message?: string }
    throw new CodeTraceError(
      "command_failed",
      `Failed to execute \`ci trace ${mode}\`.`,
      {
        message: commandError.message ?? "Unknown command failure.",
        stderr: normalizeStderr(commandError.stderr),
      },
    )
  }
}

export const traceCallers = async (input: TraceCallersInput): Promise<TraceCaller[]> => {
