const AUTO_REFRESH_MS = 8_000

export default function ObservabilityModelPage() {
  const [modelData, setModelData] = useState<ObservabilityDataModel | null>(null)
  const [service, setService] = useState("")
  const [eventName, setEventName] = useState("")
  const [pathFilter, setPathFilter] = useState("")
  const [requestId, setRequestId] = useState("")
  const [statusFilter, setStatusFilter] = useState("")
  const [since, setSince] = useState("")
  const [until, setUntil] = useState("")
  const [isLoadingModel, setIsLoadingModel] = useState(false)
  const [modelErrorMessage, setModelErrorMessage] = useState("")
  const [autoRefresh, setAutoRefresh] = useState(true)

  const loadModel = useCallback(async (opts: { quiet?: boolean } = {}) => {

  if (!opts.quiet) {
    setIsLoadingModel(true)
  }
  setModelErrorMessage("")

  try {
    const params = new URLSearchParams()
    if (service.trim()) {
      params.set("service", service.trim())
    }
    if (eventName.trim()) {
      params.set("event", eventName.trim())
    }
    if (pathFilter.trim()) {
      params.set("path", pathFilter.trim())
    }
    if (requestId.trim()) {
      params.set("requestId", requestId.trim())
    }
    const normalizedStatus = statusFilter.trim()
    if (normalizedStatus) {
      params.set("status", normalizedStatus)
    }
    const sinceIso = toIsoQuery(since)
    if (sinceIso) {
      params.set("since", sinceIso)
    }
    const untilIso = toIsoQuery(until)
    if (untilIso) {
      params.set("until", untilIso)
    }

    const response = await fetch(`/api/observability/model?${params.toString()}`, {
      method: "GET",
      headers: {
        "content-type": "application/json",
      },
    })

    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to load observability model."))
    }

    setModelData(payload as ObservabilityDataModel)
  } catch (error) {
    setModelErrorMessage(error instanceof Error ? error.message : "Failed to load observability model.")
  } finally {
    if (!opts.quiet) {
      setIsLoadingModel(false)
    }
  }
}, [

  eventName,
  pathFilter,
  requestId,
  service,
  since,
  statusFilter,
  until,
])

useEffect(() => {
  if (!autoRefresh) {
    return
  }

  const timer = window.setInterval(() => {
    void loadModel({ quiet: true })
  }, AUTO_REFRESH_MS)

  return () => {
    window.clearInterval(timer)
  }
}, [autoRefresh, loadModel])

useEffect(() => {
  void loadModel()
}, [loadModel])

const handleApplyFilters = useCallback(() => {
