}

import { redirect } from "next/navigation"

import { buildRepoMergeRequestPath } from "@/lib/gitlab/repo-route"
import { resolveMergeRequestBridgeIntegration } from "@/lib/gitlab/mr-bridge"
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { getSession } from "@/lib/session"

type MergeRequestBridgePageProps = {
  searchParams: Promise<{
    projectPath?: string | string[]
    mergeRequestIid?: string | string[]
    instance?: string | string[]
  }>
}

const pickFirst = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value[0] : value

export default async function MergeRequestBridgePage({
  searchParams,
}: MergeRequestBridgePageProps) {
  const [session, query] = await Promise.all([
    getSession(),
    searchParams,
  ])

  if (!session?.user?.id) {
    redirect("/")
  }

  const projectPath = pickFirst(query.projectPath)?.trim()
  const mergeRequestIid = pickFirst(query.mergeRequestIid)?.trim()
  if (!projectPath || !mergeRequestIid) {
    redirect("/onboarding/projects")
  }

  const requestedInstance = pickFirst(query.instance)
  const integrations = await getCachedUserIntegrations(session.user.id)
  const integration = resolveMergeRequestBridgeIntegration({
    integrations,
    projectPath,
    instanceUrl: requestedInstance,
  })

  if (!integration) {
    redirect("/onboarding/projects")
  }

  redirect(buildRepoMergeRequestPath(integration, mergeRequestIid))
}

