export const enqueueReconcileJob = async (args: { integrationId: string }) => {
  const now = new Date()
  const debounceKey = buildReconcileDebounceKey(args.integrationId)

  const [row] = await db
    .insert(indexJobs)
    .values({
      integrationId: args.integrationId,
      jobType: 'reconcile',
      debounceKey,
      status: 'pending',
      attempts: 0,
      nextAttemptAt: now,
      startedAt: null,
      finishedAt: null,
      lastError: null,
      result: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexJobs.debounceKey],
      set: {
        integrationId: args.integrationId,
        jobType: 'reconcile',
        status: 'pending',
        attempts: 0,
        nextAttemptAt: now,
        startedAt: null,
        finishedAt: null,
        lastError: null,
        result: null,
        updatedAt: now,
      },
    })
    .returning({
      id: indexJobs.id,
      debounceKey: indexJobs.debounceKey,
      status: indexJobs.status,
    })

  if (!row) {
    throw new Error('Failed to enqueue reconcile job.')
  }

  return row
}

