import { spawn } from "node:child_process"
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { createServer, Socket } from "node:net"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"
import { setTimeout as delay } from "node:timers/promises"

const bunExecutable = process.platform === "win32" ? "bun.exe" : "bun"
const cloudflaredExecutable = process.platform === "win32" ? "cloudflared.exe" : "cloudflared"
const rootDir = resolve(process.cwd())

const parseEnvFile = (filePath) => {
  const parsed = {}
  const content = readFileSync(filePath, "utf8")

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim()
    if (!line || line.startsWith("#")) {
      continue
    }

    const normalized = line.startsWith("export ") ? line.slice(7).trim() : line
    const separatorIndex = normalized.indexOf("=")
    if (separatorIndex <= 0) {
      continue
    }

    const key = normalized.slice(0, separatorIndex).trim()
    if (!key) {
      continue
    }

    let value = normalized.slice(separatorIndex + 1).trim()
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1)
    }

    parsed[key] = value
  }

  return parsed
}

const loadMergedEnv = () => {
  const env = { ...process.env }
  const rootEnvPath = resolve(rootDir, ".env")
  const tunnelEnvPath = resolve(rootDir, ".env.tunnel")

  if (existsSync(rootEnvPath)) {
    Object.assign(env, parseEnvFile(rootEnvPath))
  }

  if (existsSync(tunnelEnvPath)) {
    Object.assign(env, parseEnvFile(tunnelEnvPath))
  }

  return env
}

const env = loadMergedEnv()
const tunnelToken = env.CF_TUNNEL_TOKEN_DEV?.trim()

if (!tunnelToken) {
  console.error(
    [
      "[dev:tunnel] missing CF_TUNNEL_TOKEN_DEV.",
      "Create .env.tunnel from .env.tunnel.example and set CF_TUNNEL_TOKEN_DEV.",
    ].join("\n"),
  )
  process.exit(1)
}

const devTunnelUrl = env.DEV_TUNNEL_URL?.trim() || "http://127.0.0.1:3000"
const appUrl = env.BETTER_AUTH_URL?.trim()

if (!appUrl) {
  console.error("[dev:tunnel] missing BETTER_AUTH_URL. Set it in .env.tunnel.")
  process.exit(1)
}

let parsedTunnelUrl
try {
  parsedTunnelUrl = new URL(devTunnelUrl)
} catch {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL must be a valid URL. Received: ${devTunnelUrl}`)
  process.exit(1)
}

if (!/^https?:$/i.test(parsedTunnelUrl.protocol)) {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL must use http or https. Received: ${devTunnelUrl}`)
  process.exit(1)
}

const originHost = parsedTunnelUrl.hostname || "127.0.0.1"
const originPort =
  parsedTunnelUrl.port
    ? Number.parseInt(parsedTunnelUrl.port, 10)
    : parsedTunnelUrl.protocol === "https:"
      ? 443
      : 80

if (!Number.isFinite(originPort) || originPort <= 0) {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL port is invalid. Received: ${devTunnelUrl}`)
  process.exit(1)
}

const children = []
let shuttingDown = false
let tokenFileDir = null

const stopAll = (signal = "SIGTERM") => {
  if (shuttingDown) {
    return
  }
  shuttingDown = true

  if (tokenFileDir) {
    rmSync(tokenFileDir, { recursive: true, force: true })
    tokenFileDir = null
  }

  for (const child of children) {
    if (!child.killed) {
      child.kill(signal)
    }
  }
}

const spawnManaged = ({ name, executable, args, childEnv }) => {
  const child = spawn(executable, args, {
    cwd: rootDir,
    stdio: "inherit",
    env: childEnv,
  })

  child.on("exit", (code, signal) => {
    if (shuttingDown) {
      return
    }

    console.error(
      `[dev:tunnel] ${name} exited ${signal ? `with signal ${signal}` : `with code ${code}`}`,
    )
    stopAll(signal ?? "SIGTERM")
    process.exit(code ?? 1)
  })

  child.on("error", (error) => {
    console.error(`[dev:tunnel] failed to start ${name}:`, error)
    stopAll()
    process.exit(1)
  })

  children.push(child)
  return child
}

const ensurePortAvailable = (port) =>
  new Promise((resolveAvailable, rejectUnavailable) => {
    const server = createServer()

    server.once("error", (error) => {
      if (error && typeof error === "object" && "code" in error && error.code === "EADDRINUSE") {
        rejectUnavailable(
          new Error(`[dev:tunnel] port ${port} is already in use. Stop the existing process and retry.`),
        )
        return
      }

      rejectUnavailable(error)
    })

    server.listen(port, () => {
      server.close(() => resolveAvailable())
    })
  })

const waitForOriginReady = async (host, port, timeoutMs = 60_000) => {
  const startedAt = Date.now()

  while (Date.now() - startedAt < timeoutMs) {
    const opened = await new Promise((resolveOpen) => {
      const socket = new Socket()
      let settled = false

      const finalize = (value) => {
        if (!settled) {
          settled = true
          resolveOpen(value)
        }
      }

      socket.setTimeout(500)
      socket.once("connect", () => {
        socket.destroy()
        finalize(true)
      })
      socket.once("timeout", () => {
        socket.destroy()
        finalize(false)
      })
      socket.once("error", () => finalize(false))
      socket.connect(port, host)
    })

    if (opened) {
      return
    }

    await delay(250)
  }

  throw new Error(`[dev:tunnel] timed out waiting for web origin at ${host}:${port}.`)
}

const run = async () => {
  await ensurePortAvailable(originPort)

  const webEnv = { ...env }
  delete webEnv.CF_TUNNEL_TOKEN_DEV

  const tunnelEnv = { ...env }
  delete tunnelEnv.CF_TUNNEL_TOKEN_DEV

  tokenFileDir = mkdtempSync(join(tmpdir(), "argus-tunnel-"))
  const tokenFilePath = join(tokenFileDir, "token")
  writeFileSync(tokenFilePath, `${tunnelToken}\n`, {
    encoding: "utf8",
    mode: 0o600,
  })

  spawnManaged({
    name: "web",
    executable: bunExecutable,
    args: [
      "run",
      "--cwd",
      "apps/web",
      "dev",
      "--",
      "--webpack",
      "--hostname",
      originHost,
      "--port",
      String(originPort),
    ],
    childEnv: webEnv,
  })

  await waitForOriginReady(originHost, originPort)

  spawnManaged({
    name: "cloudflared",
    executable: cloudflaredExecutable,
    args: ["tunnel", "run", "--token-file", tokenFilePath, "--url", devTunnelUrl],
    childEnv: tunnelEnv,
  })

  console.log(`[dev:tunnel] BETTER_AUTH_URL=${appUrl}`)
  console.log(`[dev:tunnel] DEV_TUNNEL_URL=${devTunnelUrl}`)
}

run().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error))
  stopAll()
  process.exit(1)
})

process.once("SIGINT", () => {
  stopAll("SIGINT")
  process.exit(0)
})

process.once("SIGTERM", () => {
  stopAll("SIGTERM")
  process.exit(0)
})

