      code: 'INDEX_JOB_FAILED',
      why: status ? `Job moved to ${status}.` : 'Job failure status was not persisted.',
      fix: 'Inspect job payload and processor path for deterministic retries.',
      details: {
        outcome: 'failed',
        failureStatus: status ?? 'unknown',
      },
    })
  } finally {
    jobLog.emit({
      status: jobStatus,
      durationMs: Date.now() - jobStartedAt,
    })
  }
}

const claimedRuns = await claimPlannedRuns(normalizedBatchSize)
summary.claimed = claimedRuns.length
batchLog.set({
  runsClaimed: claimedRuns.length,
})

for (const run of claimedRuns) {
  const runLog = createRunnerScopedLogger({
    method: 'INGEST',
    path: '/workers/indexer/runs/ingest',
    requestId: run.id,
  })
  const runStartedAt = Date.now()

runLog.set({
  event: 'indexer.run.processing',
  batchId: options.batchId ?? null,
  runId: run.id,
  integrationId: run.integrationId,
  branch: run.branch,
  configHash: run.configHash,
  headSha: run.headSha,
})

let runStatus = 500
let runMetrics: {
  durationMs: number | null
  filesProcessed: number
  failures: number
  embeddingApiCalls: number
  pendingJobs: number | null
  processingJobs: number | null
  embeddingPromptTokens: number
  embeddingTotalTokens: number
  embeddingCostUsd: number | null
} | null = null
try {
  const result = await processIngestJob({ runId: run.id })
  runMetrics = result.indexingMetrics

  if (result.status === 'ready') {
    summary.ready += 1
  } else if (result.status === 'failed') {
    summary.failed += 1
  } else if (result.status === 'superseded') {
    summary.superseded += 1
  } else {
    summary.skipped += 1
  }
  if (result.modeFallbackReason) {
    summary.deltaFallbacks += 1
    summary.deltaFallbackReasons[result.modeFallbackReason] =
      (summary.deltaFallbackReasons[result.modeFallbackReason] ?? 0) + 1
  }
  if (result.finalizeStatus === 'invalid_state' || result.finalizeStatus === 'not_found') {
    summary.finalizeFailures += 1
  }
  if (result.gcStatus === 'failed') {
    summary.gcFailures += 1
  }

} catch (error) {
  const errorToLog = toError(error, 'Unexpected ingest run processing error.')
  const errorPayload = {
    code: 'INGEST_RUN_FAILED',
    message: errorToLog.message.slice(0, 500),
    stack: errorToLog.stack?.slice(0, 1_000) ?? null,
  }
  summary.failed += 1
  runLog.set({
    outcome: 'failed',
    statusTransitionFrom: 'planned',
    statusTransitionTo: 'failed',
    errorCode: errorPayload.code,
    errorMessage: errorPayload.message,
    errorDetails: null,
    finalizeStatus: null,
    gcStatus: 'not_applicable',
    indexingMetrics: runMetrics,
  })

  try {
    await markIndexRunFailed(run.id, errorPayload)
  } catch (markError) {
    const markErrorToLog = toError(markError, 'Failed to persist ingest run failure.')
    logRunnerScopedError(runLog, markErrorToLog, {
      code: 'INGEST_RUN_MARK_FAILED',
      why: 'Ingest processor threw and the run failure state could not be persisted.',
      fix: 'Inspect index_runs write path and database availability.',
    })
  }

  logRunnerScopedError(runLog, errorToLog, {
    code: 'INGEST_RUN_FAILED',
    why: 'Ingest processor threw before finalize.',
    fix: 'Inspect ingest worker dependencies and run context for this run id.',
  })
  runStatus = 500
} finally {

    const runDurationMs = Date.now() - runStartedAt
    if (runMetrics) {
      runLog.set({
        indexingMetrics: {
          ...runMetrics,
          durationMs: runDurationMs,
        },
      })
    }
    runLog.emit({
      status: runStatus,
      durationMs: runDurationMs,
    })
  }
}

const hasFailures = summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
try {
  summary.queueDepthAfter = await getQueueDepthSnapshot()
  batchLog.set({
    queueDepthAfter: summary.queueDepthAfter,
  })
} catch (error) {
  const errorToLog = toError(error, 'Unexpected queue depth snapshot processing error.')
  logRunnerScopedError(batchLog, errorToLog, {
    code: 'INDEXER_QUEUE_DEPTH_AFTER_FAILED',
    why: 'Failed to read queue depth snapshot after batch processing.',
    fix: 'Inspect index_jobs/index_runs queries and database connectivity.',
  })
}
batchLog.set({
  outcome: hasFailures ? 'partial_failure' : 'success',
})
if (hasFailures) {
  batchStatus = 207
}

return summary

  } finally {
    const durationMs = Date.now() - startedAt
    const indexingFailures =
      summary.failed + summary.jobsFailed + summary.jobsDead + summary.embeddingFailures
    batchLog.set({
      durationMs,
      summary,
      indexingMetrics: {
        durationMs,
        filesProcessed: summary.filesProcessed,
        failures: indexingFailures,
        embeddingApiCalls: summary.embeddingApiCalls,
        pendingJobs: summary.queueDepthAfter?.jobsPending ?? null,
        processingJobs: summary.queueDepthAfter?.jobsProcessing ?? null,
      },
      llmMetrics: {
        provider: resolveEmbeddingProviderLabel(),
        model: resolveEmbeddingModelLabel(),
        promptTokens: summary.embeddingPromptTokens,
        completionTokens: 0,
        totalTokens: summary.embeddingTotalTokens,
        latencyMs: null,
        costUsd: Number(summary.embeddingCostUsd.toFixed(8)),
        requestCount: summary.embeddingApiCalls,
      },
    })
    batchLog.emit({
      status: batchStatus,
      durationMs,
    })
  }
}

export type WorkerRunner = () => Promise<void>

export type ModuleImporter = (moduleId: string) => Promise<unknown>

type WorkerModule = {
  runIndexerWorker?: WorkerRunner
}

export const DEFAULT_INDEXER_RUNTIME_MODULE = "@argus/service-web/indexer-runtime"

export const loadWorkerRunner = async ({
  moduleId = DEFAULT_INDEXER_RUNTIME_MODULE,
  importModule = (importId: string) => import(importId),
}: {
  moduleId?: string
  importModule?: ModuleImporter
} = {}): Promise<WorkerRunner> => {
  const workerModule = (await importModule(moduleId)) as WorkerModule
  const runIndexerWorker = workerModule.runIndexerWorker
  if (typeof runIndexerWorker !== "function") {
    throw new Error(
      `[service-indexer] worker module did not export runIndexerWorker: ${moduleId}`,
    )
  }
  return runIndexerWorker
}

export const runIndexerService = async ({
  loadRunner = () => loadWorkerRunner(),
}: {
  loadRunner?: () => Promise<WorkerRunner>
} = {}) => {
  const runWorker = await loadRunner()
  await runWorker()
}

export const runIndexerServiceCli = async ({
  runService = () => runIndexerService(),
  logError = (...args: unknown[]) => {
    console.error(...args)
  },
  exit = (code: number) => {
    process.exit(code)
  },
}: {
  runService?: () => Promise<void>
  logError?: (...args: unknown[]) => void
  exit?: (code: number) => void
} = {}) => {
  try {
    await runService()
  } catch (error) {
    logError("[service-indexer] worker execution failed:", error)
    exit(1)
  }
}

import { describe, expect, test } from "bun:test"

import {
