import { afterEach, describe, expect, mock, test } from "bun:test"

type LoggerContext = Record<string, unknown>

type ApiLogHandlerArgs = {
  logger: {
    set: (context: LoggerContext) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

const withEnv = async <T>(
  overrides: Partial<NodeJS.ProcessEnv>,
  fn: () => Promise<T> | T,
) => {
  const previous = new Map<string, string | undefined>()
  for (const [key, value] of Object.entries(overrides)) {
    previous.set(key, process.env[key])
    if (value === undefined) {
      delete process.env[key]
    } else {
      process.env[key] = value
    }
  }

  try {
    return await fn()
  } finally {
    for (const [key, value] of previous.entries()) {
      if (value === undefined) {
        delete process.env[key]
      } else {
        process.env[key] = value
      }
    }
  }
}

const originalFetch = globalThis.fetch

afterEach(() => {
  globalThis.fetch = originalFetch
})

const loadRouteModule = async (userId: string | null = "user-1") => {
  const loggerContext: LoggerContext = {}

  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: (context: LoggerContext) => {
        Object.assign(loggerContext, context)
      },
    }
    const result = await handler({ logger, requestId: "req_1" })
    return result.response
  })

  const getSessionUserId = mock(async () => userId)

  mock.module("@/lib/session", () => ({
    getSessionUserId,
    getSession: async () => {
      const userId = await getSessionUserId()
      return userId ? { user: { id: userId } } : null
    },
    getSessionAccess: async () => {
      const userId = await getSessionUserId()
      return {
        session: userId ? { user: { id: userId } } : null,
        isAlphaDenied: false,
      }
    },
  }))
  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
    logScopedError: mock(() => {}),
  }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    POST: routeModule.POST as (request: Request) => Promise<Response>,
    loggerContext,
  }
}

const setMockProviderResponse = (payload: unknown, status = 200) => {
  const fetchMock = mock(async () =>
    new Response(JSON.stringify(payload), {
      status,
      headers: {
        "content-type": "application/json",
      },
    }),
  )
  globalThis.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

const setMockProviderRejected = (error: unknown) => {
  const fetchMock = mock(async () => {
    throw error
  })
  globalThis.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

describe("ai test connection route", () => {
  test("rejects unauthorized requests", async () => {
    const { POST } = await loadRouteModule(null)

    const response = await POST(
      new Request("http://localhost/api/ai/test", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          apiUrl: "https://api.openai.com/v1",
          model: "gpt-4o-mini",
          token: "secret",
        }),
      }),
    )

    expect(response.status).toBe(401)
  })

test("validates payload and URL", async () => {
  const { POST } = await loadRouteModule()

  const missingFieldResponse = await POST(
    new Request("http://localhost/api/ai/test", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ apiUrl: "https://api.openai.com/v1" }),
    }),
  )
  expect(missingFieldResponse.status).toBe(400)

  const invalidUrlResponse = await POST(
    new Request("http://localhost/api/ai/test", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        apiUrl: "file:///tmp/ai",
        model: "gpt-4o-mini",
        token: "secret",
      }),
    }),
  )
  const invalidUrlBody = await invalidUrlResponse.json()

  expect(invalidUrlResponse.status).toBe(400)
  expect(invalidUrlBody.error).toBe("API URL must use http or https.")

  const privateUrlResponse = await POST(
    new Request("http://localhost/api/ai/test", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        apiUrl: "http://127.0.0.1:11434/v1",
        model: "gpt-4o-mini",
        token: "secret",
      }),
    }),
  )
  const privateUrlBody = await privateUrlResponse.json()

  expect(privateUrlResponse.status).toBe(400)
  expect(privateUrlBody.error).toBe("API URL must not target localhost or private network hosts.")
})

test("requires token when payload and env are empty", async () =>
  withEnv(
    {
      AI_API_TOKEN: undefined,
      OPENAI_API_KEY: undefined,
    },
    async () => {
      const { POST } = await loadRouteModule()

      const response = await POST(
        new Request("http://localhost/api/ai/test", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            apiUrl: "https://api.openai.com/v1",
            model: "gpt-4o-mini",
            token: "",
          }),
        }),
      )
      const body = await response.json()

      expect(response.status).toBe(400)
      expect(body.error).toBe("AI token missing. Set API token in settings or server env.")
    },
  ))

test("tests provider connectivity and reports latency", async () =>
  withEnv(
    {
      AI_API_TOKEN: undefined,
      OPENAI_API_KEY: undefined,
    },
    async () => {
      const fetchMock = setMockProviderResponse({ choices: [{ message: { content: "OK" } }] }, 200)
      const { POST, loggerContext } = await loadRouteModule()

      const response = await POST(
        new Request("http://localhost/api/ai/test", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            apiUrl: "https://api.openai.com/v1/",
            model: "gpt-4o-mini",
            token: "client-token",
          }),
        }),
      )
      const body = await response.json()

      expect(response.status).toBe(200)
      expect(body.ok).toBe(true)
      expect(typeof body.data.latencyMs).toBe("number")
      expect(body.data.latencyMs).toBeGreaterThanOrEqual(1)

      const [url, init] = fetchMock.mock.calls[0] as [string, RequestInit]
      expect(url).toBe("https://api.openai.com/v1/chat/completions")
      expect((init.headers as Record<string, string>).authorization).toBe("Bearer client-token")
      expect(loggerContext.model).toBe("gpt-4o-mini")
    },
  ))

test("falls back to env token and surfaces upstream errors", async () =>
  withEnv(
    {
      AI_API_TOKEN: "env-token",
      OPENAI_API_KEY: undefined,
    },
    async () => {
      const fetchMock = setMockProviderResponse(
        {
          error: {
            message: "Invalid API key",
          },
        },
        401,
      )
      const { POST, loggerContext } = await loadRouteModule()

      const response = await POST(
        new Request("http://localhost/api/ai/test", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            apiUrl: "https://api.openai.com/v1",
            model: "gpt-4o-mini",
          }),
        }),
      )
      const body = await response.json()

      expect(response.status).toBe(502)
      expect(body.providerStatus).toBe(401)
      expect(body.error).toContain("Connection failed (401)")
      expect(body.error).toContain("Invalid API key")

      const [, init] = fetchMock.mock.calls[0] as [string, RequestInit]
      expect((init.headers as Record<string, string>).authorization).toBe("Bearer env-token")
      expect(loggerContext.providerStatus).toBe(401)
    },
  ))

test("requires explicit token when API URL differs from server provider URL", async () =>
  withEnv(
    {
      AI_API_URL: "https://api.openai.com/v1",
      AI_API_TOKEN: "env-token",
      OPENAI_API_KEY: undefined,
    },
    async () => {
      const fetchMock = setMockProviderResponse({ choices: [{ message: { content: "OK" } }] }, 200)
      const { POST } = await loadRouteModule()

      const response = await POST(
        new Request("http://localhost/api/ai/test", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            apiUrl: "https://attacker.example/v1",
            model: "gpt-4o-mini",
          }),
        }),
      )
      const body = await response.json()

      expect(fetchMock).not.toHaveBeenCalled()
      expect(response.status).toBe(400)
      expect(body.error).toBe("Custom API URL requires an explicit token.")
    },
  ))

  test("returns network failure when provider fetch throws", async () => {
    const fetchMock = setMockProviderRejected(new TypeError("fetch failed"))
    const { POST } = await loadRouteModule()

    const response = await POST(
      new Request("http://localhost/api/ai/test", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
