import { useEffect, useRef } from "react"

import type {
  OnboardingRouteStep,
  OnboardingTrackedEvent,
} from "@/components/onboarding/onboarding-types"

type UseOnboardingStartedTrackingOptions = {
  isHydrated: boolean
  routeStep: OnboardingRouteStep
  trackEvent: (
    event: OnboardingTrackedEvent,
    metadata?: Record<string, unknown>,
  ) => void
}

export function useOnboardingStartedTracking({
  isHydrated,
  routeStep,
  trackEvent,
}: UseOnboardingStartedTrackingOptions) {
  const startedEventTracked = useRef(false)

  useEffect(() => {
    if (!isHydrated) {
      return
    }
    if (routeStep !== "tokens") {
      return
    }
    if (startedEventTracked.current) {
      return
    }

    startedEventTracked.current = true
    trackEvent("onboarding_started")
  }, [isHydrated, routeStep, trackEvent])
}

import type { FileDiffMetadata } from "@pierre/diffs"
import { useMemo } from "react"

import {
  getFileLabel,
  INITIAL_FILE_BATCH_SIZE,
  type DiffDataSource,
  type DiffLoadProfile,
} from "../merge-request-diff-viewer.utils"

type UseMergeRequestDiffDerivedOptions = {
  parsedFiles: FileDiffMetadata[]
  filenameFilter: string
  patchText: string
  visibleResetToken: number
  visibleWindow: { key: string; count: number }
  dataSource: DiffDataSource | null
  loadProfile: DiffLoadProfile
}

export function useMergeRequestDiffDerived({
  parsedFiles,
  filenameFilter,
  patchText,
  visibleResetToken,
  visibleWindow,
  dataSource,
  loadProfile,
}: UseMergeRequestDiffDerivedOptions) {
  const normalizedFilter = filenameFilter.trim().toLowerCase()

  const filteredFiles = useMemo(() => {
    if (!normalizedFilter) {
      return parsedFiles
    }

    return parsedFiles.filter((file) => {
      const label = getFileLabel(file).toLowerCase()
      return label.includes(normalizedFilter)
    })
  }, [normalizedFilter, parsedFiles])

  const totals = useMemo(
    () =>
      filteredFiles.reduce(
        (accumulator, file) => {
          for (const hunk of file.hunks) {
            accumulator.additions += hunk.additionLines
            accumulator.deletions += hunk.deletionLines
          }
          return accumulator
        },
        { additions: 0, deletions: 0 },
      ),
    [filteredFiles],
  )

  const visibleWindowKey = `${visibleResetToken}:${normalizedFilter}:${patchText}`

  const visibleFileCount =
    visibleWindow.key === visibleWindowKey
      ? visibleWindow.count
      : INITIAL_FILE_BATCH_SIZE

  const visibleFiles = filteredFiles.slice(0, visibleFileCount)
  const canLoadMore = visibleFileCount < filteredFiles.length

  const loadProfileSummary = useMemo(() => {
    if (!dataSource || loadProfile.fetchMs == null) {
      return ""
    }

    const parts = [
      `Source: ${dataSource === "changes" ? "changes" : "raw_diffs"}`,
      `fetch ${loadProfile.fetchMs}ms`,
    ]
    if (loadProfile.firstParseMs != null) {
      parts.push(`first parse ${loadProfile.firstParseMs}ms`)
    }
    if (loadProfile.fullParseMs != null) {
      parts.push(`full parse ${loadProfile.fullParseMs}ms`)
    }
    return parts.join(" · ")
  }, [dataSource, loadProfile.fetchMs, loadProfile.firstParseMs, loadProfile.fullParseMs])

  return {
    filteredFiles,
    totals,
    visibleWindowKey,
    visibleFileCount,
    visibleFiles,
    canLoadMore,
    loadProfileSummary,
  }
}

import { describe, expect, mock, test } from "bun:test"

import {
  getCachedUserIntegrations,
  invalidateUserIntegrations,
} from "@/lib/gitlab/user-integrations-cache"

type IntegrationRow = {
  id: string
  projectId: string
}

describe("user integrations cache", () => {
  test("reuses cached integrations for repeated reads", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-1", projectId: "p-1" } as IntegrationRow])

    const first = await getCachedUserIntegrations("user-1", { load })
    const second = await getCachedUserIntegrations("user-1", { load })

    expect(first).toEqual([{ id: "int-1", projectId: "p-1" }])
    expect(second).toEqual(first)
    expect(load).toHaveBeenCalledTimes(1)
  })

  test("invalidates a single user cache entry", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-2", projectId: "p-2" } as IntegrationRow])

    await getCachedUserIntegrations("user-2", { load })
    expect(load).toHaveBeenCalledTimes(1)

    const invalidated = invalidateUserIntegrations("user-2")
    expect(invalidated).toBe(1)

    await getCachedUserIntegrations("user-2", { load })
    expect(load).toHaveBeenCalledTimes(2)
  })

  test("returns empty array for blank user ids", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-3", projectId: "p-3" } as IntegrationRow])

    const value = await getCachedUserIntegrations("   ", { load })

    expect(value).toEqual([])
    expect(load).toHaveBeenCalledTimes(0)
  })
})

import { stdin as input, stdout as output } from 'node:process'
import { createInterface } from 'node:readline/promises'
import { fileURLToPath } from 'node:url'

import { Client } from 'pg'

import { resolveDatabaseUrl } from './db-bootstrap'

const CONFIRMATION_PHRASE = 'WIPE'
const DRIZZLE_MIGRATIONS_TABLE = '__drizzle_migrations'

type TableRow = {
  table_schema: string
  table_name: string
}

type WipeLogger = Pick<Console, 'log'>

type RunDbWipeOptions = {
  databaseUrl?: string
  force?: boolean
  logger?: WipeLogger
}

const quoteIdentifier = (identifier: string): string => `"${identifier.replaceAll('"', '""')}"`

const formatTableName = (schema: string, table: string): string =>
  `${quoteIdentifier(schema)}.${quoteIdentifier(table)}`

const confirmWipe = async (force: boolean): Promise<void> => {
  if (force) {
    return
  }

  if (!input.isTTY || !output.isTTY) {
    throw new Error('[db:wipe] Interactive terminal required. Use --yes to skip confirmation.')
  }

  const rl = createInterface({ input, output })

  try {
    output.write(
      '[db:wipe] This will permanently delete all rows from all non-system tables (except __drizzle_migrations).\n',
    )
    const answer = await rl.question(`[db:wipe] Type "${CONFIRMATION_PHRASE}" to continue: `)
    if (answer.trim() !== CONFIRMATION_PHRASE) {
      throw new Error('[db:wipe] Aborted by user.')
    }
  } finally {
    rl.close()
  }
}

export const runDbWipe = async (options: RunDbWipeOptions = {}): Promise<void> => {
  const databaseUrl = options.databaseUrl ?? resolveDatabaseUrl()
  const force = options.force ?? false
  const logger = options.logger ?? console

  await confirmWipe(force)

  const client = new Client({ connectionString: databaseUrl })
  await client.connect()

  try {
    const tables = await client.query<TableRow>(
      `
        select table_schema, table_name
        from information_schema.tables
        where table_type = 'BASE TABLE'
          and table_schema not in ('pg_catalog', 'information_schema')
          and table_name <> $1
        order by table_schema, table_name
      `,
      [DRIZZLE_MIGRATIONS_TABLE],
    )

    if (tables.rows.length === 0) {
      logger.log('[db:wipe] No tables found to truncate.')
      return
    }

    const targetTables = tables.rows.map((table) => formatTableName(table.table_schema, table.table_name))
    await client.query(`truncate table ${targetTables.join(', ')} restart identity cascade`)

    logger.log(`[db:wipe] Truncated ${targetTables.length} table(s).`)
  } finally {
    await client.end()
  }
}

const isDirectExecution = (() => {
  const entrypointPath = process.argv[1]
  if (!entrypointPath) {
    return false
  }

  try {
    return fileURLToPath(import.meta.url) === entrypointPath
  } catch {
    return false
  }
})()

if (isDirectExecution) {
  const force = process.argv.includes('--yes') || process.argv.includes('-y')

  runDbWipe({ force }).catch((error) => {
    console.error('[db:wipe] failed', error)
    process.exit(1)
  })
}

