}

/* ── React Flow overrides ── */

/* Reset ALL node wrappers — custom nodes own their chrome */
.react-flow__node {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  color: inherit !important;
}

/* Kill default selection outline — custom nodes handle their own */
.react-flow__node.selected,
.react-flow__node.selected:focus,
.react-flow__node.selected:focus-visible,
.react-flow__node:focus,
.react-flow__node:focus-visible,
.react-flow__node.selectable.selected,
.react-flow__node.selectable:focus,
.react-flow__node.selectable:focus-visible {
  box-shadow: none !important;
  outline: none !important;
}

/* Make handles always visible (not just when connecting) */
.react-flow__handle {
  pointer-events: all !important;
  cursor: crosshair;
  opacity: 1 !important;
}

/* Edge hover glow */
.react-flow__edge-path {
  stroke: rgba(216, 191, 123, 0.95) !important;
  stroke-width: 2.5 !important;
  opacity: 1 !important;
  fill: none;
  transition: stroke 0.2s ease;
}

.react-flow__edge:hover .react-flow__edge-path {
  stroke: rgba(236, 212, 148, 1) !important;
  filter: drop-shadow(0 0 4px rgba(236, 212, 148, 0.75));
}

/* Connection line while dragging */
.react-flow__connection-path {
