import { describe, expect, mock, test } from "bun:test"

type LoggerContext = Record<string, unknown>

type ApiLogHandlerArgs = {
  logger: {
    set: (context: LoggerContext) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

const loadRouteModule = async (options?: {
  userId?: string | null
  rows?: Array<{
    userId: string
    event: string
    createdAt: Date
    metadata?: Record<string, unknown>
  }>
}) => {
  const loggerContext: LoggerContext = {}
  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: (context: LoggerContext) => {
        Object.assign(loggerContext, context)
      },
    }
    const result = await handler({ logger, requestId: "req_1" })
    return result.response
  })

  const getSessionUserId = mock(async () =>
    options?.userId === undefined ? "user-1" : options.userId,
  )

  const orderBy = mock(async () => options?.rows ?? [])
  const where = mock(() => ({ orderBy }))
  const from = mock(() => ({ where }))
  const select = mock(() => ({ from }))

  mock.module("drizzle-orm", () => ({
    asc: (value: unknown) => value,
    gte: () => ({ __gte: true }),
  }))

  mock.module("@/lib/session", () => ({
    getSessionUserId,
    getSession: async () => {
      const userId = await getSessionUserId()
      return userId ? { user: { id: userId } } : null
    },
    getSessionAccess: async () => {
      const userId = await getSessionUserId()
      return {
        session: userId ? { user: { id: userId } } : null,
        isAlphaDenied: false,
      }
    },
  }))
  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
    logScopedError: mock(() => {}),
  }))
  mock.module("@/lib/db", () => ({ db: { select } }))
  mock.module("@/lib/db/schema", () => ({
    onboardingEvents: {
      userId: "user_id",
      event: "event",
      createdAt: "created_at",
      metadata: "metadata",
    },
  }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    GET: routeModule.GET as (request: Request) => Promise<Response>,
    loggerContext,
    select,
  }
}

describe("onboarding ttfr route", () => {
  test("returns 401 when unauthenticated", async () => {
    const { GET, select } = await loadRouteModule({ userId: null })

    const response = await GET(new Request("http://localhost/api/observability/onboarding-ttfr"))
    const body = await response.json()

    expect(response.status).toBe(401)
    expect(body).toEqual({ error: "Unauthorized" })
    expect(select).toHaveBeenCalledTimes(0)
  })

  test("aggregates p50/p95 TTFR by instance", async () => {
    const startedAt = new Date("2026-02-16T10:00:00.000Z")
    const openedAt = new Date("2026-02-16T10:00:08.000Z")

    const { GET, loggerContext } = await loadRouteModule({
      rows: [
        {
          userId: "u1",
          event: "onboarding_started",
          createdAt: startedAt,
          metadata: {
            instanceUrl: "https://us.global.lmco.com",
          },
        },
        {
          userId: "u1",
          event: "onboarding_review_opened",
          createdAt: openedAt,
          metadata: {
            projectId: "p1",
          },
        },
      ],
    })

    const response = await GET(new Request("http://localhost/api/observability/onboarding-ttfr"))
    const body = await response.json()

    expect(response.status).toBe(200)
    expect(body.summary).toMatchObject({
      totalSessions: 1,
      sessionsWithTtfr: 1,
      p50Ms: 8000,
      p95Ms: 8000,
      sloBreached: false,
    })
    expect(body.byInstance).toEqual([
      {
        instance: "US",
        count: 1,
        p50Ms: 8000,
        p95Ms: 8000,
        sloBreached: false,
      },
    ])
    expect(loggerContext).toMatchObject({
      sessions: 1,
      sessionsWithTtfr: 1,
      overallP95: 8000,
      alertCount: 0,
    })
  })
})

import { describe, expect, test } from "bun:test"
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs"
import os from "node:os"
import path from "node:path"

import { resolveCodeIntelRootFrom } from "./code-intel-root"

describe("resolveCodeIntelRootFrom", () => {
  test("returns cwd when argus-search.json exists in cwd", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-cwd-"))
    try {
      writeFileSync(path.join(tmp, "argus-search.json"), "{}", "utf8")
      expect(resolveCodeIntelRootFrom(tmp)).toBe(tmp)
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })

  test("walks up to parent when config is not in cwd", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-parent-"))
    const nested = path.join(tmp, "apps", "web")
    try {
      mkdirSync(nested, { recursive: true })
      writeFileSync(path.join(tmp, "argus-search.json"), "{}", "utf8")
      expect(resolveCodeIntelRootFrom(nested)).toBe(tmp)
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })

  test("throws when config cannot be found", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-missing-"))
    try {
      expect(() => resolveCodeIntelRootFrom(tmp)).toThrow(
        "Could not locate argus-search.json",
      )
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })
})

