import {
  index,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import { user } from "./auth";

export const onboardingEventEnum = pgEnum("onboarding_event", [
  "onboarding_started",
  "onboarding_token_validated",
  "onboarding_projects_ready",
  "onboarding_projects_selected",
  "onboarding_mrs_ready",
  "onboarding_review_opened",
  "onboarding_quick_review_output",
  "onboarding_full_review_ready",
  "onboarding_completed",
]);

export type OnboardingEventMetadata = {
  instanceUrl?: string;
  selectedProjectCount?: number;
  projectId?: string;
  mergeRequestId?: string;
  mergeRequestCount?: number;
  errorCode?: string;
  reviewMode?: "quick" | "full";
  completionSource?: "merge_request_selection" | "first_ai_review" | "manual";
  findingsCount?: number;
  onboardingStartedAt?: string;
  onboardingCompletedAt?: string;
  onboardingDurationMs?: number;
};

export const onboardingEvents = pgTable(
  "onboarding_events",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    event: onboardingEventEnum("event").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    metadata: jsonb("metadata").$type<OnboardingEventMetadata>(),
  },
  (table) => [
    index("onboarding_events_user_id_idx").on(table.userId),
    index("onboarding_events_event_idx").on(table.event),
    index("onboarding_events_created_at_idx").on(table.createdAt),
  ],
);

