const TIMELINE_STEPS: TimelineStep[] = [
  {
    key: "chunking",
    label: "Queue Batches",
    description: "Split changed files into reviewable batches.",
  },
  {
    key: "analyzing",
    label: "Analyze Changes",
    description: "Run AI over each batch of files.",
  },
  {
    key: "mapping",
    label: "Map Findings",
    description: "Attach findings to files and line ranges.",
  },
  {
    key: "done",
    label: "Complete",
    description: "Summarize output and severity counts.",
  },
]

const STAGE_ORDER: ReviewRunStage[] = [
  "idle",
  "chunking",
  "analyzing",
  "mapping",
  "done",
  "failed",
]

/* ─── helpers ─── */

const stageRank = (stage: ReviewRunStage) => STAGE_ORDER.indexOf(stage)

const getStepStatus = ({
  step,
  stage,
  hasError,
}: {
  step: TimelineStep["key"]
  stage: ReviewRunStage
  hasError: boolean
}): StepStatus => {
  if (hasError || stage === "failed") {
    if (step === "analyzing") return "error"
    if (step === "chunking" && stageRank(stage) > stageRank("chunking")) return "complete"
    return "pending"
  }
  if (stage === step) return "current"
  if (step === "done" && stage === "done") return "complete"
  if (stageRank(stage) > stageRank(step)) return "complete"
  return "pending"
}

const stepIcon = (status: StepStatus) => {
  if (status === "error") return <AlertTriangle className="size-3.5" aria-hidden="true" />
  if (status === "complete") return <CheckCircle2 className="size-3.5" aria-hidden="true" />
  if (status === "current") return <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
  return <Circle className="size-3.5" aria-hidden="true" />
}

const stepIconColor = (status: StepStatus) => {
  if (status === "error") return "text-red-500 dark:text-red-400"
  if (status === "complete") return "text-emerald-500 dark:text-emerald-400"
  if (status === "current") return "text-blue-500 dark:text-blue-400"
  return "text-muted-foreground/40"
}

const stepLineColor = (status: StepStatus) => {
  if (status === "complete") return "bg-emerald-500/30 dark:bg-emerald-400/20"
  if (status === "error") return "bg-red-500/30 dark:bg-red-400/20"
  return "bg-border/60"
}

/** Group events by the step they belong to. */
const eventsByStep = (events: ReviewRunEvent[]) => {
  const map: Record<string, ReviewRunEvent[]> = {}
  for (const event of events) {
    const key = event.stage === "failed" ? "analyzing" : event.stage
    if (!map[key]) map[key] = []
    map[key].push(event)
  }
  return map
}

/** Build a short context string for the currently active step. */

const getStepDetail = (
  step: TimelineStep["key"],
  reviewRun: ReviewRunState,
  reviewError: string,
): string | null => {
  if (step === "chunking" && reviewRun.totalBatches > 0) {
    return `${reviewRun.totalBatches} ${reviewRun.totalBatches === 1 ? "batch" : "batches"} queued`
  }
  if (step === "analyzing") {
    if (reviewRun.stage === "failed" || reviewError) {
      return reviewError || "Review failed"
    }
    if (reviewRun.totalBatches > 0) {
      return `Batch ${Math.min(reviewRun.currentBatchIndex, reviewRun.totalBatches)}/${reviewRun.totalBatches}`
    }
  }
  return null
}

/** Format file list for the analyzing step. */
const formatBatchFiles = (files: string[]) => {
  if (files.length === 0) return null
  if (files.length <= 3) return files.join(", ")
  return `${files.slice(0, 3).join(", ")} +${files.length - 3} more`
}

/* ─── header status helpers ─── */

const headerStatusIcon = (stage: ReviewRunStage, isReviewing: boolean) => {
  if (stage === "failed") return <AlertTriangle className="size-3.5" aria-hidden="true" />
  if (stage === "done") return <CheckCircle2 className="size-3.5" aria-hidden="true" />
  if (isReviewing) return <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
  return <Sparkles className="size-3.5" aria-hidden="true" />
}

const headerStatusColor = (stage: ReviewRunStage, isReviewing: boolean) => {
  if (stage === "failed") return "text-red-500 dark:text-red-400"
  if (stage === "done") return "text-emerald-500 dark:text-emerald-400"
  if (isReviewing) return "text-blue-500 dark:text-blue-400"
  return "text-muted-foreground"
}

const STATUS_BADGE_STYLE: Record<string, string> = {
  running: "border-blue-200/60 bg-blue-500/10 text-blue-600 dark:border-blue-800/50 dark:bg-blue-500/10 dark:text-blue-400",
  complete: "border-emerald-200/60 bg-emerald-500/10 text-emerald-600 dark:border-emerald-800/50 dark:bg-emerald-500/10 dark:text-emerald-400",
  failed: "border-red-200/60 bg-red-500/10 text-red-600 dark:border-red-800/50 dark:bg-red-500/10 dark:text-red-400",
}

/* ─── component ─── */

export function MergeRequestReviewProcess({
  isReviewing,
  reviewError,
  reviewSummary,
  reviewFindingsCount,
  suppressedReviewFindingsCount,
  reviewSeverityCounts,
  reviewRun,
  reviewId,
  reviewFeedback,
  reviewFeedbackError,
  isSubmittingReviewFeedback,
  onSubmitReviewFeedback,
}: MergeRequestReviewProcessProps) {
  const hasStarted = reviewRun.stage !== "idle" || reviewRun.events.length > 0
  const isDone = reviewRun.stage === "done"
  const hasFailed = reviewRun.stage === "failed"
  const hasError = reviewError.trim().length > 0 || hasFailed
  const hasFindings = reviewFindingsCount > 0

  const [isManuallyOpen, setIsManuallyOpen] = useState(false)
  const [pendingFeedbackAction, setPendingFeedbackAction] = useState<ReviewFeedback | null>(null)

const isOpen = isReviewing || isManuallyOpen

const handleReviewFeedbackSubmit = (action: ReviewFeedback) => {
  setPendingFeedbackAction(action)
  onSubmitReviewFeedback(reviewFeedback === action ? null : action)
}

if (!hasStarted) return null

const groupedEvents = eventsByStep(reviewRun.events)

return (
  <Collapsible
    open={isOpen}
    onOpenChange={(open) => {
      if (!isReviewing) {
        setIsManuallyOpen(open)
      }
    }}
  >
    {/* ── collapsed header row ── */}
    <CollapsibleTrigger
      className={cn(
        "group flex w-full items-center gap-2.5 rounded-lg border border-border/50 px-3 py-2",
        "bg-card/50 backdrop-blur-sm",
        "transition-all duration-150 hover:bg-accent/50",
        "cursor-pointer select-none",
      )}
    >
      <span className={cn("shrink-0", headerStatusColor(reviewRun.stage, isReviewing))}>
        {headerStatusIcon(reviewRun.stage, isReviewing)}
      </span>

      <span className="text-[13px] font-medium text-foreground">AI Review</span>

{isReviewing ? (
  <Badge variant="outline" className={cn("text-[10px] uppercase tracking-wider font-medium", STATUS_BADGE_STYLE.running)}>
    Running
  </Badge>
) : isDone ? (
  <Badge variant="outline" className={cn("text-[10px] uppercase tracking-wider font-medium", STATUS_BADGE_STYLE.complete)}>
    Complete
  </Badge>
) : hasFailed ? (
  <Badge variant="outline" className={cn("text-[10px] uppercase tracking-wider font-medium", STATUS_BADGE_STYLE.failed)}>
    Failed
  </Badge>
) : null}

{/* push right side to end */}
<div className="ml-auto flex items-center gap-2">
  {/* severity pills — visible for quick scanning */}

{hasFindings ? (
  <div className="flex items-center gap-1">
    {reviewSeverityCounts.high > 0 ? (
      <span className="inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-red-700 bg-red-500/10 ring-1 ring-inset ring-red-500/20 dark:text-red-300 dark:bg-red-500/10 dark:ring-red-500/20">
        {reviewSeverityCounts.high} High
      </span>
    ) : null}
    {reviewSeverityCounts.med > 0 ? (
      <span className="inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-amber-700 bg-amber-500/10 ring-1 ring-inset ring-amber-500/20 dark:text-amber-300 dark:bg-amber-500/10 dark:ring-amber-500/20">
        {reviewSeverityCounts.med} Med
      </span>
    ) : null}
    {reviewSeverityCounts.low > 0 ? (
      <span className="inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground bg-muted/50 ring-1 ring-inset ring-border">
        {reviewSeverityCounts.low} Low
      </span>
    ) : null}
  </div>
) : isDone && !hasFindings ? (
  <span className="text-[11px] text-muted-foreground">No findings</span>
) : null}

{!isLast ? (
  <div
    className={cn(
      "absolute left-[9px] top-[22px] w-px",
      stepLineColor(status),
    )}
    style={{ height: "calc(100% - 6px)" }}
    aria-hidden="true"
  />
) : null}

{/* icon */}
<span className={cn("relative z-10 mt-0.5 shrink-0", stepIconColor(status))}>
  {stepIcon(status)}
</span>

{/* content */}
<div className={cn("min-w-0 pb-4", isLast && "pb-0")}>

          {stepEvents.length > 0 ? (
            <ul className="mt-1.5 space-y-0.5">
              {stepEvents.slice(-4).map((event) => (
                <li
                  key={event.id}
                  className={cn(
                    "text-[10px] leading-relaxed",
                    event.stage === "failed"
                      ? "text-red-600 dark:text-red-400"
                      : "text-muted-foreground/60",
                  )}
                >
                  {event.message}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      </li>
    )
  })}
</ol>

{/* findings summary row — only when done with findings */}

{isDone && hasFindings ? (
  <div className="mt-3 flex flex-wrap items-center gap-1.5 pt-3">
    <span className="text-[11px] font-medium text-muted-foreground">
      {reviewFindingsCount} {reviewFindingsCount === 1 ? "finding" : "findings"}
    </span>
    <span className="text-border/60">·</span>
    {reviewSeverityCounts.high > 0 ? (
      <span className="text-[11px] font-medium tabular-nums text-red-600 dark:text-red-400">
        {reviewSeverityCounts.high} high
      </span>
    ) : null}
    {reviewSeverityCounts.med > 0 ? (
      <>
        {reviewSeverityCounts.high > 0 ? <span className="text-border/60">·</span> : null}
        <span className="text-[11px] font-medium tabular-nums text-amber-600 dark:text-amber-400">
          {reviewSeverityCounts.med} med
        </span>
      </>
    ) : null}
    {reviewSeverityCounts.low > 0 ? (
      <>
        {(reviewSeverityCounts.high > 0 || reviewSeverityCounts.med > 0) ? <span className="text-border/60">·</span> : null}
        <span className="text-[11px] font-medium tabular-nums text-muted-foreground">
          {reviewSeverityCounts.low} low
        </span>
      </>
    ) : null}
  </div>
) : null}

{/* summary text when done */}

{isDone && reviewSummary ? (
  <p className="mt-2.5 text-[11px] leading-relaxed text-muted-foreground">{reviewSummary}</p>
) : null}
{isDone && suppressedReviewFindingsCount > 0 ? (
  <p className="mt-1 text-[11px] text-muted-foreground">
    {suppressedReviewFindingsCount} finding{suppressedReviewFindingsCount === 1 ? "" : "s"} filtered by confidence settings.
  </p>
) : null}

          {isDone && reviewId ? (
            <div className="mt-3 flex flex-wrap items-center gap-2 pt-3">
              <span className="text-[11px] text-muted-foreground">Helpful?</span>
              <ReviewFeedbackIconButton
                ariaLabel="Mark review as helpful"
                icon={ThumbsUp}
                isActive={reviewFeedback === "up"}
                isLoading={isSubmittingReviewFeedback && pendingFeedbackAction === "up"}
                disabled={isSubmittingReviewFeedback}
                className="h-6 px-1.5"
                onClick={() => handleReviewFeedbackSubmit("up")}
              />
              <ReviewFeedbackIconButton
                ariaLabel="Mark review as not helpful"
                icon={ThumbsDown}
                isActive={reviewFeedback === "down"}
                isLoading={isSubmittingReviewFeedback && pendingFeedbackAction === "down"}
                disabled={isSubmittingReviewFeedback}
                className="h-6 px-1.5"
                onClick={() => handleReviewFeedbackSubmit("down")}
              />
              {isSubmittingReviewFeedback ? (
                <span className="text-[11px] text-muted-foreground">Saving…</span>
              ) : null}
              {reviewFeedbackError ? (
                <span className="text-[11px] text-red-600 dark:text-red-400">
                  {reviewFeedbackError}
                </span>
              ) : null}
            </div>
          ) : null}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

