} from "@/lib/observability"

type BadgeVariant = "default" | "secondary" | "destructive" | "outline"

export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export const extractErrorMessage = (payload: unknown, fallback: string) => {
  const record = asRecord(payload)
  const rawError = record?.error
  return typeof rawError === "string" && rawError.trim() ? rawError : fallback
}

export const formatDateTime = (value: string | null | undefined) => {
  if (!value) {
    return "n/a"
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "invalid"
  }
  return parsed.toLocaleString()
}

export const formatDuration = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  return `${value}ms`
}

export const formatPercent = (value: number | null) => {
  if (value === null || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return `${value.toFixed(2)}%`
}

export const formatCurrencyUsd = (value: number | null) => {
  if (value === null || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return `$${value.toFixed(6)}`
}

export const formatCount = (value: number | null | undefined) => {
  if (value === null || value === undefined || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return Math.floor(value).toLocaleString()
}

export const asNumber = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

export const formatAge = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  const seconds = Math.floor(value / 1000)
  if (seconds < 60) {
    return `${seconds}s`
  }
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) {
    return `${minutes}m`
  }
  const hours = Math.floor(minutes / 60)
  return `${hours}h`
}

export const toIsoQuery = (value: string) => {
  if (!value.trim()) {
    return ""
  }
  const parsed = new Date(value)
  return Number.isNaN(parsed.getTime()) ? "" : parsed.toISOString()
}

export const toLocalDateTimeInput = (value: string | null | undefined) => {
  if (!value) {
    return ""
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return ""
  }
  const pad = (segment: number) => String(segment).padStart(2, "0")
  return [
    parsed.getFullYear(),
    "-",
    pad(parsed.getMonth() + 1),
    "-",
    pad(parsed.getDate()),
    "T",
    pad(parsed.getHours()),
    ":",
    pad(parsed.getMinutes()),
  ].join("")
}

export const levelBadgeVariant = (level: ObservabilityLogLevel): BadgeVariant => {
  if (level === "error") {
    return "destructive"
  }
  if (level === "warn") {
    return "secondary"
  }
  if (level === "debug") {
    return "outline"
  }
  return "default"
}

export const healthBadgeVariant = (status: ObservabilityHealthStatus): BadgeVariant => {
  if (status === "critical") {
    return "destructive"
  }
  if (status === "degraded") {
    return "secondary"
  }
  return "default"
}

export const payloadPreview = (payload: Record<string, unknown>) => {
  try {
    const serialized = JSON.stringify(payload, null, 2)
    if (serialized.length <= 280) {
      return serialized
    }
    return `${serialized.slice(0, 280)}...`
  } catch {
    return "[payload serialization failed]"
  }
}

