const withEnv = async <T>(
  overrides: Partial<NodeJS.ProcessEnv>,
  fn: () => Promise<T> | T,
): Promise<T> => {
  const previous = new Map<string, string | undefined>()
  for (const [key, value] of Object.entries(overrides)) {
    previous.set(key, process.env[key])
    if (value === undefined) {
      delete process.env[key]
    } else {
      process.env[key] = value
    }
  }

  try {
    return await fn()
  } finally {
    for (const [key, value] of previous.entries()) {
      if (value === undefined) {
        delete process.env[key]
      } else {
        process.env[key] = value
      }
    }
  }
}

const createClientHarness = (responses: Array<QueryCall | Error>) => {
  const connect = mock(async () => {})
  const end = mock(async () => {})
  const query = mock(async (text: string, values?: unknown[]) => {
    const next = responses.shift()
    if (!next) {
      throw new Error(`No mock response for query: ${text}`)
    }

    if (next instanceof Error) {
      throw next
    }

    expect(text).toBe(next.text)
    expect(values).toEqual(next.values)

    if (text.includes('select extname, extversion')) {
      return {
        rowCount: 1,
        rows: [{ extname: 'vector', extversion: '0.8.1' }],
      }
    }

    if (text.includes(`select to_regtype('vector')::text as "vectorType"`)) {
      return {
        rowCount: 1,
        rows: [{ vectorType: 'vector' }],
      }
    }

    return {
      rowCount: null,
      rows: [],
    }
  })

  const client: BootstrapClient = {
    connect,
    query,
    end,
  }

  return { client, connect, query, end }
}

describe('db-bootstrap', () => {
  test('resolves env defaults and validates extension name', async () => {
    await withEnv({ DATABASE_URL: ' postgres://example ', DB_VECTOR_EXTENSION: undefined }, () => {
      expect(resolveDatabaseUrl()).toBe('postgres://example')
      expect(resolveVectorExtension()).toBe('vector')
    })

    await withEnv({ DB_VECTOR_EXTENSION: 'INVALID-NAME' }, () => {
      expect(() => resolveVectorExtension()).toThrow('Invalid DB_VECTOR_EXTENSION value')
    })
  })

test('runs extension bootstrap and vector type assertion', async () => {
  const { client, connect, query, end } = createClientHarness([
    { text: 'create extension if not exists "vector"', values: undefined },
    { text: 'select extname, extversion from pg_extension where extname = $1', values: ['vector'] },
    { text: `select to_regtype('vector')::text as "vectorType"`, values: undefined },
  ])
  const log = mock(() => {})

  await runDbBootstrap({
    databaseUrl: 'postgres://example',
    extension: 'vector',
    clientFactory: () => client,
    logger: { log },
  })

  expect(connect).toHaveBeenCalledTimes(1)
  expect(query).toHaveBeenCalledTimes(3)
  expect(end).toHaveBeenCalledTimes(1)
  expect(log).toHaveBeenCalledWith('[db:bootstrap] extension "vector" ready (version 0.8.1).')
})

test('fails fast with actionable message when extension install is blocked by privileges', async () => {
  const pgError = Object.assign(new Error('permission denied'), {
    code: '42501',
    detail: 'Must be superuser',
  })

  const connect = mock(async () => {})
  const end = mock(async () => {})
  const query = mock(async () => {
    throw pgError
  })
  const client: BootstrapClient = { connect, query, end }

  await expect(
    runDbBootstrap({
      databaseUrl: 'postgres://example',
      extension: 'vector',
      clientFactory: () => client,
    }),
  ).rejects.toThrow('cannot create extension "vector" (insufficient privilege)')
  await expect(
    runDbBootstrap({
      databaseUrl: 'postgres://example',
      extension: 'vector',
      clientFactory: () => client,
    }),
  ).rejects.toThrow('create extension if not exists "vector";')

  expect(end).toHaveBeenCalledTimes(2)
})

test('fails fast when extension is not available on server', async () => {
  const pgError = Object.assign(new Error('missing extension control file'), {
    code: '0A000',
    hint: 'Install extension package first',
  })

  const connect = mock(async () => {})
  const end = mock(async () => {})
  const query = mock(async () => {
    throw pgError
  })
  const client: BootstrapClient = { connect, query, end }

  await expect(
    runDbBootstrap({
      databaseUrl: 'postgres://example',
      extension: 'vector_missing',
      clientFactory: () => client,
    }),
  ).rejects.toThrow('extension "vector_missing" is not available on this PostgreSQL server')

  expect(end).toHaveBeenCalledTimes(1)
})

  test('fails when extension exists but vector SQL type is unavailable', async () => {
    const connect = mock(async () => {})
    const end = mock(async () => {})
    const query = mock(async (text: string, values?: unknown[]) => {
      if (text === 'create extension if not exists "vector"') {
        expect(values).toBeUndefined()
        return { rowCount: null, rows: [] }
      }

      if (text === 'select extname, extversion from pg_extension where extname = $1') {
        expect(values).toEqual(['vector'])
        return {
          rowCount: 1,
          rows: [{ extname: 'vector', extversion: '0.8.1' }],
        }
      }

      if (text === `select to_regtype('vector')::text as "vectorType"`) {
        expect(values).toBeUndefined()
        return {
          rowCount: 1,
          rows: [{ vectorType: null }],
        }
      }

      throw new Error(`Unexpected query: ${text}`)
    })
    const client: BootstrapClient = { connect, query, end }

    await expect(
      runDbBootstrap({
        databaseUrl: 'postgres://example',
        extension: 'vector',
        clientFactory: () => client,
      }),
    ).rejects.toThrow('SQL type "vector" is missing')

    expect(end).toHaveBeenCalledTimes(1)
  })

  test('formatBootstrapError preserves fallback message for unknown PG errors', () => {
    const error = formatBootstrapError(new Error('boom'), 'vector')
    expect(error.message).toContain('failed to ensure extension "vector" is ready')
    expect(error.message).toContain('boom')
  })
})

  test("falls back for missing/invalid fields", () => {
    const row = toStructuredLogRow({
      timestamp: 0,
      level: "debug",
      tag: "trace",
      status: "bad",
      duration: "not-a-duration",
    })

    expect(row.event).toBe("log.trace")
    expect(row.status).toBeNull()
    expect(row.durationMs).toBeNull()
    expect(row.version).toBeNull()
    expect(row.path).toBeNull()
    expect(row.requestId).toBeNull()
  })
})

