export const loadPersistedReviewImpacts = async (args: {
  userId: string
  reviewId: string
}): Promise<ReviewImpactResponse> => {
  const review = await getOwnedReview({
    userId: args.userId,
    reviewId: args.reviewId,
  })
  const findingsByKey = toFindingsByCommentKey(review.findings)
  const rows = await getPersistedRows(review.id)
  const impactByKey = Object.fromEntries(rows.map((row) => [row.commentKey, toImpactResult(row)]))
  return {
    reviewId: review.id,
    status: resolveReviewImpactStatus({
      rows,
      expectedCount: findingsByKey.size,
    }),
    impactByKey,
    graph: resolveGraphInfoFromRows(rows),
  }
}

export const computeAndPersistReviewImpacts = async (args: {
  userId: string
  reviewId: string
  force: boolean
}): Promise<ReviewImpactComputeResponse> => {
  const review = await getOwnedReview({
    userId: args.userId,
    reviewId: args.reviewId,
  })
  const findingsByKey = toFindingsByCommentKey(review.findings)
  if (findingsByKey.size === 0) {
    return {
      reviewId: review.id,
      status: "completed",
      computedCount: 0,
      failedCount: 0,
      impactByKey: {},
      graph: null,
    }
  }

  const existingRows = await getPersistedRows(review.id)
  const existingByKey = new Map(existingRows.map((row) => [row.commentKey, row]))

  let graphSummary: Awaited<ReturnType<typeof getCodeGraphSummary>> = null
  let graphErrorMessage = ""

try {
  graphSummary = await getCodeGraphSummary()
  if (!graphSummary) {
    graphErrorMessage = "Code graph index-pack not found. Refresh to build it."
  }
} catch (error) {
  graphErrorMessage = errorMessage(error)
}

let computedCount = 0
for (const [commentKey, finding] of findingsByKey.entries()) {
  const existing = existingByKey.get(commentKey)
  if (!args.force && existing && existing.status !== "pending") {
    continue
  }

  computedCount += 1

  if (graphErrorMessage) {
    await persistImpactRow({
      reviewId: review.id,
      commentKey,
      status: "failed",
      scope: null,
      sourceNodeId: null,
      sourceFile: finding.file,
      sourceLine: finding.line,
      impactScore: null,
      impactLevel: null,
      callersCount: 0,
      calleesCount: 0,
      dependentsCount: 0,
      dependenciesCount: 0,
      affectedFilesCount: 0,
      affectedSymbolsCount: 0,
      topImpactedFiles: [],
      indexRunId: null,
      graphGeneratedAt: null,
      error: graphErrorMessage,
    })
    continue
  }

  try {
    const match = await findPersistedGraphNodeForFinding({
      filePath: finding.file,
      line: finding.line,
      title: finding.title,
    })

  }

  const loaded = await loadPersistedReviewImpacts({
    userId: args.userId,
    reviewId: review.id,
  })
  const failedCount = Object.values(loaded.impactByKey).filter((impact) => impact.status === "failed").length

  return {
    ...loaded,
    computedCount,
    failedCount,
  }
}

import { NextResponse } from "next/server"
import { db } from "@/lib/db"
import { onboardingEvents, type OnboardingEventMetadata } from "@/lib/db/schema"
import { recordOnboardingCompletedIfMissing } from "@/lib/onboarding/service"
import { getSession } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const ONBOARDING_EVENTS = [
  "onboarding_started",
  "onboarding_token_validated",
  "onboarding_projects_ready",
  "onboarding_projects_selected",
  "onboarding_mrs_ready",
  "onboarding_review_opened",
  "onboarding_quick_review_output",
  "onboarding_full_review_ready",
  "onboarding_completed",
] as const

type OnboardingEvent = (typeof ONBOARDING_EVENTS)[number]

type TrackEventPayload = {
  event: OnboardingEvent
  metadata?: OnboardingEventMetadata
}

const isOnboardingEvent = (value: unknown): value is OnboardingEvent =>
  typeof value === "string" && ONBOARDING_EVENTS.includes(value as OnboardingEvent)

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/onboarding/track",
    event: "api.onboarding.track",
    handler: async ({ logger }) => {
      const payloadPromise = request.json().catch(() => null)
      const sessionPromise = getSession()

      const [session, payloadValue] = await Promise.all([sessionPromise, payloadPromise])

      if (!session?.user?.id) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

const payload = payloadValue as TrackEventPayload | null
if (!payload || !isOnboardingEvent(payload.event)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid onboarding event." }, { status: 400 }),
  }
}

const metadata =
  payload.metadata && typeof payload.metadata === "object"
    ? payload.metadata
    : undefined

let onboardingDurationMs: number | null = null
let onboardingAlreadyCompleted = false
let onboardingCompletionSource: OnboardingEventMetadata["completionSource"] | null =
  metadata?.completionSource ?? null

if (payload.event === "onboarding_completed") {
  onboardingCompletionSource = metadata?.completionSource ?? "manual"
  const completion = await recordOnboardingCompletedIfMissing({
    userId: session.user.id,
    metadata: {
      ...metadata,
      completionSource: onboardingCompletionSource,
    },
  })
  onboardingDurationMs = completion.onboardingDurationMs
  onboardingAlreadyCompleted = completion.alreadyCompleted
} else {
  await db.insert(onboardingEvents).values({
    userId: session.user.id,
    event: payload.event,
    metadata,
  })
}

logger.set({
  onboardingEvent: payload.event,
  onboardingDurationMs,
  onboardingAlreadyCompleted,
  onboardingCompletionSource,
})

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          ok: true,
          data: {
            onboardingDurationMs,
            onboardingAlreadyCompleted,
          },
        }),
      }
    },
  })
}

export type CleanupIndexArtifactsSummary = {
  lock: 'acquired' | 'skipped'
  policy: CleanupPolicy
  scannedRuns: number
  trackedRuns: number
  protectedRuns: number
  candidateRuns: number
  skippedByDeleteLimit: number
  deletedRuns: number
  deletedBytes: number
  deletedObjects: number
  errors: number
  totalBytesBefore: number | null
  totalBytesAfter: number | null
  reasons: Record<CleanupReason, number>
}

type CleanupIndexArtifactsOptions = {
  readyKeepPerBranch?: number
  failedRetentionDays?: number
  supersededRetentionDays?: number
  maxTotalBytes?: number
  runScanLimit?: number
  deleteLimit?: number
}

const parseNonNegativeInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return fallback
  }

  return parsed
}

const isPrunedPrefix = (prefix: string) => prefix.startsWith(PRUNED_ARTIFACTS_PREFIX)
const isCompletedRunStatus = (status: string): status is CompletedRunStatus =>
  (RUN_STATUSES_WITH_ARTIFACTS as readonly string[]).includes(status)

const completedRuns = fetchedRuns.filter(
  (run): run is CompletedRun => isCompletedRunStatus(run.status),
)

const trackedRuns = completedRuns.filter((run) => {
  const prefix = run.artifactsPrefix.trim()
  if (!prefix) {
    return false
  }

  return prefix !== PENDING_ARTIFACTS_PREFIX && !isPrunedPrefix(prefix)
})
summary.trackedRuns = trackedRuns.length

const protectedRunIds = new Set(
  servingPointers.flatMap((pointer) =>
    typeof pointer.lastReadyRunId === 'string' && pointer.lastReadyRunId.length > 0
      ? [pointer.lastReadyRunId]
      : [],
  ),
)

const readyRunsByBranch = new Map<string, CompletedRun[]>()
for (const run of trackedRuns) {
  if (run.status !== 'ready') {
    continue
  }

  const bucket = readyRunsByBranch.get(run.branchStateId)
  if (bucket) {
    bucket.push(run)
  } else {
    readyRunsByBranch.set(run.branchStateId, [run])
  }
}

for (const runs of readyRunsByBranch.values()) {
  runs
    .slice()
    .sort((left, right) => right.updatedAt.getTime() - left.updatedAt.getTime())
    .slice(0, policy.readyKeepPerBranch)
    .forEach((run) => {
      protectedRunIds.add(run.id)
    })
}

summary.protectedRuns = protectedRunIds.size

const failedCutoffMs = Date.now() - policy.failedRetentionDays * ONE_DAY_MS
const supersededCutoffMs = Date.now() - policy.supersededRetentionDays * ONE_DAY_MS
const candidates = new Map<string, { run: CompletedRun; reason: CleanupReason }>()

for (const run of trackedRuns) {
  if (protectedRunIds.has(run.id)) {
    continue
  }

  if (run.status === 'ready') {
    candidates.set(run.id, {
      run,
      reason: 'ready_count',
    })
    continue
  }

  if (run.status === 'failed' && run.updatedAt.getTime() <= failedCutoffMs) {
    candidates.set(run.id, {
      run,
      reason: 'failed_age',
    })
    continue
  }

  if (run.status === 'superseded' && run.updatedAt.getTime() <= supersededCutoffMs) {
    candidates.set(run.id, {
      run,
      reason: 'superseded_age',
    })
  }
}

const sizesByRunId = new Map<string, number>()

if (policy.maxTotalBytes > 0) {
  for (const run of trackedRuns) {
    try {
      const details = await cleanupStore.describePrefix({
        artifactsPrefix: run.artifactsPrefix,
      })
      sizesByRunId.set(run.id, Math.max(0, details.bytes))
    } catch {
      sizesByRunId.set(run.id, 0)
      summary.errors += 1
    }
  }

  const totalBytesBefore = trackedRuns.reduce(
    (acc, run) => acc + (sizesByRunId.get(run.id) ?? 0),
    0,
  )
  summary.totalBytesBefore = totalBytesBefore

  let projectedBytesAfter = totalBytesBefore
  for (const candidate of candidates.values()) {
    projectedBytesAfter -= sizesByRunId.get(candidate.run.id) ?? 0
  }

  if (projectedBytesAfter > policy.maxTotalBytes) {
    const overflowCandidates = trackedRuns
      .filter((run) => !protectedRunIds.has(run.id) && !candidates.has(run.id))
      .sort((left, right) => left.updatedAt.getTime() - right.updatedAt.getTime())

    for (const run of overflowCandidates) {
      candidates.set(run.id, {
        run,
        reason: 'size_limit',
      })
      projectedBytesAfter -= sizesByRunId.get(run.id) ?? 0
      if (projectedBytesAfter <= policy.maxTotalBytes) {
        break
      }
    }
  }
}

const orderedCandidates = [...candidates.values()].sort(
  (left, right) => left.run.updatedAt.getTime() - right.run.updatedAt.getTime(),
)
summary.candidateRuns = orderedCandidates.length

    const selectedCandidates = orderedCandidates.slice(0, policy.deleteLimit)
    summary.skippedByDeleteLimit = Math.max(0, orderedCandidates.length - selectedCandidates.length)

    for (const candidate of selectedCandidates) {
      summary.reasons[candidate.reason] += 1

      try {
        const deleted = await cleanupStore.deletePrefix({
          artifactsPrefix: candidate.run.artifactsPrefix,
        })

        await markRunArtifactsPruned(candidate.run)

        summary.deletedRuns += 1
        summary.deletedBytes += deleted.bytes
        summary.deletedObjects += deleted.objects
      } catch {
        summary.errors += 1
      }
    }

    if (summary.totalBytesBefore !== null) {
      summary.totalBytesAfter = Math.max(0, summary.totalBytesBefore - summary.deletedBytes)
    }

    return summary
  } finally {
    cleanupInProgress = false
  }
}

