import { notFound, redirect } from "next/navigation"

import { IndexingConsole } from "@/components/indexing/indexing-console"
import { SiteHeaderTitle } from "@/components/site-header-title"
import { buildRepoRouteId, findIntegrationByRepoRouteId } from "@/lib/gitlab/repo-route"
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { getSession } from "@/lib/session"

type RepoIndexingPageProps = {
  params: Promise<{
    integrationId: string
  }>
}

export default async function RepoIndexingPage({ params }: RepoIndexingPageProps) {
  const [session, { integrationId: repoRouteId }] = await Promise.all([
    getSession(),
    params,
  ])

  if (!session?.user?.id) {
    redirect("/")
  }

  const integrations = await getCachedUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)

  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(`/repos/${encodeURIComponent(canonicalRepoRouteId)}/indexing`)
  }

  return (
    <div className="space-y-6">
      <SiteHeaderTitle title={`${integration.projectName} indexing`} />
      <IndexingConsole
        initialIntegrationId={integration.id}
        fixedIntegration={{
          id: integration.id,
          projectName: integration.projectName,
          projectPath: integration.projectPath,
          status: integration.status,
        }}
      />
    </div>
  )
}

import { describe, expect, test } from "bun:test"

import { buildAlphaAccessConfig, isAlphaAccessEmailAllowedForConfig } from "@/lib/alpha-access"

describe("alpha access gating", () => {
  test("allows all users when the gate is disabled", () => {
    const config = buildAlphaAccessConfig({
      enabled: "0",
      allowedEmails: "",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, null)).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "user@example.com")).toBe(true)
  })

  test("enforces exact email matches when the gate is enabled", () => {
    const config = buildAlphaAccessConfig({
      enabled: "1",
      allowedEmails: "alpha@example.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "alpha@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "ALPHA@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "beta@example.com")).toBe(false)
  })

  test("supports domain allowlist entries", () => {
    const config = buildAlphaAccessConfig({
      enabled: "true",
      allowedEmails: "@example.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "dev@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "dev@other.com")).toBe(false)
  })

  test("parses mixed separators for allowlist tokens", () => {
    const config = buildAlphaAccessConfig({
      enabled: "yes",
      allowedEmails: "one@example.com, two@example.com\n@company.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "one@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "two@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "three@company.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "three@elsewhere.com")).toBe(false)
  })
})

