        name: "US GitLab",
      },
      {
        key: "https://gitlab.global.lmco.com",
        name: "Global GitLab",
      },
      {
        key: "custom",
        name: "Custom GitLab",
        defaultUrl: "https://gitlab.com",
        isCustom: true,
      },
    ])
  })

  test("builds token slots for every configured instance", () => {
    const tokens = buildEmptyInstanceTokens()

    expect(Object.keys(tokens).sort()).toEqual(INSTANCE_PRESETS.map((preset) => preset.key).sort())
    expect(Object.values(tokens).every((value) => value === "")).toBe(true)
  })

  test("hashTokenForCache is deterministic", () => {
    const first = hashTokenForCache("token-123")
    const second = hashTokenForCache("token-123")
    const third = hashTokenForCache("token-456")

    expect(first).toBe(second)
    expect(first).not.toBe(third)
  })

test("resolveGitLabInstance trims trailing slashes and handles custom instance", () => {
  expect(resolveGitLabInstance("https://gitlab.us.lmco.com", "ignored")).toBe(
    "https://gitlab.us.lmco.com",
  )
  expect(resolveGitLabInstance("custom", "https://self.hosted.local///")).toBe(
    "https://self.hosted.local",
