export default function SignUpPage() {
  const { data: session, isPending: sessionLoading } = authClient.useSession()
  const {
    name,
    email,
    password,
    confirmPassword,
    submitting,
    errorMessage,
    setName,
    setEmail,
    setPassword,
    setConfirmPassword,
    handleSubmit,
    handleOidcSignIn,
  } = useSignUpForm({
    onSuccess: () => {
      window.location.assign("/")
