  indexFileStates,
  indexRunFileChanges,
} from '@/lib/db/schema'

export type ExistingFileState = {
  path: string
  fileId: string
}

export const clearStagedChanges = async (runId: string): Promise<void> => {
  await db
    .delete(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, runId))
}

export const stageUpsert = async (args: {
  runId: string
  path: string
  fileId: string
  sizeBytes: number
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'upsert',
      fileId: args.fileId,
      sizeBytes: args.sizeBytes,
      skipReason: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'upsert',
        fileId: args.fileId,
        sizeBytes: args.sizeBytes,
        skipReason: null,
        updatedAt: now,
      },
    })
}

export const stageDelete = async (args: {
  runId: string
  path: string
  skipReason?: string | null
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'delete',
      fileId: null,
      sizeBytes: null,
      skipReason: args.skipReason ?? null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'delete',
        fileId: null,
        sizeBytes: null,
        skipReason: args.skipReason ?? null,
        updatedAt: now,
      },
    })
}

export const loadExistingStates = async (branchStateId: string): Promise<Map<string, ExistingFileState>> => {
  const rows = await db
    .select({
      path: indexFileStates.path,
      fileId: indexFileStates.fileId,
    })
    .from(indexFileStates)
    .where(eq(indexFileStates.branchStateId, branchStateId))

  return new Map(rows.map((row) => [row.path, row]))
}

import { describe, expect, mock, test } from "bun:test"

import { connectIntegrationAndEnableIndexing } from "@/components/onboarding/hooks/use-onboarding-integration-connect"

describe("connectIntegrationAndEnableIndexing", () => {
  test("queues plan and reconcile jobs after project connect", async () => {
    const fetchMock = mock(async (input: string) => {
      if (input === "/api/gitlab/integrations/connect") {
        return new Response(
          JSON.stringify({
            data: { id: "integration-1" },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      if (input === "/api/gitlab/integrations/integration-1/index/enable") {
        return new Response(
          JSON.stringify({
            data: {
              branch: "main",
              job: { id: "plan-job-1" },
              reconcileJob: { id: "reconcile-job-1" },
            },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      return new Response(JSON.stringify({ error: "Unexpected request" }), {
        status: 500,
        headers: { "content-type": "application/json" },
      })
    })

    const result = await connectIntegrationAndEnableIndexing({
      project: {
        id: "project-1",
        name: "Project 1",
        path: "group/project-1",
        webUrl: "https://gitlab.com/group/project-1",
        defaultBranch: "main",
      },
      normalizedInstance: "https://gitlab.com",
      token: "token-123",
      fetchImpl: fetchMock as unknown as typeof fetch,
    })

  })

  test("returns integration id with warning when indexing enable fails", async () => {
    const fetchMock = mock(async (input: string) => {
      if (input === "/api/gitlab/integrations/connect") {
        return new Response(
          JSON.stringify({
            data: { id: "integration-1" },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      if (input === "/api/gitlab/integrations/integration-1/index/enable") {
        return new Response(
          JSON.stringify({
            error: "Indexing queue unavailable",
          }),
          { status: 503, headers: { "content-type": "application/json" } },
        )
      }

      return new Response(JSON.stringify({ error: "Unexpected request" }), {
        status: 500,
        headers: { "content-type": "application/json" },
      })
    })

    const result = await connectIntegrationAndEnableIndexing({
      project: {
        id: "project-1",
        name: "Project 1",
        path: "group/project-1",
        webUrl: "https://gitlab.com/group/project-1",
        defaultBranch: "main",
      },
      normalizedInstance: "https://gitlab.com",
      token: "token-123",
      fetchImpl: fetchMock as unknown as typeof fetch,
    })

    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(result).toEqual({
      integrationId: "integration-1",
      warning: "Webhook active, but indexing could not be queued. Indexing queue unavailable",
    })
  })
})

