import { describe, expect, mock, test } from "bun:test"
import { EventEmitter } from "node:events"
import type { ChildProcessWithoutNullStreams } from "node:child_process"

type ApiLogHandlerArgs = {
  logger: {
    set: (context: Record<string, unknown>) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

type FakeChildProcess = ChildProcessWithoutNullStreams & {
  stdout: EventEmitter
  stderr: EventEmitter
  emit: (event: string, ...args: unknown[]) => boolean
}

const createFakeChildProcess = (): FakeChildProcess => {
  const processEmitter = new EventEmitter() as unknown as FakeChildProcess
  processEmitter.stdout = new EventEmitter()
  processEmitter.stderr = new EventEmitter()
  processEmitter.pid = 9_001
  processEmitter.killed = false
  processEmitter.kill = ((signal?: NodeJS.Signals) => {
    processEmitter.killed = true
    queueMicrotask(() => {
      processEmitter.emit("close", 0, signal ?? null)
    })
    return true
  }) as ChildProcessWithoutNullStreams["kill"]
  return processEmitter
}

const loadRouteModule = async (options?: { userId?: string | null }) => {
  const spawn = mock(() => createFakeChildProcess())

  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: () => {},
    }

    const result = await handler({ logger, requestId: "req_1" })
    return result.response
  })

  const getSessionUserId = mock(async () => (options?.userId === undefined ? "user-1" : options.userId))

  mock.module("node:child_process", () => ({ spawn }))
  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
    logScopedError: mock(() => {}),
  }))
  mock.module("@/lib/session", () => ({
    getSessionUserId,
    getSession: async () => {
      const userId = await getSessionUserId()
      return userId ? { user: { id: userId } } : null
    },
    getSessionAccess: async () => {
      const userId = await getSessionUserId()
      return {
        session: userId ? { user: { id: userId } } : null,
        isAlphaDenied: false,
      }
    },
  }))

