  return {
    GET: routeModule.GET as (request: Request) => Promise<Response>,
    spawn,
  }
}

describe("scip progress stream route", () => {
  test("returns 401 for unauthenticated users", async () => {
    const { GET, spawn } = await loadRouteModule({ userId: null })

    const response = await GET(new Request("http://localhost/api/code/scip/stream"))
    const body = await response.json()

    expect(response.status).toBe(401)
    expect(body).toEqual({ error: "Unauthorized" })
    expect(spawn).toHaveBeenCalledTimes(0)
  })

  test("returns server-sent events and starts ci with scip phases", async () => {
    const { GET, spawn } = await loadRouteModule()
    const abortController = new AbortController()

    const response = await GET(
      new Request("http://localhost/api/code/scip/stream", { signal: abortController.signal }),
    )

