export function renderMergeRequestReviewAnnotation(
  annotation: DiffLineAnnotation<ReviewAnnotationMetadata>,
  options?: {
    onSubmitFeedback?: (commentKey: string, feedback: ReviewFeedback | null) => void
    onPostToGitLab?: (input: {
      commentKeyInput: string
      file: string
      oldPath: string | null
      newPath: string | null
      line: number
      side: "additions" | "deletions"
      title: string
      body: string
    }) => void
    onRemoveFromGitLab?: (commentKeyInput: string) => void
  },
) {
  return <MergeRequestReviewAnnotation annotation={annotation} options={options} />
}

function MergeRequestReviewAnnotation({

  annotation,
  options,
}: {
  annotation: DiffLineAnnotation<ReviewAnnotationMetadata>
  options?: {
    onSubmitFeedback?: (commentKey: string, feedback: ReviewFeedback | null) => void
    onPostToGitLab?: (input: {
      commentKeyInput: string
      file: string
      oldPath: string | null
      newPath: string | null
      line: number
      side: "additions" | "deletions"
      title: string
      body: string
    }) => void
    onRemoveFromGitLab?: (commentKeyInput: string) => void
  }
}) {
  const metadata = annotation.metadata
  const severityMeta = REVIEW_SEVERITY_META[metadata.severity]
  const isDeletionComment = annotation.side === "deletions"
  const lineLabel = `${isDeletionComment ? "-" : "+"}${annotation.lineNumber}`
  const confidencePercent = Math.round(metadata.confidence * 100)
  const [pendingFeedbackAction, setPendingFeedbackAction] = useState<ReviewFeedback | null>(null)
  const impact = metadata.impact
  const impactLevelMeta =
    impact?.impactLevel && impact.impactLevel in IMPACT_LEVEL_META
      ? IMPACT_LEVEL_META[impact.impactLevel]
      : null

  const handleFeedbackSubmit = (action: ReviewFeedback) => {
    setPendingFeedbackAction(action)
    options?.onSubmitFeedback?.(
      metadata.feedbackKey,
      metadata.feedback === action ? null : action,
    )
  }

const handlePostToGitLab = () => {
  options?.onPostToGitLab?.({
    commentKeyInput: metadata.feedbackKey,
    file: metadata.file,
    oldPath: metadata.oldPath,
    newPath: metadata.newPath,
    line: annotation.lineNumber,
    side: annotation.side,
    title: metadata.title,
    body: metadata.body,
  })
}

const handleRemoveFromGitLab = () => {
  options?.onRemoveFromGitLab?.(metadata.feedbackKey)
}

return (
  <div
    data-review-comment="true"
    data-review-comment-key={metadata.feedbackKey}
    tabIndex={-1}
    className="mx-2 my-2 overflow-hidden rounded-md border border-border/70 bg-card/95 shadow-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
  >
    <div className="flex items-center gap-2 border-b border-border/70 bg-muted/35 px-3 py-2 text-[11px]">
      <span className="flex size-5 items-center justify-center rounded-full bg-primary/10 text-primary">
        <Bot className="size-3" />
      </span>
      <span className="font-semibold text-foreground">Argus AI</span>
      <span className="text-muted-foreground">commented</span>
      <span className="rounded-sm bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
        {lineLabel}
      </span>
      <Badge
        variant="outline"
        className={`h-5 border text-[10px] font-medium ${severityMeta.className}`}
      >
        {severityMeta.label}
      </Badge>

{metadata.evidence ? (
  <p className="whitespace-pre-wrap rounded border border-border/60 bg-muted/30 px-2 py-1 text-[11px] leading-4 text-muted-foreground">
    Evidence: {metadata.evidence}
  </p>
) : null}
<p className="text-[10px] uppercase tracking-wide text-muted-foreground">
  {confidencePercent}% confidence
</p>
{metadata.isImpactComputing ? (
  <p className="text-[10px] text-muted-foreground">Impact analysis running...</p>
) : null}

{impact ? (
  <div className="space-y-1">
    <div className="flex flex-wrap items-center gap-1.5">
      {impactLevelMeta ? (
        <Badge
          variant="outline"
          className={`h-5 border text-[10px] font-medium ${impactLevelMeta.className}`}
        >
          {impactLevelMeta.label}
        </Badge>
      ) : null}
      {impact.impactScore !== null ? (
        <span className="rounded-sm bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
          score {impact.impactScore}
        </span>
      ) : null}
      <span className="text-[10px] text-muted-foreground">
        callers {impact.callersCount} · dependents {impact.dependentsCount} · files {impact.affectedFilesCount}
      </span>
    </div>
    {impact.topImpactedFiles.length > 0 ? (
      <p className="text-[10px] text-muted-foreground">
        Top files:{" "}
        {impact.topImpactedFiles
          .slice(0, 3)
          .map((item) => `${item.filePath} (${item.count})`)
          .join(", ")}
      </p>
    ) : null}
    {impact.status === "failed" && impact.error ? (
      <p className="text-[10px] text-red-600 dark:text-red-400">
        Impact analysis failed: {impact.error}
      </p>
    ) : null}
  </div>
) : null}

        {metadata.feedbackError ? (
          <p className="text-[10px] text-red-600 dark:text-red-400">{metadata.feedbackError}</p>
        ) : null}
        {metadata.gitlabPostError ? (
          <p className="text-[10px] text-red-600 dark:text-red-400">{metadata.gitlabPostError}</p>
        ) : null}
      </div>
    </div>
  )
}

