import { type ReviewGateSettings, type ReviewGateStrictness } from "@/lib/review/gate"

const isStrictness = (value: unknown): value is ReviewGateStrictness =>
  value === "quiet" || value === "balanced" || value === "thorough"

export const parseReviewGateSettings = (
  payload: unknown,
): { settings: ReviewGateSettings | null; error: string | null } => {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return {
      settings: null,
      error: "Request body must be an object.",
    }
  }

  const record = payload as Record<string, unknown>

  if (!isStrictness(record.strictness)) {
    return {
      settings: null,
      error: "strictness must be one of: quiet, balanced, thorough.",
    }
  }

  if (typeof record.requireEvidence !== "boolean") {
    return {
      settings: null,
      error: "requireEvidence must be a boolean.",
    }
  }

  if (typeof record.securityBoost !== "boolean") {
    return {
      settings: null,
      error: "securityBoost must be a boolean.",
    }
  }

  return {
    settings: {
      strictness: record.strictness,
      requireEvidence: record.requireEvidence,
      securityBoost: record.securityBoost,
    },
    error: null,
  }
}

