import { spawnSync } from "node:child_process"
import { existsSync, readdirSync, readFileSync } from "node:fs"
import path from "node:path"

const [, , scriptName, ...args] = process.argv

if (!scriptName) {
  console.error("[workspace-runner] usage: bun run scripts/run-workspace-script.mjs <script> [--scope=all|apps|shared]")
  process.exit(1)
}

const scopeArg = args.find((arg) => arg.startsWith("--scope="))
const scope = scopeArg ? scopeArg.slice("--scope=".length) : "all"

if (!["all", "apps", "shared"].includes(scope)) {
  console.error(`[workspace-runner] unsupported scope: ${scope}`)
  process.exit(1)
}

const rootDir = process.cwd()

const collectWorkspaceDirs = (workspaceRoot) => {
  if (!existsSync(workspaceRoot)) {
    return []
  }

  return readdirSync(workspaceRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => path.join(workspaceRoot, entry.name))
    .filter((dir) => existsSync(path.join(dir, "package.json")))
}

const TEST_FILE_PATTERN = /(\.test\.|_test_|\.spec\.|_spec_)/
const TEST_SCAN_SKIP_DIRS = new Set(["node_modules", ".git", ".next", "dist", "build", "coverage"])

const hasTestFiles = (dirPath) => {
  const entries = readdirSync(dirPath, { withFileTypes: true })
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (TEST_SCAN_SKIP_DIRS.has(entry.name)) {
        continue
      }
      if (hasTestFiles(path.join(dirPath, entry.name))) {
        return true
      }
      continue
    }

    if (TEST_FILE_PATTERN.test(entry.name)) {
      return true
    }
  }

  return false
}

const workspaceDirs = [
  ...(scope === "all" || scope === "apps" ? collectWorkspaceDirs(path.join(rootDir, "apps")) : []),
  ...(scope === "all" || scope === "shared"
    ? collectWorkspaceDirs(path.join(rootDir, "packages", "shared"))
    : []),
].sort((left, right) => left.localeCompare(right))

let runCount = 0

for (const packageDir of workspaceDirs) {
  const packageJson = JSON.parse(readFileSync(path.join(packageDir, "package.json"), "utf8"))
  const scripts = packageJson.scripts ?? {}
  if (!scripts[scriptName]) {
    continue
  }

  if (scriptName === "test" && !hasTestFiles(packageDir)) {
    const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
    console.log(
      `\n[workspace-runner] skipping ${displayName} (${path.relative(rootDir, packageDir)}) - no test files found`,
    )
    continue
  }

  runCount += 1
  const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
  console.log(`\n[workspace-runner] ${displayName} (${path.relative(rootDir, packageDir)})`)
  console.log(`[workspace-runner] bun run ${scriptName}`)

  const result = spawnSync("bun", ["run", scriptName], {
    cwd: packageDir,
    stdio: "inherit",
    env: process.env,
  })

  if ((result.status ?? 1) !== 0) {
    process.exit(result.status ?? 1)
  }
}

if (runCount === 0) {
  console.error(`[workspace-runner] no workspace packages expose script "${scriptName}" for scope "${scope}"`)
  process.exit(1)
}

console.log(`\n[workspace-runner] completed "${scriptName}" in ${runCount} package(s).`)

import { NextResponse } from "next/server"
import { z } from "zod"

import { db } from "@/lib/db"
import { analyticsUserActivityEvents } from "@/lib/db/schema"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const payloadSchema = z
  .object({
    event: z.enum(["command_used", "feature_opened", "session_duration"]),
    feature: z.string().trim().min(1).max(160).optional(),
    command: z.string().trim().min(1).max(160).optional(),
    sessionId: z.string().trim().min(1).max(120).optional(),
    durationMs: z.coerce.number().int().nonnegative().max(1000 * 60 * 60 * 24).optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
  })
  .strict()

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/analytics/track",
    event: "api.analytics.track",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = payloadSchema.safeParse(await request.json().catch(() => null))
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid analytics event payload." }, { status: 400 }),
        }
      }

      if (parsed.data.event === "command_used" && !parsed.data.command) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "command is required for command_used." }, { status: 400 }),
        }
      }
      if (parsed.data.event === "feature_opened" && !parsed.data.feature) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "feature is required for feature_opened." }, { status: 400 }),
        }
      }
      if (parsed.data.event === "session_duration" && parsed.data.durationMs === undefined) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "durationMs is required for session_duration." }, { status: 400 }),
        }
      }

      await db.insert(analyticsUserActivityEvents).values({
        userId,
        event: parsed.data.event,
        feature: parsed.data.feature,
        command: parsed.data.command,
        sessionId: parsed.data.sessionId,
        durationMs: parsed.data.durationMs,
        metadata: parsed.data.metadata,
      })

      logger.set({
        analyticsEvent: parsed.data.event,
        feature: parsed.data.feature ?? null,
        command: parsed.data.command ?? null,
        hasDuration: parsed.data.durationMs !== undefined,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ ok: true }),
      }
    },
  })
}

