    throw new Error("Clipboard API is unavailable.")
  }

  await navigator.clipboard.writeText(message)
}

export const useCopyableErrorToast = (
  message: string,
  options?: {
    title?: string
  },
) => {
  const lastToastSignature = useRef("")

  useEffect(() => {
    const trimmedMessage = message.trim()
    if (!trimmedMessage) {
      return
    }

    const title = options?.title?.trim() || "Request failed"
    const signature = `${title}::${trimmedMessage}`
    if (signature === lastToastSignature.current) {
      return
    }
    lastToastSignature.current = signature

    toast.error(title, {
      description: trimmedMessage,
      duration: 10_000,
      action: {
        label: "Copy",
        onClick: () => {
          void copyErrorToClipboard(trimmedMessage)
            .then(() => {
              toast.success(COPY_ERROR_SUCCESS_MESSAGE)
            })
            .catch(() => {
              toast.error(COPY_ERROR_FAILURE_MESSAGE)
            })
        },
      },
    })
  }, [message, options?.title])
}

