import { headers } from "next/headers"
import { auth } from "@/lib/auth"
import { isAlphaAccessEmailAllowed } from "@/lib/alpha-access"

type SessionAccessResult = {
  session: Awaited<ReturnType<typeof auth.api.getSession>>
  isAlphaDenied: boolean
}

type SessionCacheEntry = {
  expiresAt: number
  value: Promise<SessionAccessResult>
}

const SESSION_CACHE_TTL_MS = 1_000
const SESSION_CACHE_MAX_ENTRIES = 256
const sessionAccessCache = new Map<string, SessionCacheEntry>()

const trimSessionCache = () => {
  const now = Date.now()
  for (const [key, value] of sessionAccessCache.entries()) {
    if (value.expiresAt <= now) {
      sessionAccessCache.delete(key)
    }
  }

  while (sessionAccessCache.size > SESSION_CACHE_MAX_ENTRIES) {
    const oldestKey = sessionAccessCache.keys().next().value
    if (!oldestKey) {
      break
    }
    sessionAccessCache.delete(oldestKey)
  }
}

const resolveSessionAccess = async (
  requestHeaders: Awaited<ReturnType<typeof headers>>,
): Promise<SessionAccessResult> => {
  const session = await auth.api.getSession({
    headers: requestHeaders,
  })

  if (!session?.user?.id) {
    return {
      session: null,
      isAlphaDenied: false,
    }
  }

  if (!isAlphaAccessEmailAllowed(session.user.email)) {
    return {
      session: null,
      isAlphaDenied: true,
    }
  }

  return {
    session,
    isAlphaDenied: false,
  }
}

const getSessionCacheKey = (requestHeaders: Awaited<ReturnType<typeof headers>>) => {
  const cookie = requestHeaders.get("cookie") ?? ""
  const authorization = requestHeaders.get("authorization") ?? ""
  return `${cookie}::${authorization}`
}

export const getSessionAccess = async (): Promise<SessionAccessResult> => {
  const requestHeaders = await headers()
  const key = getSessionCacheKey(requestHeaders)
  const now = Date.now()
  const cached = sessionAccessCache.get(key)

  if (cached && cached.expiresAt > now) {
    return cached.value
  }
  if (cached) {
    sessionAccessCache.delete(key)
  }

  const value = resolveSessionAccess(requestHeaders)
  sessionAccessCache.set(key, {
    expiresAt: now + SESSION_CACHE_TTL_MS,
    value,
  })
  trimSessionCache()

  value.catch(() => {
    const current = sessionAccessCache.get(key)
    if (current?.value === value) {
      sessionAccessCache.delete(key)
    }
  })

  return value
}

export const getSession = async () => {
  const { session } = await getSessionAccess()
  return session
}

export const getSessionUserId = async () => {
  const session = await getSession()

  return session?.user?.id ?? null
}

