import { afterEach, beforeEach, describe, expect, mock, test } from "bun:test";

const loadSourceModule = async () => {
  const actualGitlabServiceModule = await import("@/lib/gitlab/service");
  const getIntegrationById = mock(async () => ({
    id: "integration-1",
    instanceUrl: "https://gitlab.example.com",
    projectId: "group/project",
    tokenCiphertext: "cipher",
    tokenIv: "iv",
    tokenAuthTag: "tag",
  }));
  const decryptIntegrationToken = mock(() => "token-1");

  mock.module("@/lib/gitlab/service", () => ({
    ...actualGitlabServiceModule,
    getIntegrationById,
    decryptIntegrationToken,
  }));

  const sourceModule = await import(`./gitlab-source?cacheBust=${Math.random().toString(36).slice(2)}`);
  return {
    createGitLabSource: sourceModule.createGitLabSource as () => {
      resolveHeadSha: (args: {
        integrationId: string;
        branch: string;
        hintedHeadSha?: string;
      }) => Promise<string>;
      downloadArchive: (args: {
        integrationId: string;
        sha: string;
      }) => Promise<{ archivePath: string }>;
    },
  };
};

describe("GitLabApiSource", () => {
  const originalFetch = globalThis.fetch;
  const originalTimeout = process.env.INDEXER_GITLAB_REQUEST_TIMEOUT_MS;
  const originalRetries = process.env.INDEXER_GITLAB_REQUEST_RETRIES;
  const originalArchiveMax = process.env.INDEXER_GITLAB_ARCHIVE_MAX_BYTES;

beforeEach(() => {
  process.env.INDEXER_GITLAB_REQUEST_TIMEOUT_MS = "5000";
  process.env.INDEXER_GITLAB_REQUEST_RETRIES = "1";
  process.env.INDEXER_GITLAB_ARCHIVE_MAX_BYTES = "1024";
});

afterEach(() => {
  globalThis.fetch = originalFetch;
  process.env.INDEXER_GITLAB_REQUEST_TIMEOUT_MS = originalTimeout;
  process.env.INDEXER_GITLAB_REQUEST_RETRIES = originalRetries;
  process.env.INDEXER_GITLAB_ARCHIVE_MAX_BYTES = originalArchiveMax;
  mock.restore();
});

test("retries transient GitLab failures", async () => {
  let callCount = 0;
  const fetchMock = mock(async () => {
    callCount += 1;
    if (callCount === 1) {
      return new Response("temporary", { status: 503 });
    }
    return new Response(JSON.stringify({ commit: { id: "sha-123" } }), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  });
  globalThis.fetch = fetchMock;

  const { createGitLabSource } = await loadSourceModule();
  const source = createGitLabSource();
  const sha = await source.resolveHeadSha({
    integrationId: "integration-1",
    branch: "main",
  });

  expect(sha).toBe("sha-123");
  expect(callCount).toBe(2);
});

  test("rejects archive download when size exceeds configured limit", async () => {
    process.env.INDEXER_GITLAB_ARCHIVE_MAX_BYTES = "5";
    globalThis.fetch = mock(
      async () =>
        new Response("0123456789", {
          status: 200,
          headers: {
            "content-length": "10",
          },
        }),
    );

    const { createGitLabSource } = await loadSourceModule();
    const source = createGitLabSource();

    await expect(
      source.downloadArchive({
        integrationId: "integration-1",
        sha: "abc123",
      }),
    ).rejects.toThrow("exceeds configured limit");
  });
});

import { describe, expect, test } from "bun:test"
import type { FileDiffMetadata } from "@pierre/diffs"

import {
  findHunkIndexForFinding,
  getErrorMessage,
  getReviewErrorMessage,
  getStableFileKey,
  normalizeReviewImpact,
  normalizePersistedReview,
  normalizeReviewFindings,
  splitPatchIntoFileChunks,
} from "../merge-request-diff-viewer.utils"

const makeFile = (overrides: Partial<FileDiffMetadata>): FileDiffMetadata => {
  return {
    cacheKey: "cache-key",
    name: "src/a.ts",
    prevName: null,
    type: "modified",
    hunks: [],
    ...overrides,
  } as unknown as FileDiffMetadata
}

describe("merge-request-diff-viewer.utils", () => {
  test("normalizes review findings and drops invalid rows", () => {
    const findings = normalizeReviewFindings([
      {
        file: "a/src/main.ts",
        line: 8.9,
        side: "removed",
        severity: "medium",
        title: "Null check",
        body: "Potential null dereference",
        confidence: 2,
      },
      {
        file: "",
        line: 1,
        title: "invalid",
        body: "invalid",
      },
    ])

    expect(findings).toHaveLength(1)
    expect(findings[0]).toEqual({
      file: "a/src/main.ts",
      line: 8,
      side: "deletions",
      severity: "med",
      title: "Null check",
      body: "Potential null dereference",
      confidence: 1,
      evidence: "",
    })
  })

test("splits patch text into file chunks and preserves metadata prefix", () => {
  const patchText = [
    "From 123",
    "diff --git a/src/a.ts b/src/a.ts",
    "@@ -1,1 +1,1 @@",
    "diff --git a/src/b.ts b/src/b.ts",
    "@@ -1,1 +1,1 @@",
  ].join("\n")

  const chunks = splitPatchIntoFileChunks(patchText)

  expect(chunks).toHaveLength(2)
  expect(chunks[0].startsWith("From 123\ndiff --git a/src/a.ts b/src/a.ts")).toBe(true)
  expect(chunks[1].startsWith("diff --git a/src/b.ts b/src/b.ts")).toBe(true)
})

test("finds matching hunk index for additions and deletions", () => {
  const file = makeFile({
    hunks: [
      {
        additionStart: 5,
        additionCount: 3,
        deletionStart: 10,
        deletionCount: 2,
      } as unknown as FileDiffMetadata["hunks"][number],
      {
        additionStart: 30,
        additionCount: 1,
        deletionStart: 40,
        deletionCount: 1,
      } as unknown as FileDiffMetadata["hunks"][number],
    ],
  })

  const addIndex = findHunkIndexForFinding(file, {
    file: "src/a.ts",
    line: 6,
    side: "additions",
    severity: "low",
    title: "x",
    body: "y",
    confidence: 0.5,
  })
  const delIndex = findHunkIndexForFinding(file, {
    file: "src/a.ts",
    line: 10,
    side: "deletions",
    severity: "low",
    title: "x",
    body: "y",
    confidence: 0.5,
  })

  expect(addIndex).toBe(0)
  expect(delIndex).toBe(0)
})

test("prefers cacheKey, otherwise builds stable fallback key", () => {
  expect(getStableFileKey({ cacheKey: "abc", prevName: undefined, name: "src/a.ts" })).toBe(
    "abc",
  )
  expect(getStableFileKey({ cacheKey: undefined, prevName: "old.ts", name: "new.ts" })).toBe(
    "old.ts->new.ts",
  )
})

test("returns Error.message for failed AI review requests", () => {
  expect(getReviewErrorMessage(new Error("AI provider request failed (401): invalid API key"))).toBe(
    "AI provider request failed (401): invalid API key",
  )
})

test("returns Error.message for diff load failures", () => {
  expect(getErrorMessage(new Error("GitLab token is invalid or expired."))).toBe(
