    totalTokensWarning: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_WARNING", 200_000),
    totalTokensCritical: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_CRITICAL", 1_000_000),
  },
})

const readProviderAndModel = (payload: Record<string, unknown>) => {
  const labels = asRecord(payload.labels)
  const llmMetrics = asRecord(payload.llmMetrics)
  const provider =
    asString(labels?.provider) ??
    asString(llmMetrics?.provider) ??
    null
  const model =
    asString(labels?.model) ??
    asString(llmMetrics?.model) ??
    asString(payload.model) ??
    null
  return { provider, model }
}

const resolveWindow = (args: {
  sinceRaw?: string
  untilRaw?: string
  windowHours: number
}) => {
  const now = new Date()
  const until = args.untilRaw ? asDate(args.untilRaw) : now
  if (!until) {
    return { error: "Invalid until date." as const, since: null, until: null }
  }
  const since = args.sinceRaw
    ? asDate(args.sinceRaw)
    : new Date(until.getTime() - args.windowHours * 60 * 60 * 1_000)
  if (!since) {
    return { error: "Invalid since date." as const, since: null, until: null }
  }
  if (until.getTime() < since.getTime()) {
    return { error: "until cannot be before since." as const, since: null, until: null }
  }
  return { error: null, since, until }
}

const matchedRows = args.rows.filter((row) => {
  const payload = asSafePayload(row.payload)
  const { provider, model } = readProviderAndModel(payload)
  if (args.providerFilter && !sameIgnoreCase(provider, args.providerFilter)) {
    return false
  }
  if (args.modelFilter && !sameIgnoreCase(model, args.modelFilter)) {
    return false
  }
  return true
})

const apiLatencies: number[] = []
let apiRequestCount = 0
let apiErrorCount = 0
let latestApi: MetricRow | null = null

const indexingDurations: number[] = []
let indexingFilesProcessed = 0
let indexingFailures = 0
let indexingEmbeddingApiCalls = 0
let latestIndexingPendingJobs: number | null = null
let latestIndexingProcessingJobs: number | null = null

const llmLatencies: number[] = []
let llmPromptTokens = 0
let llmCompletionTokens = 0
let llmTotalTokens = 0
let llmRequestCount = 0
let llmCostKnown = false
let llmCostUsd = 0
let llmProvider: string | null = args.providerFilter ?? null
let llmModel: string | null = args.modelFilter ?? null

for (const row of matchedRows) {
  const payload = asSafePayload(row.payload)
  const apiMetrics = asRecord(payload.apiMetrics)
  const indexingMetrics = asRecord(payload.indexingMetrics)
  const llmMetrics = asRecord(payload.llmMetrics)
  const { provider, model } = readProviderAndModel(payload)

  const isApi = row.event.startsWith("api.") || apiMetrics !== null

if (isApi) {
  apiRequestCount += asInt(apiMetrics?.requestCount, 1)
  apiErrorCount += asInt(apiMetrics?.errorCount, row.status !== null && row.status >= 400 ? 1 : 0)
  const latency = asNullableInt(apiMetrics?.requestLatencyMs) ?? asNullableInt(row.durationMs)
  if (latency !== null) {
    apiLatencies.push(latency)
  }
  if (!latestApi) {
    latestApi = row
  }
}

const isIndexing = row.event.startsWith("indexer.") || indexingMetrics !== null
if (isIndexing) {
  const duration = asNullableInt(indexingMetrics?.durationMs) ?? asNullableInt(row.durationMs)
  if (duration !== null) {
    indexingDurations.push(duration)
  }
  indexingFilesProcessed += asInt(indexingMetrics?.filesProcessed, 0)
  indexingFailures += asInt(
    indexingMetrics?.failures,
    row.event.startsWith("indexer.") && row.status !== null && row.status >= 400 ? 1 : 0,
  )
  indexingEmbeddingApiCalls += asInt(indexingMetrics?.embeddingApiCalls, 0)
  const maybePendingJobs = asNullableInt(indexingMetrics?.pendingJobs)
  const maybeProcessingJobs = asNullableInt(indexingMetrics?.processingJobs)
  if (maybePendingJobs !== null && latestIndexingPendingJobs === null) {
    latestIndexingPendingJobs = maybePendingJobs
  }
  if (maybeProcessingJobs !== null && latestIndexingProcessingJobs === null) {
    latestIndexingProcessingJobs = maybeProcessingJobs
  }
}

const isLlm = llmMetrics !== null || row.event.startsWith("api.ai.") || row.event.startsWith("api.review.")

  if (isLlm) {
    llmPromptTokens += asInt(llmMetrics?.promptTokens, 0)
    llmCompletionTokens += asInt(llmMetrics?.completionTokens, 0)
    llmTotalTokens += asInt(llmMetrics?.totalTokens, 0)
    llmRequestCount += asInt(llmMetrics?.requestCount, 1)
    const llmLatency = asNullableInt(llmMetrics?.latencyMs) ?? asNullableInt(payload.latencyMs)
    if (llmLatency !== null) {
      llmLatencies.push(llmLatency)
    }
    const maybeCost = asNumber(llmMetrics?.costUsd)
    if (maybeCost !== null) {
      llmCostKnown = true
      llmCostUsd += Math.max(0, maybeCost)
    }
    if (llmProvider === null && provider) {
      llmProvider = provider
    }
    if (llmModel === null && model) {
      llmModel = model
    }
  }
}

const labels: ObservabilityFilterLabels = {
  service: args.requestedLabels.service ?? latestApi?.service,
  environment: args.requestedLabels.environment ?? latestApi?.environment,
  region: args.requestedLabels.region ?? latestApi?.region ?? undefined,
  event: args.requestedLabels.event ?? latestApi?.event,
  path: args.requestedLabels.path ?? latestApi?.path ?? undefined,
  method: args.requestedLabels.method ?? latestApi?.method ?? undefined,
  status: args.requestedLabels.status ?? latestApi?.status ?? undefined,
  requestId: args.requestedLabels.requestId ?? latestApi?.requestId ?? undefined,
  provider: args.providerFilter ?? llmProvider ?? undefined,
  model: args.modelFilter ?? llmModel ?? undefined,
}

  return {
    labels,
    dimensions,
    apiMetrics: {
