        `[dev:all] ${command.name} exited ${signal ? `with signal ${signal}` : `with code ${code}`}`,
      )
      stopAll(signal ?? "SIGTERM")
      process.exit(code ?? 1)
    }
  })

  child.on("error", (error) => {
    console.error(`[dev:all] failed to start ${command.name}:`, error)
    stopAll()
    process.exit(1)
  })

  children.push(child)
}

process.once("SIGINT", () => {
  stopAll("SIGINT")
  process.exit(0)
})

process.once("SIGTERM", () => {
  stopAll("SIGTERM")
  process.exit(0)
})

export default function ObservabilityLogExplorerPage() {
  const searchParams = useSearchParams()

  const [logs, setLogs] = useState<ObservabilityLogRecord[]>([])
  const [level, setLevel] = useState<FilterLevel>(() => parseLevel(searchParams.get("level")))
  const [service, setService] = useState(() => searchParams.get("service")?.trim() ?? "")
  const [eventName, setEventName] = useState(() => searchParams.get("event")?.trim() ?? "")
  const [pathFilter, setPathFilter] = useState(() => searchParams.get("path")?.trim() ?? "")
  const [requestId, setRequestId] = useState(() => searchParams.get("requestId")?.trim() ?? "")
  const [modelFilter, setModelFilter] = useState(() => searchParams.get("model")?.trim() ?? "")
  const [statusFilter, setStatusFilter] = useState(() => searchParams.get("status")?.trim() ?? "")
  const [since, setSince] = useState(() => parseDateInput(searchParams.get("since")))
  const [until, setUntil] = useState(() => parseDateInput(searchParams.get("until")))
  const [minDurationMs, setMinDurationMs] = useState(() => searchParams.get("minDurationMs")?.trim() ?? "")
  const [pagination, setPagination] = useState<ObservabilityLogsPayload["pagination"] | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")
  const [lastRefreshedAt, setLastRefreshedAt] = useState<Date | null>(null)
  const [autoRefresh, setAutoRefresh] = useState(true)
  const [currentPage, setCurrentPage] = useState(1)
  const [payloadDialogOpen, setPayloadDialogOpen] = useState(false)

const [selectedPayloadEntry, setSelectedPayloadEntry] = useState<ObservabilityLogRecord | null>(null)
const inFlightRequestRef = useRef<AbortController | null>(null)
const inFlightRequestKeyRef = useRef<string | null>(null)

const totalPages = useMemo(
  () => pagination?.totalPages ?? 1,
  [pagination],
)

const loadLogs = useCallback(async (opts: {
  page?: number
  quiet?: boolean
  skipIfInFlightDuplicate?: boolean
} = {}) => {
  const page = opts.page ?? 1
  const quiet = opts.quiet ?? false
  let requestController: AbortController | null = null
  if (!quiet) {
    setIsLoading(true)
  }
  setErrorMessage("")

  try {
    const params = new URLSearchParams()
    if (level !== "all") {
      params.set("level", level)
    }
    if (service.trim()) {
      params.set("service", service.trim())
    }
    if (eventName.trim()) {
      params.set("event", eventName.trim())
    }
    if (pathFilter.trim()) {
      params.set("path", pathFilter.trim())
    }
    if (requestId.trim()) {
      params.set("requestId", requestId.trim())
    }
    if (modelFilter.trim()) {
      params.set("model", modelFilter.trim())
    }
    const normalizedStatus = statusFilter.trim()
    if (normalizedStatus) {
      params.set("status", normalizedStatus)
    }
    const sinceIso = toIsoQuery(since)
    if (sinceIso) {
      params.set("since", sinceIso)
    }
    const untilIso = toIsoQuery(until)
    if (untilIso) {
      params.set("until", untilIso)
    }

if (minDurationMs.trim()) {
  params.set("minDurationMs", minDurationMs.trim())
}
params.set("page", String(page))
params.set("limit", String(DEFAULT_LIMIT))
const requestKey = params.toString()
if (
  opts.skipIfInFlightDuplicate &&
  shouldSkipPollingRequest({
    isVisible: isPageVisible(),
    inFlightRequestKey: inFlightRequestKeyRef.current,
    nextRequestKey: requestKey,
  })
) {
  return
}

if (inFlightRequestRef.current) {
  inFlightRequestRef.current.abort()
}

const controller = new AbortController()
requestController = controller
inFlightRequestRef.current = controller
inFlightRequestKeyRef.current = requestKey

const response = await fetch(`/api/observability/logs?${requestKey}`, {
  method: "GET",
  headers: {
    "content-type": "application/json",
  },
  signal: controller.signal,
})
const payload = await response.json().catch(() => null)
if (!response.ok) {
  throw new Error(extractErrorMessage(payload, "Failed to load logs."))
}

const typedPayload = payload as ObservabilityLogsPayload | null
const typedLogs = Array.isArray(typedPayload?.data) ? typedPayload.data : []
setLogs(typedLogs)
setPagination(
  typedPayload?.pagination ??
    {
      page,
      limit: DEFAULT_LIMIT,
      total: 0,
      totalPages: 1,
    },
)
setLastRefreshedAt(new Date())
setCurrentPage(page)

  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      return
    }
    setLogs([])
    setPagination({
      page,
      limit: DEFAULT_LIMIT,
      total: 0,
      totalPages: 1,
    })
    setErrorMessage(error instanceof Error ? error.message : "Failed to load logs.")
  } finally {
    if (requestController && inFlightRequestRef.current === requestController) {
      inFlightRequestRef.current = null
      inFlightRequestKeyRef.current = null
    }
    if (!quiet) {
      setIsLoading(false)
    }
  }
}, [
  eventName,
  level,
  minDurationMs,
  modelFilter,
  pathFilter,
  requestId,
  service,
  since,
  statusFilter,
  until,
])

useEffect(() => {
  if (!autoRefresh) {
    return
  }
  const timer = window.setInterval(() => {
    if (!isPageVisible()) {
      return
    }
    void loadLogs({
      page: currentPage,
      quiet: true,
      skipIfInFlightDuplicate: true,
    })
  }, AUTO_REFRESH_MS)
  return () => {
    window.clearInterval(timer)
  }
}, [autoRefresh, currentPage, loadLogs])

useEffect(() => {
  return () => {
    inFlightRequestRef.current?.abort()
    inFlightRequestRef.current = null
    inFlightRequestKeyRef.current = null
  }
}, [])

useEffect(() => {
  void loadLogs({ page: 1 })
}, [loadLogs])

const handleRefresh = useCallback(() => {
  void loadLogs({ page: currentPage })
}, [currentPage, loadLogs])

const handleSubmit = useCallback(() => {
  setCurrentPage(1)
  void loadLogs({ page: 1 })
}, [loadLogs])

const handleNextPage = useCallback(() => {
  if (currentPage < totalPages) {
    setCurrentPage(currentPage + 1)
    void loadLogs({ page: currentPage + 1 })
  }
}, [currentPage, loadLogs, totalPages])

const handlePrevPage = useCallback(() => {
  if (currentPage > 1) {
    setCurrentPage(currentPage - 1)
    void loadLogs({ page: currentPage - 1 })
  }
}, [currentPage, loadLogs])

const clearFilters = useCallback(() => {
  setLevel("all")
  setService("")
  setEventName("")
  setPathFilter("")
  setRequestId("")
  setModelFilter("")
  setStatusFilter("")
  setSince("")
  setUntil("")
  setMinDurationMs("")
  setCurrentPage(1)
}, [])

const openPayloadDialog = useCallback((entry: ObservabilityLogRecord) => {
  setSelectedPayloadEntry(entry)
  setPayloadDialogOpen(true)
}, [])

return (
  <div className="space-y-4">
    <Card>
      <CardHeader className="space-y-3">
        <CardTitle>Filter logs</CardTitle>
        <CardDescription>
          Last update: {lastRefreshedAt ? formatDateTime(lastRefreshedAt.toISOString()) : "never"}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-4">

