const ENDPOINT = "/api/analytics/track";

export const trackAnalyticsEvent = (payload: AnalyticsTrackEvent) => {
  const body = JSON.stringify(payload);

  if (typeof fetch === "function") {
    void fetch(ENDPOINT, {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body,
      keepalive: true,
    }).catch(() => {});
    return;
