import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process"

import { NextResponse } from "next/server"

import { resolveCodeIntelConfigPath, resolveCodeIntelRoot } from "@/lib/argus-search/code-intel-root"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const STREAM_KEEPALIVE_INTERVAL_MS = 15_000
const SCIP_PHASES = "parse,graph,scip"

type StreamSource = "stdout" | "stderr"

type CiProgressEvent = {
  type?: string
  phase?: string
  [key: string]: unknown
}

const buildWatchArgs = () => [
  "watch",
  "--config",
  resolveCodeIntelConfigPath(),
  "--project-root",
  resolveCodeIntelRoot(),
  "--once",
  "--json",
  "--no-vector",
  "--phases",
  SCIP_PHASES,
]

const formatEvent = (event: string, data: Record<string, unknown>) =>
  `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`

const parseJson = (value: string): CiProgressEvent | null => {
  try {
    const parsed = JSON.parse(value)
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return null
    }
    return parsed as CiProgressEvent
  } catch {
    return null
  }
}

const resolveEventName = (source: StreamSource, parsed: CiProgressEvent | null) => {
  if (source === "stderr") {
    return "stderr"
  }
  if (!parsed) {
    return "progress"
  }
  if (parsed.phase === "scip") {
    return "scip"
  }
  if (typeof parsed.type === "string" && parsed.type.startsWith("scip")) {
    return "scip"
  }
  return "progress"
}

export async function GET(request: Request) {

return runWithApiRequestLog({
  request,
  path: "/api/code/scip/stream",
  event: "api.code.scip.stream",
  handler: async ({ logger }) => {
    const userId = await getSessionUserId()
    if (!userId) {
      return {
        status: 401,
        outcome: "unauthorized",
        response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
      }
    }

    const encoder = new TextEncoder()
    let closed = false
    let child: ChildProcessWithoutNullStreams | null = null
    let keepAliveTimer: ReturnType<typeof setInterval> | null = null

    let stdoutBuffer = ""
    let stderrBuffer = ""

    const clearTimers = () => {
      if (keepAliveTimer) {
        clearInterval(keepAliveTimer)
        keepAliveTimer = null
      }
    }

    const stream = new ReadableStream<Uint8Array>({
      start(controller) {
        const sendEvent = (event: string, data: Record<string, unknown>) => {
          if (closed) {
            return
          }
          controller.enqueue(encoder.encode(formatEvent(event, data)))
        }

        const close = () => {
          if (closed) {
            return
          }
          closed = true
          clearTimers()
          try {
            controller.close()
          } catch {
            // no-op
          }
        }

const flushBuffer = (source: StreamSource) => {
  const remaining = source === "stdout" ? stdoutBuffer : stderrBuffer
  const trimmed = remaining.trim()
  if (!trimmed) {
    return
  }
  const parsed = parseJson(trimmed)
  const event = resolveEventName(source, parsed)
  sendEvent(event, {
    source,
    at: new Date().toISOString(),
    line: trimmed,
    parsed,
  })
}

const handleChunk = (source: StreamSource, chunk: Buffer | string) => {
  const text = chunk.toString()
  const combined = (source === "stdout" ? stdoutBuffer : stderrBuffer) + text
  const lines = combined.split(/\r?\n/)
  const nextBuffer = lines.pop() ?? ""
  if (source === "stdout") {
    stdoutBuffer = nextBuffer
  } else {
    stderrBuffer = nextBuffer
  }

  for (const rawLine of lines) {
    const line = rawLine.trim()
    if (!line) {
      continue
    }
    const parsed = parseJson(line)
    const event = resolveEventName(source, parsed)
    sendEvent(event, {
      source,
      at: new Date().toISOString(),
      line,
      parsed,
    })
  }
}

request.signal.addEventListener("abort", () => {
  if (child && !child.killed) {
    child.kill("SIGTERM")
  }
  close()
})

const args = buildWatchArgs()
child = spawn("ci", args, {
  cwd: resolveCodeIntelRoot(),
  env: process.env,
})

logger.set({
  scipPhases: SCIP_PHASES,
  ciPid: child.pid ?? null,
})

sendEvent("ready", {
  at: new Date().toISOString(),
  phases: SCIP_PHASES,
  command: "ci watch",
})

keepAliveTimer = setInterval(() => {
  if (closed) {
    return
  }
  controller.enqueue(encoder.encode(": ping\n\n"))
}, STREAM_KEEPALIVE_INTERVAL_MS)

child.stdout.on("data", (chunk) => {
  handleChunk("stdout", chunk)
})

child.stderr.on("data", (chunk) => {
  handleChunk("stderr", chunk)
})

child.on("error", (error) => {
  sendEvent("error", {
    at: new Date().toISOString(),
    message: error instanceof Error ? error.message : "Failed to run SCIP progress command.",
  })
  close()
})

          child.on("close", (code, signal) => {
            flushBuffer("stdout")
            flushBuffer("stderr")
            logger.set({
              ciExitCode: code,
              ciExitSignal: signal,
            })
            sendEvent("done", {
              at: new Date().toISOString(),
              code,
              signal,
            })
            close()
          })
        },
        cancel() {
          clearTimers()
          closed = true
          if (child && !child.killed) {
            child.kill("SIGTERM")
          }
        },
      })

      return {
        status: 200,
        outcome: "success",
        response: new Response(stream, {
          headers: {
            "content-type": "text/event-stream; charset=utf-8",
            "cache-control": "private, max-age=0, must-revalidate, no-transform",
            connection: "keep-alive",
            "x-accel-buffering": "no",
          },
        }),
      }
    },
  })
}

