import { Button } from "@/components/ui/button"
import {
  buildRepoMergeRequestDescriptionPath,
  buildRepoMergeRequestPath,
  buildRepoPath,
  buildRepoRouteId,
  findIntegrationByRepoRouteId,
} from "@/lib/gitlab/repo-route"
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { getSession } from "@/lib/session"

type MergeRequestDescriptionPageProps = {
  params: Promise<{
    integrationId: string
    mergeRequestIid: string
  }>
}

const integrationStatusLabel: Record<"active" | "degraded" | "disabled", string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const integrationStatusVariant: Record<"active" | "degraded" | "disabled", "default" | "secondary" | "outline"> = {
  active: "default",
  degraded: "secondary",
  disabled: "outline",
}

export default async function MergeRequestDescriptionPage({
  params,
}: MergeRequestDescriptionPageProps) {
  const [session, { integrationId: repoRouteId, mergeRequestIid }] = await Promise.all([
    getSession(),
    params,
  ])

  if (!session?.user?.id) {
    redirect("/")
  }

  const integrations = await getCachedUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)
  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(buildRepoMergeRequestDescriptionPath(integration, mergeRequestIid))
  }

  return (
    <div className="space-y-4">
      <section className="space-y-2">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="space-y-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-2xl font-semibold">MR Description</h1>
              <Badge variant={integrationStatusVariant[integration.status]}>
                {integrationStatusLabel[integration.status]}
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {integration.projectPath} · MR !{mergeRequestIid}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Button asChild size="sm" variant="outline">
              <Link href={buildRepoMergeRequestPath(integration, mergeRequestIid)}>Back to review</Link>
            </Button>
            <Button asChild size="sm" variant="outline">
              <Link href={buildRepoPath(integration)}>Repo workspace</Link>
            </Button>
          </div>
        </div>
      </section>

      <MergeRequestDescriptionStreamPage
        instanceUrl={integration.instanceUrl}
        token=""
        integrationId={integration.id}
        projectId={integration.projectId}
        mergeRequestIid={mergeRequestIid}
      />
    </div>
  )
}

const toErrorMessageChain = (error: unknown): string => {
  if (error instanceof Error) {
    const cause = (error as Error & { cause?: unknown }).cause
    if (cause) {
      return `${error.message}\n${toErrorMessageChain(cause)}`
    }
    return error.message
  }
  if (typeof error === "string") {
    return error
  }
  return ""
}

const isMissingAiReviewColumnError = (error: unknown) => {
  const message = toErrorMessageChain(error).toLowerCase()
  return (
    message.includes("ai_review_auto_post_enabled") &&
    (message.includes("does not exist") || message.includes("undefined column"))
  )
}

const withGitLabSchemaHint = async <T>(work: () => Promise<T>): Promise<T> => {
  try {
    return await work()
  } catch (error) {
    if (isMissingAiReviewColumnError(error)) {
      throw new Error(
        'Database schema is out of date for GitLab integrations. Run "bun run --cwd apps/web db:migrate" with DATABASE_URL set.',
        { cause: error },
      )
    }
    throw error
  }
}

const assertNonEmpty = (value: string, fieldName: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error(`${fieldName} is required.`)
  }
  return trimmed
}

const buildWebhookUrl = (integrationId: string) =>
  `${gitlabEnv.appPublicUrl}${GITLAB_WEBHOOK_PATH_PREFIX}/${integrationId}`

export const enqueueGitLabJob = async ({
  integrationId,
  jobType,
  deliveryId,
  normalizedPayload,
}: {
  integrationId: string
  jobType: GitLabJobType
  deliveryId?: string
  normalizedPayload?: Record<string, unknown>
}) => {
  await db.insert(gitlabJobs).values({
    integrationId,
    deliveryId,
    jobType,
    status: "pending",
    attempts: 0,
    nextAttemptAt: new Date(),
    normalizedPayload,
    updatedAt: new Date(),
  })
}

export const decryptIntegrationToken = (integration: GitLabIntegration) => {
  if (!integration.tokenCiphertext || !integration.tokenIv || !integration.tokenAuthTag) {
    throw new Error("No encrypted GitLab token is available for this integration.")
  }

  return decryptGitLabToken({
    ciphertext: integration.tokenCiphertext,
    iv: integration.tokenIv,
    authTag: integration.tokenAuthTag,
  })
}

const updateIntegrationToken = async (integrationId: string, token: string) => {
  const encrypted = encryptGitLabToken(token)
  await db
    .update(gitlabIntegrations)
    .set({
      tokenCiphertext: encrypted.ciphertext,
      tokenIv: encrypted.iv,
      tokenAuthTag: encrypted.authTag,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integrationId))
}

export const syncIntegrationWebhook = async ({
  integration,
  token,
}: {
  integration: GitLabIntegration
  token: string
}): Promise<SyncResult> => {
  const webhookSecret = generateWebhookSecret()
  const webhookSecretHash = hashWebhookSecret(webhookSecret)

  try {
    const { hookId } = await upsertProjectWebhook({
      instanceUrl: integration.instanceUrl,
      token,
      projectId: integration.projectId,
      callbackUrl: buildWebhookUrl(integration.id),
      secret: webhookSecret,
    })

    await db
      .update(gitlabIntegrations)
      .set({
        hookId,
        webhookUrl: buildWebhookUrl(integration.id),
        webhookSecretHash,
        status: "active",
        lastHookSyncAt: new Date(),
        lastError: null,
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integration.id))

    return { ok: true }
  } catch (error) {
    const message = toErrorMessage(error)
    await db
      .update(gitlabIntegrations)
      .set({
        status: "degraded",
        lastError: message,
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integration.id))

    return {
      ok: false,
      error: message,
    }
  }
}

export const connectGitLabIntegration = async ({
  userId,
  instanceUrl,
  token,
  projectId,
  projectPath,
  projectName,
}: {
  userId: string
  instanceUrl: string
  token: string
  projectId: string
  projectPath: string
  projectName: string
}) => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(instanceUrl)

const normalizedProjectId = assertNonEmpty(projectId, "projectId")
const normalizedProjectPath = assertNonEmpty(projectPath, "projectPath")
const normalizedProjectName = assertNonEmpty(projectName, "projectName")
const normalizedToken = assertNonEmpty(token, "token")

const existing = await db.query.gitlabIntegrations.findFirst({
  where: and(
    eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
    eq(gitlabIntegrations.projectId, normalizedProjectId),
  ),
})

if (existing) {
  await linkMembership(existing.id, userId)
  await enqueueGitLabJob({
    integrationId: existing.id,
    jobType: "hook_sync",
    normalizedPayload: {
      reason: "connect_existing",
    },
  })

  return {
    created: false,
    integration: integrationToSummary(existing),
    warning:
      existing.status === "active"
        ? undefined
        : "Integration linked. Hook verification queued in background.",
  }
}

const integrationId = randomUUID()
const encryptedToken = encryptGitLabToken(normalizedToken)
const bootstrapSecret = generateWebhookSecret()

const insertedRows = await db
  .insert(gitlabIntegrations)
  .values({
    id: integrationId,
    instanceUrl: normalizedInstanceUrl,
    projectId: normalizedProjectId,
    projectPath: normalizedProjectPath,
    projectName: normalizedProjectName,
    webhookUrl: buildWebhookUrl(integrationId),
    webhookSecretHash: hashWebhookSecret(bootstrapSecret),
    tokenCiphertext: encryptedToken.ciphertext,
    tokenIv: encryptedToken.iv,
    tokenAuthTag: encryptedToken.authTag,
    status: "degraded",
    lastError: "Pending initial webhook sync.",
  })
  .onConflictDoNothing()
  .returning()

const inserted = insertedRows[0]
if (!inserted) {
  const winner = await db.query.gitlabIntegrations.findFirst({
    where: and(
      eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
      eq(gitlabIntegrations.projectId, normalizedProjectId),
    ),
  })

  if (!winner) {
    throw new Error("Failed to resolve shared GitLab integration.")
  }

  await linkMembership(winner.id, userId)
  await enqueueGitLabJob({
    integrationId: winner.id,
    jobType: "hook_sync",
    normalizedPayload: {
      reason: "connect_race_winner",
    },
  })

  return {
    created: false,
    integration: integrationToSummary(winner),
    warning: "Integration linked. Hook verification queued in background.",
  }
}

await linkMembership(inserted.id, userId)

const syncResult = await syncIntegrationWebhook({
  integration: inserted,
  token: normalizedToken,
})

  const updatedIntegration = await getIntegrationById(inserted.id)
  if (!updatedIntegration) {
    throw new Error("Integration created but not found after sync.")
  }

  return {
    created: true,
    integration: integrationToSummary(updatedIntegration),
    warning: syncResult.ok ? undefined : syncResult.error,
  }
}

export const getUserIntegration = async (integrationId: string, userId: string) => {
  const rows = await withGitLabSchemaHint(() =>
    db
      .select({ integration: gitlabIntegrations })
      .from(gitlabIntegrationMemberships)
      .innerJoin(
        gitlabIntegrations,
        eq(gitlabIntegrationMemberships.integrationId, gitlabIntegrations.id),
      )
      .where(
        and(
          eq(gitlabIntegrationMemberships.integrationId, integrationId),
          eqGitLabMembershipUserId(userId),
        ),
      )
      .limit(1),
  )

  return rows[0]?.integration
}

export const resyncGitLabIntegration = async ({
  integration,
  token,
}: {
  integration: GitLabIntegration
  token?: string
}) => {
  const normalizedToken = token?.trim()

  let tokenToUse: string
  if (normalizedToken) {
    await updateIntegrationToken(integration.id, normalizedToken)
    tokenToUse = normalizedToken
  } else {
    tokenToUse = decryptIntegrationToken(integration)
  }

  const current = (await getIntegrationById(integration.id)) ?? integration
  const syncResult = await syncIntegrationWebhook({
    integration: current,
    token: tokenToUse,
  })

  const updated = await getIntegrationById(integration.id)
  if (!updated) {
    throw new Error("Integration no longer exists.")
  }

  return {
    integration: integrationToSummary(updated),
    warning: syncResult.ok ? undefined : syncResult.error,
  }
}

export const updateGitLabIntegrationAiReviewSettings = async ({
  integrationId,
  autoPostEnabled,
}: {
  integrationId: string
  autoPostEnabled: boolean
}) => {
  await db
    .update(gitlabIntegrations)
    .set({
      aiReviewAutoPostEnabled: autoPostEnabled,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integrationId))

  const updated = await getIntegrationById(integrationId)
  if (!updated) {
    throw new Error("Integration not found.")
  }
  return integrationToSummary(updated)
}

export const disconnectGitLabIntegration = async ({
  integration,
  userId,
}: {
  integration: GitLabIntegration
  userId: string
}) => {
  await db
    .delete(gitlabIntegrationMemberships)
    .where(
      and(
        eq(gitlabIntegrationMemberships.integrationId, integration.id),
        eqGitLabMembershipUserId(userId),
      ),
    )

  const countResult = await db
    .select({ value: count() })
    .from(gitlabIntegrationMemberships)
    .where(eq(gitlabIntegrationMemberships.integrationId, integration.id))

  const memberCount = Number(countResult[0]?.value ?? 0)
  if (memberCount > 0) {
    return {
      scope: "personal" as const,
      warning: undefined,
    }
  }

  let warning: string | undefined
  try {
    if (integration.tokenCiphertext && integration.tokenIv && integration.tokenAuthTag) {
      const token = decryptIntegrationToken(integration)
      await deleteProjectWebhook({
        instanceUrl: integration.instanceUrl,
        token,
        projectId: integration.projectId,
        callbackUrl: integration.webhookUrl,
        hookId: integration.hookId,
      })
    }
  } catch (error) {
    warning = `Hook cleanup warning: ${toErrorMessage(error)}`
  }

  await db
    .update(gitlabIntegrations)
    .set({
      hookId: null,
      webhookSecretHash: null,
      tokenCiphertext: null,
      tokenIv: null,
      tokenAuthTag: null,
      status: "disabled",
      lastError: warning ?? null,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integration.id))

  return {
    scope: "global" as const,
    warning,
  }
}

export const ingestWebhookDelivery = async ({
  integrationId,
  eventUuid,
  eventName,
  eventType,
  ref,
  payload,
  jobType,
  normalizedPayload,
}: {
  integrationId: string
  eventUuid: string
  eventName: string
  eventType: "push" | "merge_request" | "ignored"
  ref: string | null
  payload: Record<string, unknown>
  jobType?: "push" | "merge_request"
  normalizedPayload?: Record<string, unknown>
}) => {
  return db.transaction(async (tx) => {
    await tx
      .update(gitlabIntegrations)
      .set({
        lastWebhookReceivedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integrationId))

    const insertedDeliveries = await tx
      .insert(gitlabWebhookDeliveries)
      .values({
        integrationId,
        eventUuid,
        eventName,
        eventType,
        ref,
        payload,
      })
      .onConflictDoNothing()
      .returning({ id: gitlabWebhookDeliveries.id })

    const deliveryId = insertedDeliveries[0]?.id
    if (!deliveryId) {
      return {
        deduped: true,
        enqueued: false,
      }
    }

    if (jobType) {
      await tx.insert(gitlabJobs).values({
        integrationId,
        deliveryId,
        jobType,
        status: "pending",
        attempts: 0,
        nextAttemptAt: new Date(),
        normalizedPayload,
        updatedAt: new Date(),
      })
    }

    return {
      deduped: false,
      enqueued: Boolean(jobType),
    }
  })
}

import { asc, gte } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { onboardingEvents } from "@/lib/db/schema"
import type { ObservabilityOnboardingTtfrPayload } from "@/lib/observability"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const TTFR_SLO_MS = 20_000
const DEFAULT_WINDOW_DAYS = 30

type SessionMilestones = {
  userId: string
  instanceBucket: "US" | "Global" | "Custom" | "Unknown"
  errorClass: string
  startedAt: Date
  tokenValidatedAt: Date | null
  projectsReadyAt: Date | null
  mrsReadyAt: Date | null
  reviewOpenedAt: Date | null
  quickReviewOutputAt: Date | null
  fullIndexedReadyAt: Date | null
}

const percentile = (values: number[], p: number) => {
  if (values.length === 0) {
    return null
  }

  const sorted = [...values].sort((a, b) => a - b)
  const index = (sorted.length - 1) * p
  const lower = Math.floor(index)
  const upper = Math.ceil(index)

  if (lower === upper) {
    return Math.round(sorted[lower])
  }

  const weight = index - lower
  const blended = sorted[lower] * (1 - weight) + sorted[upper] * weight
  return Math.round(blended)
}

const toMs = (start: Date, end: Date | null) => {
  if (!end) {
    return null
  }

  return Math.max(0, end.getTime() - start.getTime())
}

const instanceBucketFromUrl = (value: string | null | undefined) => {
  const normalized = value?.trim().toLowerCase()
  if (!normalized) {
    return "Unknown" as const
  }

  if (normalized === "https://us.global.lmco.com") {
    return "US" as const
  }

  if (normalized === "https://gitlab.global.lmco.com") {
    return "Global" as const
  }

  return "Custom" as const
}

const getMetadataString = (value: unknown, key: string) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  return typeof record[key] === "string" && record[key]
    ? String(record[key])
    : null
}

const pushSession = (
  sessions: SessionMilestones[],
  current: SessionMilestones | null,
) => {
  if (!current) {
    return
  }

  sessions.push(current)
}

const aggregateByKey = (
  sessions: SessionMilestones[],
  key: "instanceBucket" | "errorClass",
) => {
  const grouped = new Map<string, number[]>()

  for (const session of sessions) {
    const ttfrMs = toMs(session.startedAt, session.reviewOpenedAt)
    if (ttfrMs === null) {
      continue
    }

    const bucket = String(session[key])
    const rows = grouped.get(bucket) ?? []
    rows.push(ttfrMs)
    grouped.set(bucket, rows)
  }

  return Array.from(grouped.entries())
    .map(([bucket, values]) => {
      const p50Ms = percentile(values, 0.5)
      const p95Ms = percentile(values, 0.95)
      return {
        bucket,
        count: values.length,
        p50Ms,
        p95Ms,
        sloBreached: p95Ms !== null && p95Ms > TTFR_SLO_MS,
      }
    })
    .sort((a, b) => b.count - a.count)
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/observability/onboarding-ttfr",
    event: "api.observability.onboarding_ttfr",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const since = new Date(Date.now() - DEFAULT_WINDOW_DAYS * 24 * 60 * 60 * 1000)

const rows = await db
  .select({
    userId: onboardingEvents.userId,
    event: onboardingEvents.event,
    createdAt: onboardingEvents.createdAt,
    metadata: onboardingEvents.metadata,
  })
  .from(onboardingEvents)
  .where(gte(onboardingEvents.createdAt, since))
  .orderBy(asc(onboardingEvents.userId), asc(onboardingEvents.createdAt))

const sessions: SessionMilestones[] = []
let current: SessionMilestones | null = null

for (const row of rows) {
  if (row.event === "onboarding_started") {
    pushSession(sessions, current)
    current = {
      userId: row.userId,
      instanceBucket: instanceBucketFromUrl(
        getMetadataString(row.metadata, "instanceUrl"),
      ),
      errorClass: getMetadataString(row.metadata, "errorCode") ?? "none",
      startedAt: row.createdAt,
      tokenValidatedAt: null,
      projectsReadyAt: null,
      mrsReadyAt: null,
      reviewOpenedAt: null,
      quickReviewOutputAt: null,
      fullIndexedReadyAt: null,
    }
    continue
  }

  if (!current || current.userId !== row.userId) {
    continue
  }

  const instanceUrl = getMetadataString(row.metadata, "instanceUrl")
  if (instanceUrl) {
    current.instanceBucket = instanceBucketFromUrl(instanceUrl)
  }

  const errorCode = getMetadataString(row.metadata, "errorCode")
  if (errorCode) {
    current.errorClass = errorCode
  }

  if (row.event === "onboarding_token_validated" && !current.tokenValidatedAt) {
    current.tokenValidatedAt = row.createdAt
  }
  if (row.event === "onboarding_projects_ready" && !current.projectsReadyAt) {
    current.projectsReadyAt = row.createdAt
  }
  if (row.event === "onboarding_mrs_ready" && !current.mrsReadyAt) {
    current.mrsReadyAt = row.createdAt
  }
  if (row.event === "onboarding_review_opened" && !current.reviewOpenedAt) {
    current.reviewOpenedAt = row.createdAt
  }
  if (
    row.event === "onboarding_quick_review_output" &&
    !current.quickReviewOutputAt
  ) {
    current.quickReviewOutputAt = row.createdAt
  }
  if (
    row.event === "onboarding_full_review_ready" &&
    !current.fullIndexedReadyAt
  ) {
    current.fullIndexedReadyAt = row.createdAt
  }
}

pushSession(sessions, current)

const sessionTtfrValues = sessions
  .map((session) => toMs(session.startedAt, session.reviewOpenedAt))
  .filter((value): value is number => value !== null)

const responsePayload: ObservabilityOnboardingTtfrPayload = {
  windowDays: DEFAULT_WINDOW_DAYS,
  sloTargetMs: TTFR_SLO_MS,
  summary: {
    totalSessions: sessions.length,
    sessionsWithTtfr: sessionTtfrValues.length,
    p50Ms: overallP50,
    p95Ms: overallP95,
    sloBreached: overallP95 !== null && overallP95 > TTFR_SLO_MS,
  },
  byInstance,
  byErrorClass,
  stageBreakdown: {
    tokenValidatedMs: {
      p50Ms: percentile(stageValues.tokenValidatedMs, 0.5),
      p95Ms: percentile(stageValues.tokenValidatedMs, 0.95),
    },
    projectsReadyMs: {
      p50Ms: percentile(stageValues.projectsReadyMs, 0.5),
      p95Ms: percentile(stageValues.projectsReadyMs, 0.95),
    },
    mrsReadyMs: {
      p50Ms: percentile(stageValues.mrsReadyMs, 0.5),
      p95Ms: percentile(stageValues.mrsReadyMs, 0.95),
    },
    reviewOpenedMs: {
      p50Ms: percentile(stageValues.reviewOpenedMs, 0.5),
      p95Ms: percentile(stageValues.reviewOpenedMs, 0.95),
    },
    quickReviewOutputMs: {
      p50Ms: percentile(stageValues.quickReviewOutputMs, 0.5),
      p95Ms: percentile(stageValues.quickReviewOutputMs, 0.95),
    },
    fullIndexedReadyMs: {
      p50Ms: percentile(stageValues.fullIndexedReadyMs, 0.5),
      p95Ms: percentile(stageValues.fullIndexedReadyMs, 0.95),
    },
  },
  alerts,
}

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(responsePayload),
      }
    },
  })
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { traceGraph, CodeTraceError } from "@/lib/argus-search/trace-callers"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const tracePayloadSchema = z
  .object({
    mode: z.enum(["callers", "impact"]).optional(),
    symbol: z.string().trim().min(1).max(300).optional(),
    nodeId: z.string().trim().min(1).max(500).optional(),
    limit: z.number().int().positive().max(200).optional(),
    depth: z.number().int().positive().max(64).optional(),
  })
  .superRefine((value, ctx) => {
    if (!value.symbol && !value.nodeId) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Either symbol or nodeId is required.",
      })
    }
  })

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/trace-callers",
    event: "api.code.trace_callers",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => ({})),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }
      const parsed = tracePayloadSchema.safeParse(payload)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid trace payload." }, { status: 400 }),
  }
}

const { mode = "callers", symbol, nodeId, limit, depth } = parsed.data

try {
  const results = await traceGraph({
    mode,
    symbol,
    nodeId,
    limit,
    depth: mode === "impact" ? depth : undefined,
  })

  logger.set({
    mode,
    symbol: symbol ?? null,
    nodeId: nodeId ?? null,
    depth: mode === "impact" ? depth ?? 3 : null,
    callersCount: results.length,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        mode,
        symbol: symbol ?? null,
        nodeId: nodeId ?? null,
        depth: mode === "impact" ? depth ?? 3 : null,
        count: results.length,
        results,
      },
    }),
  }
} catch (error) {

        if (error instanceof CodeTraceError) {
          const status = error.code === "binary_missing" ? 503 : 502
          logger.set({
            traceErrorCode: error.code,
            traceErrorDetails: error.details,
          })

          return {
            status,
            outcome: "trace_failed",
            response: NextResponse.json(
              {
                error:
                  error.code === "binary_missing"
                    ? "Code intelligence CLI is unavailable."
                    : "Failed to trace code graph.",
              },
              { status },
            ),
          }
        }

        logger.set({
          traceErrorCode: "unknown",
        })

        return {
          status: 500,
          outcome: "trace_failed",
          response: NextResponse.json({ error: "Failed to trace code graph." }, { status: 500 }),
        }
      }
    },
  })
}

