import { NextResponse } from "next/server"
import { z } from "zod"

import {
  computeAndPersistReviewImpacts,
  loadPersistedReviewImpacts,
  ReviewImpactServiceError,
} from "@/lib/review/impact-service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const reviewIdSchema = z.string().trim().min(1)
const postPayloadSchema = z.object({
  reviewId: reviewIdSchema,
  force: z.boolean().optional(),
})

const parseReviewId = (value: unknown) => {
  const parsed = reviewIdSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }
  return parsed.data
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/impact",
    event: "api.review.impact.get",
    handler: async () => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const reviewId = parseReviewId(new URL(request.url).searchParams.get("reviewId"))
      if (!reviewId) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "reviewId is required." }, { status: 400 }),
        }
      }

      let data
      try {
        data = await loadPersistedReviewImpacts({ userId, reviewId })
      } catch (error) {
        if (error instanceof ReviewImpactServiceError && error.code === "not_found") {
          return {
            status: 404,
            outcome: "not_found",
            response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
          }
        }
        throw error
      }
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data }),
      }
    },
  })
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/impact",
    event: "api.review.impact.post",
    handler: async () => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => ({})),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = postPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "reviewId is required." }, { status: 400 }),
        }
      }

      let data
      try {
        data = await computeAndPersistReviewImpacts({
          userId,
          reviewId: parsed.data.reviewId,
          force: parsed.data.force ?? false,
        })
      } catch (error) {
        if (error instanceof ReviewImpactServiceError && error.code === "not_found") {
          return {
            status: 404,
            outcome: "not_found",
            response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
          }
        }
        throw error
      }

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data }),
      }
    },
  })
}

