const log2p = (value: number) => Math.log2(1 + Math.max(0, value))

export const computeImpactScore = (input: {
  callersCount: number
  dependentsCount: number
  calleesCount: number
  dependenciesCount: number
  affectedFilesCount: number
}) => {
  const raw =
    20 * log2p(input.callersCount) +
    18 * log2p(input.dependentsCount) +
    12 * log2p(input.calleesCount) +
    10 * log2p(input.dependenciesCount) +
    8 * log2p(input.affectedFilesCount)

  return Math.max(0, Math.min(100, Math.round(raw)))
}

export const computeImpactLevel = (score: number): "low" | "med" | "high" => {
  if (score >= 70) {
    return "high"
  }
  if (score >= 35) {
    return "med"
  }
  return "low"
}

