const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const normalizeStderr = (stderr: string | undefined) => {
  const trimmed = stderr?.trim()
  if (!trimmed) {
    return null
  }

  return trimmed.slice(0, 1_500)
}

const parseManifest = (raw: string): CodeGraphSummary => {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    throw new CodeGraphError("invalid_output", "Failed to parse graph index-pack manifest JSON.", null)
  }

  const validated = indexPackManifestSchema.safeParse(parsed)
  if (!validated.success) {
    throw new CodeGraphError("invalid_output", "Graph index-pack manifest did not match expected schema.", {
      issues: validated.error.issues.map((issue) => issue.message),
    })
  }

  const stats = validated.data.stats
  return {
    indexRunId: validated.data.indexRunId,
    generatedAt: validated.data.generatedAt,
    schemaVersion: validated.data.schemaVersion,
    stats: {
      filesParsed: stats?.filesParsed ?? 0,
      chunksEmitted: stats?.chunksEmitted ?? 0,
      nodesEmitted: stats?.nodesEmitted ?? 0,
      edgesEmitted: stats?.edgesEmitted ?? 0,
    },
  }
}

export const getCodeGraphSummary = async (): Promise<CodeGraphSummary | null> => {
  try {
    const raw = await readFile(resolveManifestPath(), "utf8")
    return parseManifest(raw)
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: string }).code === "ENOENT"
    ) {
      return null
    }

    if (error instanceof CodeGraphError) {
      throw error
    }

    throw new CodeGraphError("invalid_output", "Failed to read graph index-pack manifest.", {
      message: errorMessage(error),
    })
  }
}

