const CHAT_TIMEOUT_MS = 30_000
const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const DEFAULT_AI_MODEL = "gpt-4o-mini"
const MAX_PROVIDER_ERROR_LENGTH = 260
const MAX_QUESTION_LENGTH = 1_200

type ChatMessage = {
  role: "user" | "assistant"
