  apiUrl: z.string().trim().min(1).optional(),
  model: z.string().trim().min(1).optional(),
  token: z.string().optional(),
})

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const isPrivateOrLocalHost = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  if (
    normalized === "localhost" ||
    normalized.endsWith(".localhost") ||
    normalized === "0.0.0.0" ||
    normalized === "::1" ||
    normalized.endsWith(".local") ||
    normalized.endsWith(".internal")
  ) {
    return true
  }

  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(normalized)) {
    const octets = normalized.split(".").map((part) => Number.parseInt(part, 10))
    if (octets.some((value) => !Number.isFinite(value) || value < 0 || value > 255)) {
      return true
    }

    const [a, b] = octets
    if (
      a === 10 ||
      a === 127 ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127)
    ) {
      return true
    }
  }

  if (
    normalized.includes(":") &&
    (normalized.startsWith("fc") || normalized.startsWith("fd") || normalized.startsWith("fe80:"))
  ) {
    return true
  }

  return false
}

const resolveApiUrl = (rawApiUrl: string) => {
  let parsed: URL
  try {
    parsed = new URL(rawApiUrl)
  } catch {
    throw new Error("API URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("API URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("API URL must not include credentials.")
  }
  if (isPrivateOrLocalHost(parsed.hostname)) {
    throw new Error("API URL must not target localhost or private network hosts.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const getEnvModel = () =>
  pickFirstNonEmpty(
    process.env.AI_MODEL,
    process.env.OPENAI_MODEL,
  ) || DEFAULT_AI_MODEL

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  )

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderErrorMessage = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  const trimmed = bodyText.trim()
  if (!trimmed) {
    return ""
  }

  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    const root = parsed as Record<string, unknown>
    if (typeof root.error === "string" && root.error.trim().length > 0) {
      return root.error.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    if (root.error && typeof root.error === "object" && !Array.isArray(root.error)) {
      const nested = root.error as Record<string, unknown>
      if (typeof nested.message === "string" && nested.message.trim().length > 0) {
        return nested.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
      }
    }

    if (typeof root.message === "string" && root.message.trim().length > 0) {
      return root.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }
  } catch {
    return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
  }

  return ""
}

const buildNetworkErrorMessage = (error: unknown) => {
  if (error instanceof Error && error.name === "AbortError") {
    return `AI request timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return `AI request failed before response: ${error.message}`
  }

  return "AI request failed before response."
}

const extractMessageText = (content: unknown): string => {
  if (typeof content === "string") {
    return content.trim()
  }

  if (!Array.isArray(content)) {
    return ""
  }

  const parts = content
    .map((part) => {
      if (!part || typeof part !== "object" || Array.isArray(part)) {
        return ""
      }
      const candidate = part as Record<string, unknown>
      if (typeof candidate.text === "string") {
        return candidate.text
      }
      if (candidate.type === "text" && typeof candidate.content === "string") {
        return candidate.content
      }
      return ""
    })
    .filter((part) => part.trim().length > 0)

  return parts.join("\n").trim()
}

