const hasCustomApiUrl = clientApiUrl.length > 0 && clientApiUrl !== serverApiUrl

const model = parsed.data.model?.trim() || getEnvModel()
const clientToken = parsed.data.token?.trim() ?? ""
const token = clientToken || (hasCustomApiUrl ? "" : getEnvToken())

if (!token) {
  return {
    status: 400,
    outcome: hasCustomApiUrl ? "invalid_request" : "missing_config",
    response: NextResponse.json(
      {
        error: hasCustomApiUrl
          ? "Custom API URL requires an explicit token."
          : "AI token missing. Set API token in settings or server env.",
      },
      { status: 400 },
    ),
  }
}

const history: ChatMessage[] = (parsed.data.history ?? [])
  .map((entry) => ({
    role: entry.role,
    content: entry.content.trim(),
  }))
  .filter((entry) => entry.content.length > 0)

const controller = new AbortController()
const timeout = setTimeout(() => {
  controller.abort()
}, CHAT_TIMEOUT_MS)
const startedAt = Date.now()
const provider = resolveLlmProviderLabel(apiUrl)

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      max_tokens: 420,
      messages: toPromptMessages({
        question: parsed.data.question,
        history,
        pathname: parsed.data.pathname ?? "",
      }),
    }),
    signal: controller.signal,
  })

if (!response.ok) {
  const providerError = await readProviderErrorMessage(response)
  const suffix = providerError ? ` ${providerError}` : ""
  logger.set({
    model,
    providerStatus: response.status,
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: `AI provider request failed (${response.status}).${suffix}`,
        providerStatus: response.status,
      },
      { status: 502 },
    ),
  }
}

const latencyMs = Math.max(1, Date.now() - startedAt)
const providerPayload = (await response.json().catch(() => null)) as ProviderChatResponse | null
const answer = extractMessageText(providerPayload?.choices?.[0]?.message?.content)
if (!answer) {
  logger.set({
    model,
    responseError: "empty_message",
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: "AI response did not include a message.",
      },
      { status: 502 },
    ),
  }
}

const usage = extractUsageFromOpenAiCompatiblePayload(providerPayload)

        logger.set({
          model,
          latencyMs,
          labels: {
            provider,
            model,
          },
          llmMetrics: buildLlmMetrics({
            provider,
            model,
            promptTokens: usage.promptTokens,
            completionTokens: usage.completionTokens,
            totalTokens: usage.totalTokens,
            latencyMs,
            requestCount: 1,
          }),
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ answer }),
        }
      } catch (error) {
        const message = buildNetworkErrorMessage(error)
        logger.set({
          model,
          networkError: message,
          labels: {
            provider,
            model,
          },
        })
        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json(
            { error: message },
            { status: 502 },
          ),
        }
      } finally {
        clearTimeout(timeout)
      }
    },
  })
}

