export const toError = (value: unknown, fallbackMessage = "Unknown error."): Error => {
  if (value instanceof Error) {
    return value
  }

  if (typeof value === "string" && value.trim().length > 0) {
    return new Error(value)
  }

  return new Error(fallbackMessage)
}

export const errorMessage = (value: unknown, fallbackMessage = "Unknown error."): string => {
  if (value instanceof Error) {
    return value.message
  }

  if (typeof value === "string" && value.trim().length > 0) {
    return value
  }

  return fallbackMessage
}

export const isOnboardingPath = (pathname: string | null | undefined) => {
  if (!pathname) {
    return false
