export type SiteHeaderBreadcrumb = {
  label: string
  href: string | null
}

const SEGMENT_LABELS: Record<string, string> = {
  "code-graph": "Code Graph",
  integrations: "Integrations",
  indexing: "Indexing",
  "indexing-health": "Indexing Health",
  logs: "Log Explorer",
  mrs: "Merge Requests",
  model: "Model",
  observability: "Observability",
  onboarding: "Onboarding",
  "onboarding-ttfr": "Onboarding TTFR",
  projects: "Projects",
  repos: "Repositories",
  "sldc-flow": "SLDC Flow",
  settings: "Settings",
  tokens: "Tokens",
  description: "Description",
}

const decodeSegment = (segment: string) => {
  try {
    return decodeURIComponent(segment)
  } catch {
    return segment
  }
}

const toTitleCase = (value: string) =>
  value
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => (
      word.length <= 2
        ? word.toUpperCase()
        : `${word[0]?.toUpperCase() ?? ""}${word.slice(1)}`
    ))
    .join(" ")

const humanize = (value: string) => {
  const normalized = value
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()

  return normalized ? toTitleCase(normalized) : value
}

const formatRepoRouteId = (value: string) => {
  const parts = value.split("--")
  if (parts.length < 3) {
    return humanize(value)
  }

  const projectToken = parts[1]?.trim()
  if (!projectToken) {
    return humanize(value)
  }

  return humanize(projectToken)
}

const segmentLabel = (segments: string[], index: number) => {
  const current = decodeSegment(segments[index] ?? "")
  const previous = decodeSegment(segments[index - 1] ?? "")

  if (previous === "repos") {
    return formatRepoRouteId(current)
  }

  if (previous === "mrs") {
    return `!${current}`
  }

  return SEGMENT_LABELS[current] ?? humanize(current)
}

export const buildSiteHeaderBreadcrumbs = (pathname: string): SiteHeaderBreadcrumb[] => {
  const rawSegments = pathname.split("/").filter(Boolean)
  const segments = rawSegments.filter((segment, index) => {
    const current = decodeSegment(segment)
    const twoBack = decodeSegment(rawSegments[index - 2] ?? "")

    if (current === "description" && twoBack === "mrs") {
      return false
    }

    return true
  })

  if (segments.length === 0) {
    return [{ label: "Home", href: null }]
  }

  return segments.map((_, index) => {
    const isLast = index === segments.length - 1
    const href = isLast ? null : `/${segments.slice(0, index + 1).join("/")}`

    return {
      label: segmentLabel(segments, index),
      href,
    }
  })
}

export const resolveSiteHeaderTitle = (
  explicitTitle: string | null,
) => (explicitTitle?.trim() ? explicitTitle : null)

import { inArray, sql } from 'drizzle-orm'
import { parsePositiveInt } from '@argus/shared-config'

import { db } from '@/lib/db'
import { indexEmbeddingCache } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@/lib/indexing/constants'
import type { VectorChunkRecord } from '@/lib/indexing/contracts'
import { estimateEmbeddingCostUsd } from '@/lib/observability'
import { sha256Hex } from '@/lib/utils/hash'

type EmbeddingProvider = 'openai' | 'deterministic'

export type EmbeddingTelemetry = {
  provider: EmbeddingProvider
  model: string
  inputCount: number
  cacheHitCount: number
  cacheMissCount: number
  requestCount: number
  failureCount: number
  promptTokens: number
  totalTokens: number
  latencyMs: number
  costUsd: number | null
}

type EmbedTelemetryHook = (telemetry: EmbeddingTelemetry) => void

const DEFAULT_EMBEDDING_MODEL = 'text-embedding-3-small'
const DEFAULT_OPENAI_BASE_URL = 'https://api.openai.com/v1'
const DEFAULT_MAX_REQUEST_TOKENS = 8_000

const asNonNegativeInt = (value: unknown): number | null => {
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
    return Math.floor(value)
  }

  if (typeof value === 'string' && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed
    }
  }

  return null
}

const createEmbeddingRequestError = (message: string, retryable: boolean) => {
  const error = new Error(message) as Error & { retryable?: boolean }
  error.retryable = retryable
  return error
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

const normalizeEmbedding = (embedding: number[]): number[] => {
  if (embedding.length !== INDEX_VECTOR_DIMENSION) {
    throw new Error(
      `Embedding dimension mismatch. Expected ${INDEX_VECTOR_DIMENSION}, received ${embedding.length}.`,
    )
  }

  return embedding.map((value) => {
    if (!Number.isFinite(value)) {
      throw new Error('Embedding contains non-finite values.')
    }

    return Number(value.toFixed(8))
  })
}

const embedTextDeterministic = (text: string, dimension: number): number[] => {
  const values: number[] = []
  let counter = 0

  while (values.length < dimension) {
    const hash = sha256Hex(`${text}:${counter}`)
    for (let offset = 0; offset < hash.length && values.length < dimension; offset += 2) {
      const byte = Number.parseInt(hash.slice(offset, offset + 2), 16)
      const normalized = (byte / 255) * 2 - 1
      values.push(Number(normalized.toFixed(8)))
    }
    counter += 1
  }

  return values
}

const resolveProvider = (): EmbeddingProvider => {
  const configured = process.env.INDEXER_EMBEDDING_PROVIDER?.trim().toLowerCase()
  if (configured === 'deterministic') {
    return 'deterministic'
  }

  return 'openai'
}

const resolveEmbeddingModel = () =>
  process.env.INDEXER_EMBEDDING_MODEL?.trim() ||
  process.env.OPENAI_EMBEDDING_MODEL?.trim() ||
  DEFAULT_EMBEDDING_MODEL

const resolveBaseUrl = () =>
  (process.env.INDEXER_EMBEDDING_BASE_URL?.trim() ||
    process.env.OPENAI_BASE_URL?.trim() ||
    DEFAULT_OPENAI_BASE_URL
  ).replace(/\/+$/, '')

const resolveApiKey = () =>
  process.env.INDEXER_EMBEDDING_API_KEY?.trim() || process.env.OPENAI_API_KEY?.trim() || ''

const resolveMaxRequestTokens = () =>
  parsePositiveInt(
    process.env.INDEXER_EMBEDDING_MAX_REQUEST_TOKENS,
    parsePositiveInt(process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS, DEFAULT_MAX_REQUEST_TOKENS),
  )

const estimateTokenUpperBound = (input: string) => Math.max(1, Buffer.byteLength(input, 'utf8'))

const buildEmbeddingBatches = (args: {
  inputs: string[]
  maxBatchSize: number
  maxRequestTokens: number
}): string[][] => {
  const maxBatchSize = Math.max(1, args.maxBatchSize)
  const maxRequestTokens = Math.max(1, args.maxRequestTokens)
  const batches: string[][] = []
  let currentBatch: string[] = []
  let currentBatchTokens = 0

  for (const input of args.inputs) {
    const estimatedTokens = estimateTokenUpperBound(input)
    if (currentBatch.length > 0) {
      const exceedsBatchSize = currentBatch.length >= maxBatchSize
      const exceedsTokenBudget = currentBatchTokens + estimatedTokens > maxRequestTokens
      if (exceedsBatchSize || exceedsTokenBudget) {
        batches.push(currentBatch)
        currentBatch = []
        currentBatchTokens = 0
      }
    }

    currentBatch.push(input)
    currentBatchTokens += estimatedTokens
  }

  if (currentBatch.length > 0) {
    batches.push(currentBatch)
  }

  return batches
}

const collectUniqueMisses = (args: {
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  cached: Map<string, { model: string; embedding: number[] }>
  model: string
}): Array<{ chunkId: string; content: string }> => {
  const uniqueMisses = new Map<string, { chunkId: string; content: string }>()

  for (const chunk of args.chunks) {
    const hit = args.cached.get(chunk.chunkId)
    if (hit && hit.model === args.model && hit.embedding.length === INDEX_VECTOR_DIMENSION) {
      continue
    }

    if (!uniqueMisses.has(chunk.chunkId)) {
      uniqueMisses.set(chunk.chunkId, {
        chunkId: chunk.chunkId,
        content: chunk.content,
      })
    }
  }

  return [...uniqueMisses.values()]
}

const resolveCacheModelKey = () => {
  const provider = resolveProvider()
  if (provider === 'deterministic') {
    return 'deterministic:sha256-v1'
  }

  return `openai:${resolveBaseUrl()}:${resolveEmbeddingModel()}`
}

const resolveTelemetryModel = () => {
  if (resolveProvider() === 'deterministic') {
    return 'deterministic:sha256-v1'
  }

  return resolveEmbeddingModel()
}

const parseOpenAiResponse = (payload: unknown): {
  embeddings: number[][]
  promptTokens: number
  totalTokens: number
} => {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid embedding response payload.')
  }

  const root = payload as {
    data?: unknown
    usage?: {
      prompt_tokens?: unknown
      total_tokens?: unknown
      promptTokens?: unknown
      totalTokens?: unknown
    } | null
  }
  const maybeData = root.data
  if (!Array.isArray(maybeData)) {
    throw new Error('Embedding response missing data array.')
  }

  const embeddings = maybeData.map((entry, index) => {
    const embedding = (entry as { embedding?: unknown })?.embedding
    if (!Array.isArray(embedding)) {
      throw new Error(`Embedding response item ${index} is missing embedding array.`)
    }

    return normalizeEmbedding(embedding as number[])
  })

  const promptTokens =
    asNonNegativeInt(root.usage?.prompt_tokens) ??
    asNonNegativeInt(root.usage?.promptTokens) ??
    0
  const totalTokens =
    asNonNegativeInt(root.usage?.total_tokens) ??
    asNonNegativeInt(root.usage?.totalTokens) ??
    promptTokens

  return {
    embeddings,
    promptTokens,
    totalTokens,
  }
}

const requestOpenAiEmbeddings = async (
  inputs: string[],
  telemetry?: EmbeddingTelemetry,
): Promise<number[][]> => {
  const apiKey = resolveApiKey()
  if (!apiKey) {
    if (telemetry) {
      telemetry.failureCount += 1
    }
    throw new Error(
      'Missing embedding API key. Set INDEXER_EMBEDDING_API_KEY (or OPENAI_API_KEY).',
    )
  }

const model = resolveEmbeddingModel()
const url = `${resolveBaseUrl()}/embeddings`
const timeoutMs = parsePositiveInt(process.env.INDEXER_EMBEDDING_TIMEOUT_MS, 30_000)
const maxAttempts = parsePositiveInt(process.env.INDEXER_EMBEDDING_RETRIES, 3)

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {

try {
  if (telemetry) {
    telemetry.requestCount += 1
  }

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      input: inputs,
    }),
    signal: AbortSignal.timeout(timeoutMs),
  })

  if (!response.ok) {
    const bodyText = (await response.text()).slice(0, 500)
    const isRetryable = response.status === 429 || response.status >= 500
    if (!isRetryable || attempt === maxAttempts) {
      throw createEmbeddingRequestError(
        `Embedding request failed (${response.status}): ${bodyText || response.statusText}`,
        isRetryable,
      )
    }

    await sleep(200 * 2 ** (attempt - 1))
    continue
  }

  const payload = await response.json()
  const parsed = parseOpenAiResponse(payload)
  const embeddings = parsed.embeddings
  if (embeddings.length !== inputs.length) {
    throw new Error(
      `Embedding response count mismatch. Expected ${inputs.length}, received ${embeddings.length}.`,
    )
  }
  if (telemetry) {
    telemetry.promptTokens += parsed.promptTokens
    telemetry.totalTokens += parsed.totalTokens
  }

  return embeddings
} catch (error) {

      const retryable = (error as { retryable?: unknown })?.retryable
      const shouldRetry = retryable === false ? false : attempt < maxAttempts
      if (!shouldRetry) {
        if (telemetry) {
          telemetry.failureCount += 1
        }
        throw error
      }

      await sleep(200 * 2 ** (attempt - 1))
    }
  }

  throw new Error('Embedding request failed unexpectedly.')
}

const createEmptyTelemetry = (args: {
  inputCount: number
  cacheHitCount: number
  cacheMissCount: number
}): EmbeddingTelemetry => ({
  provider: resolveProvider(),
  model: resolveTelemetryModel(),
  inputCount: args.inputCount,
  cacheHitCount: args.cacheHitCount,
  cacheMissCount: args.cacheMissCount,
  requestCount: 0,
  failureCount: 0,
  promptTokens: 0,
  totalTokens: 0,
  latencyMs: 0,
  costUsd: null,
})

const finalizeTelemetry = (telemetry: EmbeddingTelemetry, startedAt: number) => {
  telemetry.latencyMs = Math.max(0, Date.now() - startedAt)
  telemetry.costUsd = estimateEmbeddingCostUsd({
    model: telemetry.model,
    totalTokens: telemetry.totalTokens,
  })
}

const emitTelemetry = (hook: EmbedTelemetryHook | undefined, telemetry: EmbeddingTelemetry) => {
  if (!hook) {
    return
  }

  try {
    hook(telemetry)
  } catch {
    // Telemetry hook errors must never break embedding flow.
  }
}

const embedTexts = async (inputs: string[], telemetry?: EmbeddingTelemetry): Promise<number[][]> => {
  if (inputs.length === 0) {
    return []
  }

  if (resolveProvider() === 'deterministic') {
    return inputs.map((input) => normalizeEmbedding(embedTextDeterministic(input, INDEX_VECTOR_DIMENSION)))
  }

  const batchSize = parsePositiveInt(process.env.INDEXER_EMBEDDING_BATCH_SIZE, 32)
  const maxRequestTokens = resolveMaxRequestTokens()
  const batches = buildEmbeddingBatches({
    inputs,
    maxBatchSize: batchSize,
    maxRequestTokens,
  })
  const output: number[][] = []

  for (const batch of batches) {
    const vectors = await requestOpenAiEmbeddings(batch, telemetry)
    output.push(...vectors)
  }

  if (telemetry && telemetry.provider === 'openai' && telemetry.promptTokens <= 0) {
    const estimatedPromptTokens = inputs.reduce(
      (sum, input) => sum + estimateTokenUpperBound(input),
      0,
    )
    telemetry.promptTokens = Math.max(0, estimatedPromptTokens)
    telemetry.totalTokens = Math.max(telemetry.totalTokens, telemetry.promptTokens)
  }

  return output
}

const loadCache = async (chunkIds: string[]) => {
  if (chunkIds.length === 0) {
    return new Map<string, { model: string; embedding: number[] }>()
  }

  const rows = await db
    .select({
      chunkId: indexEmbeddingCache.chunkId,
      model: indexEmbeddingCache.model,
      embedding: indexEmbeddingCache.embedding,
    })
    .from(indexEmbeddingCache)
    .where(inArray(indexEmbeddingCache.chunkId, chunkIds))

  return new Map(rows.map((row) => [row.chunkId, { model: row.model, embedding: row.embedding }]))
}

const upsertCache = async (items: Array<{ chunkId: string; embedding: number[] }>): Promise<void> => {
  if (items.length === 0) {
    return
  }

  const now = new Date()
  const model = resolveCacheModelKey()

  await db
    .insert(indexEmbeddingCache)
    .values(
      items.map((item) => ({
        chunkId: item.chunkId,
        model,
        embedding: item.embedding,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: indexEmbeddingCache.chunkId,
      set: {
        model,
        embedding: sql`excluded.embedding`,
        updatedAt: now,
      },
    })
}

export const embedQueryText = async (
  query: string,
  options: { onTelemetry?: EmbedTelemetryHook } = {},
): Promise<number[]> => {
  const startedAt = Date.now()
  const telemetry = createEmptyTelemetry({
    inputCount: 1,
    cacheHitCount: 0,
    cacheMissCount: 1,
  })

  try {
    const [embedding] = await embedTexts([query], telemetry)
    if (!embedding) {
      telemetry.failureCount = Math.max(1, telemetry.failureCount)
      throw new Error('Failed to embed query text.')
    }

    return embedding
  } catch (error) {
    telemetry.failureCount = Math.max(1, telemetry.failureCount)
    throw error
  } finally {
    finalizeTelemetry(telemetry, startedAt)
    emitTelemetry(options.onTelemetry, telemetry)
  }
}

export const embedVectorChunks = async (
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>,
  options: { onTelemetry?: EmbedTelemetryHook } = {},
): Promise<VectorChunkRecord[]> => {
  if (chunks.length === 0) {
    return []
  }

  const chunkIds = [...new Set(chunks.map((chunk) => chunk.chunkId))]
  const model = resolveCacheModelKey()
  const cached = await loadCache(chunkIds)
  const misses = collectUniqueMisses({
    chunks,
    cached,
    model,
  })
  const startedAt = Date.now()
  const telemetry = createEmptyTelemetry({
    inputCount: misses.length,
    cacheHitCount: Math.max(0, chunkIds.length - misses.length),
    cacheMissCount: misses.length,
  })

  const missEmbeddings = new Map<string, number[]>()

try {
  if (misses.length > 0) {
    const vectors = await embedTexts(
      misses.map((miss) => miss.content),
      telemetry,
    )
    misses.forEach((miss, index) => {
      const vector = vectors[index]
      if (!vector) {
        telemetry.failureCount = Math.max(1, telemetry.failureCount)
        throw new Error(`Missing embedding response for chunk ${miss.chunkId}.`)
      }

      missEmbeddings.set(miss.chunkId, vector)
    })

    await upsertCache(
      misses.map((miss) => {
        const embedding = missEmbeddings.get(miss.chunkId)
        if (!embedding) {
          telemetry.failureCount = Math.max(1, telemetry.failureCount)
          throw new Error(`Missing embedding cache payload for chunk ${miss.chunkId}.`)
        }

        return {
          chunkId: miss.chunkId,
          embedding,
        }
      }),
    )
  }

  return chunks.map((chunk) => {
    const cacheHit = cached.get(chunk.chunkId)
    const embedding = missEmbeddings.get(chunk.chunkId) ?? cacheHit?.embedding
    if (!embedding) {
      telemetry.failureCount = Math.max(1, telemetry.failureCount)
      throw new Error(`Embedding unavailable for chunk ${chunk.chunkId}.`)
    }

    return {
      ...chunk,
      embedding: normalizeEmbedding(embedding),
    }
  })
} catch (error) {
  telemetry.failureCount = Math.max(1, telemetry.failureCount)
  throw error
} finally {
  finalizeTelemetry(telemetry, startedAt)
  emitTelemetry(options.onTelemetry, telemetry)
}

}

export const __testables = {
  buildEmbeddingBatches,
  estimateTokenUpperBound,
  collectUniqueMisses,
}

"use client"

import { useState } from "react"
import { IconAlertCircle, IconLogout2 } from "@tabler/icons-react"

import { authClient } from "@/lib/auth-client"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"

type AlphaAccessDeniedProps = {
  message: string
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "message" in value) {
    return String((value as { message?: string }).message)
  }
  return "Could not sign out. Try again."
}

export function AlphaAccessDenied({ message }: AlphaAccessDeniedProps) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")

  const handleSignOut = async () => {
    setBusy(true)
    setError("")

    const { error: signOutError } = await authClient.signOut()
    if (signOutError) {
      setBusy(false)
      setError(getErrorMessage(signOutError))
      return
    }

    window.location.replace("/")
  }

  return (
    <Card className="w-full max-w-md">
      <CardHeader className="space-y-2">
        <CardTitle className="flex items-center gap-2">
          <IconAlertCircle className="size-5 text-amber-600" />
          Alpha access required
        </CardTitle>
        <CardDescription>{message}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        <Button type="button" variant="outline" onClick={handleSignOut} disabled={busy}>
          <IconLogout2 className="size-4" />
          {busy ? "Signing out..." : "Sign out"}
        </Button>
        {error ? <p className="text-xs text-destructive">{error}</p> : null}
      </CardContent>
    </Card>
  )
}

