import { eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'
import type { ArtifactStore, GitLabSource, IngestJob, VectorStore } from '@/lib/indexing/contracts'
import {
  DeltaSnapshotFallbackError,
  runDeltaIngest,
} from '@/lib/indexing/delta'
import {
  finalizeIndexRun,
  markIndexRunFailed,
} from '@/lib/indexing/finalize'
import { runSnapshotIngest } from '@/lib/indexing/snapshot'
import { createArtifactStore } from '@/lib/indexing/stores/artifact-store'
import { createPostgresVectorStore } from '@/lib/indexing/stores/vector-store.pg'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { IngestResult, IngestRunMetrics } from '@/lib/indexing/types'

type IngestProcessorDeps = {
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const defaultDeps = (): IngestProcessorDeps => ({
  source: createGitLabSource(),
  vectorStore: createPostgresVectorStore(),
  artifactStore: createArtifactStore(),
})

const getErrorDetails = (error: unknown): Record<string, unknown> | null => {
  if (!(error instanceof Error)) {
    return null
  }

  return asRecord((error as Error & { details?: unknown }).details)
}

const asNumber = (value: unknown) =>
  typeof value === 'number' && Number.isFinite(value) ? value : null

const statValue = (stats: Record<string, number> | null, key: string): number => {
  const value = asNumber(stats?.[key])
  return value === null ? 0 : value
}

const resolveIngestMetrics = (
  stats: Record<string, number> | null,
): IngestRunMetrics | null => {
  if (!stats) {
    return null
  }

  const filesProcessed = (() => {
    const explicit = statValue(stats, 'filesProcessed')
    if (explicit > 0) {
      return explicit
    }

    const filesScanned = statValue(stats, 'filesScanned')
    const filesFetched = statValue(stats, 'filesFetched')
    return Math.max(filesScanned, filesFetched)
  })()

  const embeddingCostUsd = asNumber(stats.embeddingCostUsd)

  return {
    durationMs: null,
    filesProcessed,
    failures: statValue(stats, 'embeddingFailures'),
    embeddingApiCalls: statValue(stats, 'embeddingApiCalls'),
    pendingJobs: null,
    processingJobs: null,
    embeddingPromptTokens: statValue(stats, 'embeddingPromptTokens'),
    embeddingTotalTokens: statValue(stats, 'embeddingTotalTokens'),
    embeddingCostUsd:
      embeddingCostUsd !== null && embeddingCostUsd >= 0 ? Number(embeddingCostUsd.toFixed(8)) : null,
  }
}

const toErrorPayload = (error: unknown) => {
  const details = getErrorDetails(error)
  if (error instanceof Error) {
    return {
      code: 'INGEST_FAILED',
      message: error.message.slice(0, 500),
      stack: error.stack?.slice(0, 1000) ?? null,
      details,
    }
  }

  return {
    code: 'INGEST_FAILED',
    message: 'Unexpected ingest failure.',
    stack: null,
    details,
  }
}

const cleanupStaleVectorsForRun = async (args: {
  runId: string
  branchStateId: string
  vectorStore: VectorStore
}) => {
  const stagedChanges = await db
    .select({
      path: indexRunFileChanges.path,
      changeType: indexRunFileChanges.changeType,
      fileId: indexRunFileChanges.fileId,
    })
    .from(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, args.runId))

  for (const change of stagedChanges) {
    await args.vectorStore.deleteStaleByPath({
      branchStateId: args.branchStateId,
      path: change.path,
      keepFileId: change.changeType === 'upsert' ? change.fileId : null,
    })
  }
}

export const processIngestJob = async (
  job: IngestJob,
  deps: IngestProcessorDeps = defaultDeps(),
): Promise<IngestResult> => {
  const [run] = await db
    .select({
      id: indexRuns.id,
      status: indexRuns.status,
      mode: indexRuns.mode,
      branchStateId: indexRuns.branchStateId,
      baseSha: indexRuns.baseSha,
      headSha: indexRuns.headSha,
      artifactsPrefix: indexRuns.artifactsPrefix,
      configHash: indexBranchStates.configHash,
      integrationId: indexBranchStates.integrationId,
    })
    .from(indexRuns)
    .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
    .where(eq(indexRuns.id, job.runId))
    .limit(1)

if (run.mode === 'delta') {
  try {
    const delta = await runDeltaIngest({
      run: runContext,
      source: deps.source,
      vectorStore: deps.vectorStore,
      artifactStore: deps.artifactStore,
    })
    ingestStats = delta.stats
  } catch (error) {
    if (!(error instanceof DeltaSnapshotFallbackError)) {
      throw error
    }

    const snapshot = await runSnapshotIngest({
      run: runContext,
      source: deps.source,
      vectorStore: deps.vectorStore,
      artifactStore: deps.artifactStore,
    })

    ingestStats = snapshot.stats
    modeFallback = 'snapshot'
    modeFallbackReason = error.reason
  }
} else {
  const snapshot = await runSnapshotIngest({
    run: runContext,
    source: deps.source,
    vectorStore: deps.vectorStore,
    artifactStore: deps.artifactStore,
  })

  ingestStats = snapshot.stats
}

const stats = {
  ...ingestStats,
  ingestMode: run.mode,
  modeFallback,
  modeFallbackReason,
}
indexingMetrics = resolveIngestMetrics(ingestStats)

await db
  .update(indexRuns)
  .set({
    stats,
    updatedAt: new Date(),
  })
  .where(eq(indexRuns.id, run.id))

} catch (error) {
  const errorPayload = toErrorPayload(error)
  await markIndexRunFailed(run.id, errorPayload)

  return {
    runId: run.id,
    status: 'failed',
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: null,
    gcStatus: 'not_applicable',
    errorCode: 'INGEST_FAILED',
    errorMessage: errorPayload.message,
    errorDetails: asRecord(errorPayload.details),
    indexingMetrics,
  }
}

const finalized = await finalizeIndexRun(run.id)
if (finalized.status === 'not_found' || finalized.status === 'invalid_state') {
  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus: 'not_applicable',
    errorCode: finalized.status === 'not_found' ? 'FINALIZE_NOT_FOUND' : 'FINALIZE_INVALID_STATE',
    errorMessage: null,
    errorDetails: null,
    indexingMetrics,
  }
}

let gcStatus: IngestResult['gcStatus'] = 'not_applicable'
let errorCode: string | null = null
let errorMessage: string | null = null

  if (finalized.status === 'ready') {
    gcStatus = 'succeeded'
    try {
      await cleanupStaleVectorsForRun({
        runId: run.id,
        branchStateId: run.branchStateId,
        vectorStore: deps.vectorStore,
      })
    } catch (error) {
      gcStatus = 'failed'
      errorCode = 'VECTOR_GC_FAILED'
      errorMessage = error instanceof Error ? error.message.slice(0, 500) : 'Vector cleanup failed.'
      await db
        .update(indexRuns)
        .set({
          error: {
            code: 'VECTOR_GC_FAILED',
            message: errorMessage,
          },
          updatedAt: new Date(),
        })
        .where(eq(indexRuns.id, run.id))
    }
  } else {
    gcStatus = 'skipped'
  }

  return {
    runId: run.id,
    status: finalized.status,
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus,
    errorCode,
    errorMessage,
    errorDetails: null,
    indexingMetrics,
  }
}

import { NextResponse } from "next/server"

import {
  normalizeReviewGateScope,
  resolveReviewGatePreferences,
} from "@/lib/review/preferences"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/preferences",
    event: "api.review.preferences.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const params = new URL(request.url).searchParams
      const scope = normalizeReviewGateScope({
        instanceUrl: params.get("instanceUrl"),
        projectId: params.get("projectId"),
      })

      const resolved = await resolveReviewGatePreferences({
        userId,
        scope,
      })

      logger.set({
        scopeSource: resolved.effectiveSettings.scopeSource,
        hasProjectScope: Boolean(scope),
        hasProjectOverride: Boolean(resolved.projectOverride),
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            global: resolved.globalSettings,
            projectOverride: resolved.projectOverride,
            effective: resolved.effectiveSettings,
          },
        }),
      }
    },
  })
}

export const toSafeJsonObject = (value: unknown): Record<string, unknown> => {
  try {
    if (value && typeof value === "object") {
      return JSON.parse(JSON.stringify(value)) as Record<string, unknown>
    }
  } catch {
    return { serializationError: true }
  }
  return {}
}

export const extractLogEventName = (input: unknown) => {
  if (!input || typeof input !== "object") {
    return "log.unknown"
  }

  const event = input as { event?: unknown; tag?: unknown; path?: unknown }

  if (typeof event.event === "string" && event.event.trim()) {
    return event.event.trim()
  }
  if (typeof event.tag === "string" && event.tag.trim()) {
    return `log.${event.tag.trim()}`
  }
  if (typeof event.path === "string" && event.path.trim()) {
    return `request.${event.path.trim()}`
  }
  return "log.unknown"
}

