export type AiClientSettings = {
  apiUrl: string
  model: string
  token: string
}

export const AI_CLIENT_SETTINGS_STORAGE_KEY = "argus-ai-settings"
const DEFAULT_AI_API_URL = "https://api.ai.lmco.com/v1"
const DEFAULT_AI_MODEL = "gpt-oss-120b"

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const getPreferredEnvValue = (...candidates: Array<string | undefined>) => {
  for (const candidate of candidates) {
    if (isNonEmptyString(candidate)) {
      return candidate.trim()
    }
  }
  return ""
}

export const getAiClientSettingsDefaults = (): AiClientSettings => ({
  apiUrl:
    getPreferredEnvValue(
      process.env.NEXT_PUBLIC_AI_API_URL,
      process.env.NEXT_PUBLIC_OPENAI_BASE_URL,
    ) || DEFAULT_AI_API_URL,
  model:
    getPreferredEnvValue(
      process.env.NEXT_PUBLIC_AI_MODEL,
      process.env.NEXT_PUBLIC_OPENAI_MODEL,
    ) || DEFAULT_AI_MODEL,
  token: getPreferredEnvValue(
    process.env.NEXT_PUBLIC_AI_API_TOKEN,
    process.env.NEXT_PUBLIC_OPENAI_API_KEY,
  ),
})

export const normalizeAiClientSettings = (
  value: unknown,
  fallback = getAiClientSettingsDefaults(),
): AiClientSettings => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return fallback
  }

  const record = value as Record<string, unknown>
  return {
    apiUrl: isNonEmptyString(record.apiUrl) ? record.apiUrl.trim() : fallback.apiUrl,
    model: isNonEmptyString(record.model) ? record.model.trim() : fallback.model,
    token: isNonEmptyString(record.token) ? record.token.trim() : "",
  }
}

export const readAiClientSettingsFromStorage = (): AiClientSettings => {
  const defaults = getAiClientSettingsDefaults()
  if (typeof window === "undefined") {
    return defaults
  }

  const raw = window.localStorage.getItem(AI_CLIENT_SETTINGS_STORAGE_KEY)
  if (!raw) {
    return defaults
  }

  try {
    const parsed = JSON.parse(raw) as unknown
    return normalizeAiClientSettings(parsed, defaults)
  } catch {
    return defaults
  }
}

import {
  createMergeRequestDiscussion as createMergeRequestDiscussionApi,
  getMergeRequestDetails,
} from "@/lib/gitlab/client"

export type GitLabDiscussionSide = "additions" | "deletions"

export class MergeRequestDiscussionError extends Error {
  code:
    | "comment_body_required"
    | "comment_side_invalid"
    | "comment_line_invalid"
    | "comment_path_required"
    | "missing_diff_refs"

  constructor(
    code: MergeRequestDiscussionError["code"],
    message: string,
  ) {
    super(message)
    this.code = code
  }
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const normalizeDiscussionPath = (value: string | null | undefined) =>
  String(value ?? "")
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const resolveMergeRequestDiffRefs = (value: unknown) => {
  const root = asRecord(value)
  const diffRefs = asRecord(root?.diff_refs)
  if (!diffRefs) {
    return null
  }

  const baseSha = String(diffRefs.base_sha ?? "").trim()
  const startSha = String(diffRefs.start_sha ?? "").trim()
  const headSha = String(diffRefs.head_sha ?? "").trim()

  if (!baseSha || !startSha || !headSha) {
    return null
  }

  return {
    baseSha,
    startSha,
    headSha,
  }
}

export const createMergeRequestDiscussion = async ({

  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
  commentBody,
  commentLine,
  commentSide,
  commentFilePath,
  commentOldPath,
  commentNewPath,
}: {
  instanceUrl: string
  token: string
  projectId: string
  mergeRequestIid: string
  commentBody: string
  commentLine: number
  commentSide: GitLabDiscussionSide
  commentFilePath?: string | null
  commentOldPath?: string | null
  commentNewPath?: string | null
}) => {
  const normalizedCommentBody = commentBody.trim()
  if (!normalizedCommentBody) {
    throw new MergeRequestDiscussionError(
      "comment_body_required",
      "commentBody is required.",
    )
  }

  if (!(commentSide === "additions" || commentSide === "deletions")) {
    throw new MergeRequestDiscussionError(
      "comment_side_invalid",
      "commentSide must be one of: additions or deletions.",
    )
  }

  const normalizedLine = Math.floor(commentLine)
  if (!Number.isFinite(normalizedLine) || normalizedLine < 1) {
    throw new MergeRequestDiscussionError(
      "comment_line_invalid",
      "commentLine must be a positive integer.",
    )
  }

  const normalizedFilePath = normalizeDiscussionPath(commentFilePath)
  const normalizedOldPath = normalizeDiscussionPath(commentOldPath)
  const normalizedNewPath = normalizeDiscussionPath(commentNewPath)

  let oldPath = normalizedOldPath || normalizedFilePath || normalizedNewPath
  let newPath = normalizedNewPath || normalizedFilePath || normalizedOldPath
  if (!oldPath && newPath) {
    oldPath = newPath
  }
  if (!newPath && oldPath) {
    newPath = oldPath
  }

if (commentSide === "additions" && !newPath) {
  throw new MergeRequestDiscussionError(
    "comment_path_required",
    "A new path is required for additions-side comments.",
  )
}
if (commentSide === "deletions" && !oldPath) {
  throw new MergeRequestDiscussionError(
    "comment_path_required",
    "An old path is required for deletions-side comments.",
  )
}

const mergeRequestDetails = await getMergeRequestDetails(
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
)
const diffRefs = resolveMergeRequestDiffRefs(mergeRequestDetails)
if (!diffRefs) {
  throw new MergeRequestDiscussionError(
    "missing_diff_refs",
    "Unable to post comment to merge request diff right now. Reload and retry.",
  )
}

const position = {
  position_type: "text",
  base_sha: diffRefs.baseSha,
  start_sha: diffRefs.startSha,
  head_sha: diffRefs.headSha,
  old_path: oldPath,
  new_path: newPath,
  ...(commentSide === "deletions"
    ? { old_line: normalizedLine }
    : { new_line: normalizedLine }),
}

const discussionPayload = await createMergeRequestDiscussionApi(
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
  {
    body: normalizedCommentBody,
    position,
  },
)

const notes = Array.isArray(discussionPayload.notes)
  ? discussionPayload.notes
  : []
const firstNote = asRecord(notes[0])
const noteIdValue = firstNote?.id
const noteId =
  typeof noteIdValue === "number" || typeof noteIdValue === "string"
    ? String(noteIdValue)
    : null

  const discussionId = String(discussionPayload.id ?? "").trim() || null

  return {
    discussionId,
    noteId,
    commentPath: commentSide === "deletions" ? oldPath : newPath,
    commentLine: normalizedLine,
    commentSide,
  }
}

