import { and, eq, inArray, isNull, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexFileStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'

type FinalizeStatus = 'ready' | 'superseded' | 'not_found' | 'invalid_state'

export type FinalizeIndexRunResult = {
  runId: string
  status: FinalizeStatus
}

const FINALIZABLE_STATUSES = new Set(['ingesting', 'indexing'])

export const markIndexRunFailed = async (
  runId: string,
  error: Record<string, unknown>,
): Promise<void> => {
  await db
    .update(indexRuns)
    .set({
      status: 'failed',
      error,
      updatedAt: new Date(),
    })
    .where(eq(indexRuns.id, runId))
}

export const finalizeIndexRun = async (runId: string): Promise<FinalizeIndexRunResult> => {
  return db.transaction(async (tx) => {
    const [run] = await tx
      .select({
        id: indexRuns.id,
        branchStateId: indexRuns.branchStateId,
        baseSha: indexRuns.baseSha,
        headSha: indexRuns.headSha,
        status: indexRuns.status,
      })
      .from(indexRuns)
      .where(eq(indexRuns.id, runId))
      .limit(1)

    if (!run) {
      return { runId, status: 'not_found' }
    }

    if (!FINALIZABLE_STATUSES.has(run.status)) {
      return { runId, status: 'invalid_state' }
    }

    const now = new Date()

    if (deletePaths.length > 0) {
      await tx
        .delete(indexFileStates)
        .where(
          and(
            eq(indexFileStates.branchStateId, run.branchStateId),
            inArray(indexFileStates.path, deletePaths),
          ),
        )
    }

    const upserts = stagedChanges.filter(
      (change) => change.changeType === 'upsert' && change.fileId && change.sizeBytes !== null,
    )

    if (upserts.length > 0) {
      await tx
        .insert(indexFileStates)
        .values(
          upserts.map((change) => ({
            branchStateId: run.branchStateId,
            path: change.path,
            fileId: change.fileId as string,
            sizeBytes: change.sizeBytes as number,
            skipReason: change.skipReason,
            lastReadySha: run.headSha,
            createdAt: now,
            updatedAt: now,
          })),
        )
        .onConflictDoUpdate({
          target: [indexFileStates.branchStateId, indexFileStates.path],
          set: {
            fileId: sql`excluded.file_id`,
            sizeBytes: sql`excluded.size_bytes`,
            skipReason: sql`excluded.skip_reason`,
            lastReadySha: run.headSha,
            updatedAt: now,
          },
        })
    }

    await tx
      .update(indexRuns)
      .set({
        status: 'ready',
        error: null,
        updatedAt: now,
      })
      .where(eq(indexRuns.id, run.id))

    return { runId: run.id, status: 'ready' }
  })
}

import { describe, expect, mock, test } from "bun:test"
import type { NextRequest } from "next/server"

const loadProxyModule = async (options?: { sessionToken?: string | null }) => {
  const getSessionCookie = mock(() => options?.sessionToken ?? null)

  mock.module("better-auth/cookies", () => ({
    getSessionCookie,
  }))

  const module = await import(`./proxy?cacheBust=${Math.random().toString(36).slice(2)}`)
  return {
    proxy: module.proxy as (request: NextRequest) => Response,
    getSessionCookie,
  }
}

const buildRequest = (path: string) => {
  const url = `http://localhost${path}`
  return {
    url,
    nextUrl: new URL(url),
  } as NextRequest
}

describe("proxy auth routing", () => {
  test("redirects unauthenticated protected routes to root with next", async () => {
    const { proxy } = await loadProxyModule()
    const response = proxy(buildRequest("/repos/abc"))

    expect(response.status).toBe(307)
    expect(response.headers.get("location")).toBe("http://localhost/?next=%2Frepos%2Fabc")
  })

  test("does not redirect unauthenticated onboarding routes", async () => {
    const { proxy } = await loadProxyModule()
    const response = proxy(buildRequest("/onboarding/tokens"))

    expect(response.status).toBe(200)
    expect(response.headers.get("location")).toBeNull()
  })
})

import type { GitLabIntegrationSummary } from "@/lib/gitlab/service"

type UserIntegrationsCacheEntry = {
  expiresAt: number
  value: Promise<GitLabIntegrationSummary[]>
}

const DEFAULT_CACHE_TTL_MS = 60_000
const DEFAULT_CACHE_MAX_ENTRIES = 256

const asPositiveInteger = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed < 1) {
    return fallback
  }

  return parsed
}

const USER_INTEGRATIONS_CACHE_TTL_MS = asPositiveInteger(
  process.env.ARGUS_INTEGRATIONS_CACHE_TTL_MS,
  DEFAULT_CACHE_TTL_MS,
)
const USER_INTEGRATIONS_CACHE_MAX_ENTRIES = asPositiveInteger(
  process.env.ARGUS_INTEGRATIONS_CACHE_MAX_ENTRIES,
  DEFAULT_CACHE_MAX_ENTRIES,
)

const userIntegrationsCache = new Map<string, UserIntegrationsCacheEntry>()

const trimUserIntegrationsCache = () => {
  const now = Date.now()
  for (const [key, entry] of userIntegrationsCache.entries()) {
    if (entry.expiresAt <= now) {
      userIntegrationsCache.delete(key)
    }
  }

  while (userIntegrationsCache.size > USER_INTEGRATIONS_CACHE_MAX_ENTRIES) {
    const oldestKey = userIntegrationsCache.keys().next().value
    if (!oldestKey) {
      break
    }
    userIntegrationsCache.delete(oldestKey)
  }
}

const defaultLoadUserIntegrations = async (userId: string) => {
  const { listUserIntegrations } = await import("@/lib/gitlab/service")
  return listUserIntegrations(userId)
}

export const getCachedUserIntegrations = (
  userId: string,
  options?: {
    load?: (userId: string) => Promise<GitLabIntegrationSummary[]>
  },
) => {
  const normalizedUserId = userId.trim()
  if (!normalizedUserId) {
    return Promise.resolve([] as GitLabIntegrationSummary[])
  }

  const now = Date.now()
  const cachedEntry = userIntegrationsCache.get(normalizedUserId)
  if (cachedEntry && cachedEntry.expiresAt > now) {
    return cachedEntry.value
  }
  if (cachedEntry) {
    userIntegrationsCache.delete(normalizedUserId)
  }

  const load = options?.load ?? defaultLoadUserIntegrations
  const value = load(normalizedUserId)
  userIntegrationsCache.set(normalizedUserId, {
    expiresAt: now + USER_INTEGRATIONS_CACHE_TTL_MS,
    value,
  })
  trimUserIntegrationsCache()

  value.catch(() => {
    const current = userIntegrationsCache.get(normalizedUserId)
    if (current?.value === value) {
      userIntegrationsCache.delete(normalizedUserId)
    }
  })

  return value
}

export const invalidateUserIntegrations = (userId?: string) => {
  if (typeof userId === "string") {
    const normalizedUserId = userId.trim()
    if (!normalizedUserId) {
      return 0
    }
    return userIntegrationsCache.delete(normalizedUserId) ? 1 : 0
  }

  const size = userIntegrationsCache.size
  userIntegrationsCache.clear()
  return size
}

export const getUserIntegrationsCacheConfig = () => ({
  ttlMs: USER_INTEGRATIONS_CACHE_TTL_MS,
  maxEntries: USER_INTEGRATIONS_CACHE_MAX_ENTRIES,
})

