const resyncSchema = z.object({
  token: z.string().optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/resync`,
    event: "api.gitlab.integrations.resync",
    context: { integrationId },
    handler: async ({ logger }) => {

      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, payload] = await Promise.all([
        getUserIntegration(integrationId, userId),
        request.json().catch(() => ({})),
      ])

      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const parsed = resyncSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid resync payload." }, { status: 400 }),
        }
      }

      try {
        const result = await resyncGitLabIntegration({
          integration,
          token: parsed.data.token,
        })
        logger.set({
          hasWarning: Boolean(result.warning),
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result.integration, warning: result.warning }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to resync integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

const ALLOWED_MERGE_REQUEST_ACTIONS = new Set([
  "open",
  "reopen",
  "update",
  "merge",
]);

type NormalizedWebhookEvent = {
  eventType: "push" | "merge_request" | "ignored";
  jobType?: "push" | "merge_request";
  ref: string | null;
  normalizedPayload?: Record<string, unknown>;
};

const asObject = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }
  return value as Record<string, unknown>;
};

const asString = (value: unknown) =>
  typeof value === "string" && value.trim().length > 0 ? value : null;

const asNumberString = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }
  if (typeof value === "string" && value.trim()) {
    return value.trim();
  }
  return null;
};

export const classifyWebhookEvent = (
  eventName: string,
  payload: Record<string, unknown>,
): NormalizedWebhookEvent => {

  const ref = asString(payload.ref);

  if (eventName === "Push Hook") {
    if (!ref || !ref.startsWith("refs/heads/")) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const after = asString(payload.after);
    if (!after) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    return {
      eventType: "push",
      jobType: "push",
      ref,
      normalizedPayload: {
        ref,
        before: asString(payload.before),
        after,
        checkoutSha: asString(payload.checkout_sha),
      },
    };
  }

  if (eventName === "Merge Request Hook") {
    const objectAttributes = asObject(payload.object_attributes);
    const action = asString(objectAttributes?.action);

    if (!action || !ALLOWED_MERGE_REQUEST_ACTIONS.has(action)) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const mergeRequestIid = asNumberString(objectAttributes?.iid);
    if (!mergeRequestIid) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const lastCommit = asObject(objectAttributes?.last_commit);

    return {
      eventType: "merge_request",
      jobType: "merge_request",
      ref,
      normalizedPayload: {
        mergeRequestIid,
        action,
        sourceBranch: asString(objectAttributes?.source_branch),
        targetBranch: asString(objectAttributes?.target_branch),
        state: asString(objectAttributes?.state),
        lastCommitSha: asString(lastCommit?.id),
      },
    };
  }

  return {
    eventType: "ignored",
    ref,
  };
};

import type { Dispatch, SetStateAction } from "react"
import { useCallback, useEffect, useRef, useState } from "react"

import {
  BACKGROUND_PARSE_FILE_BATCH_SIZE,
  getErrorMessage,
  getNow,
  getParsePatchFilesModule,
  getStableFileKey,
  INITIAL_PARSE_FILE_BATCH_SIZE,
  splitPatchIntoFileChunks,
  type DiffDataSource,
  type DiffLoadProfile,
  type DiffPayload,
  type ParsePatchResult,
  type ParsePatchWorkerResponse,
  type PendingParseRequest,
} from "../merge-request-diff-viewer.utils"

type UseMergeRequestDiffDataOptions = {
  instanceUrl: string
  token: string
  integrationId?: string
  projectId: string
  mergeRequestIid: string
  setCollapsedFileKeys: Dispatch<SetStateAction<Set<string>>>
  onResetReview: () => void
  onDiffLoaded: () => void | Promise<void>
  onResetVisibleFileCount: () => void
}

const toDiffDataSource = (value: unknown): DiffDataSource =>
  value === "changes" ? "changes" : "raw_diffs"

const readPatchTextFromStream = async (response: Response) => {
  if (!response.body) {
    return await response.text()
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  const chunks: string[] = []

  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) {
        break
      }
      if (!value || value.byteLength === 0) {
        continue
      }
      chunks.push(decoder.decode(value, { stream: true }))
    }

    const trailing = decoder.decode()
    if (trailing) {
      chunks.push(trailing)
    }
  } finally {
    reader.releaseLock()
  }

  return chunks.join("")
}

const resolvePatchFromDiffResponse = async (response: Response) => {
  const contentType = response.headers.get("content-type")?.toLowerCase() ?? ""
  if (contentType.includes("application/json")) {
    const payload = (await response.json().catch(() => null)) as DiffPayload | null
    if (!payload?.data || typeof payload.data.patch !== "string") {
      throw new Error("Unexpected diff response from server.")
    }
    return {
      patch: payload.data.patch,
      source: toDiffDataSource(payload.data.source),
    }
  }

  const patch = await readPatchTextFromStream(response)
  return {
    patch,
    source: toDiffDataSource(response.headers.get("x-diff-source")),
  }
}

export function useMergeRequestDiffData({
  instanceUrl,
  token,
  integrationId,
  projectId,
  mergeRequestIid,
  setCollapsedFileKeys,
  onResetReview,
  onDiffLoaded,
  onResetVisibleFileCount,
}: UseMergeRequestDiffDataOptions) {
  const [isLoading, setIsLoading] = useState(false)
  const [loadError, setLoadError] = useState("")
  const [patchText, setPatchText] = useState("")
  const [dataSource, setDataSource] = useState<DiffDataSource | null>(null)
  const [loadProfile, setLoadProfile] = useState<DiffLoadProfile>({
    fetchMs: null,
    firstParseMs: null,
    fullParseMs: null,
  })
  const [parsedFiles, setParsedFiles] = useState<ParsePatchResult["files"]>([])
  const [parseError, setParseError] = useState("")
  const [isParsingInitialPatch, setIsParsingInitialPatch] = useState(false)
  const [isParsingRemainingPatch, setIsParsingRemainingPatch] = useState(false)

const parseWorkerRef = useRef<Worker | null>(null)
const parseRequestIdRef = useRef(0)
const pendingParseRequestsRef = useRef<Map<number, PendingParseRequest>>(new Map())

useEffect(() => {
  let worker: Worker | null = null
  try {
    worker = new Worker(
      new URL("../../../workers/diff-parser.worker.ts", import.meta.url),
    )
  } catch {
    worker = null
  }

  parseWorkerRef.current = worker

  if (!worker) {
    return () => {
      parseWorkerRef.current = null
    }
  }

  const pendingParseRequests = pendingParseRequestsRef.current

  const handleMessage = (event: MessageEvent<ParsePatchWorkerResponse>) => {
    const { id, files, parseError: workerParseError } = event.data
    const pending = pendingParseRequests.get(id)
    if (!pending) {
      return
    }
    pendingParseRequests.delete(id)
    pending.resolve({
      files,
      parseError: workerParseError,
    })
  }

  const handleError = () => {
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
  }

  worker.addEventListener("message", handleMessage)
  worker.addEventListener("error", handleError)

  return () => {
    parseRequestIdRef.current += 1
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
    worker.removeEventListener("message", handleMessage)
    worker.removeEventListener("error", handleError)
    worker.terminate()
    if (parseWorkerRef.current === worker) {
      parseWorkerRef.current = null
    }
  }
}, [])

useEffect(() => {
  void getParsePatchFilesModule()
}, [])

const loadDiff = useCallback(async () => {

  const loadStart = getNow()
  setIsLoading(true)
  setLoadError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "text/plain, application/json",
      },
      body: JSON.stringify({
        action: "merge-request-diff",
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
        streamDiff: true,
      }),
    })

    if (!response.ok) {
      const payload = (await response.json().catch(() => null)) as DiffPayload | null
      throw new Error(getErrorMessage(payload))
    }

    const resolvedPatch = await resolvePatchFromDiffResponse(response)
    if (!resolvedPatch.patch.trim()) {
      throw new Error("Merge request has no diff content to render.")
    }

    setPatchText(resolvedPatch.patch)
    setDataSource(resolvedPatch.source)
    setCollapsedFileKeys(new Set())
    setLoadProfile({
      fetchMs: Math.round(getNow() - loadStart),
      firstParseMs: null,
      fullParseMs: null,
    })
    onResetVisibleFileCount()
    onResetReview()
    void onDiffLoaded()
  } catch (error) {
    setPatchText("")
    setDataSource(null)
    setLoadError(getErrorMessage(error))
    setLoadProfile({
      fetchMs: null,
      firstParseMs: null,
      fullParseMs: null,
    })
    onResetReview()
  } finally {
    setIsLoading(false)
  }
}, [

  instanceUrl,
  integrationId,
  mergeRequestIid,
  onResetReview,
  onDiffLoaded,
  onResetVisibleFileCount,
  projectId,
  setCollapsedFileKeys,
  token,
])

useEffect(() => {
  void loadDiff()
}, [loadDiff])

useEffect(() => {
  if (!patchText) {
    parseRequestIdRef.current += 1
    setParsedFiles([])
    setParseError("")
    setIsParsingInitialPatch(false)
    setIsParsingRemainingPatch(false)
    return
  }

  let cancelled = false

  const parsePatchText = async (
    nextPatchText: string,
    cacheKeyPrefix: string,
    preferMainThread = false,
  ): Promise<ParsePatchResult> => {

  if (preferMainThread) {
    const { parsePatchFiles } = await getParsePatchFilesModule()
    try {
      const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
      return {
        files: patches.flatMap((patch) => patch.files),
        parseError: "",
      }
    } catch (error) {
      return {
        files: [],
        parseError: getErrorMessage(error),
      }
    }
  }

  const worker = parseWorkerRef.current
  if (worker) {
    const requestId = parseRequestIdRef.current + 1
    parseRequestIdRef.current = requestId

    return await new Promise<ParsePatchResult>((resolve, reject) => {
      pendingParseRequestsRef.current.set(requestId, { resolve, reject })
      try {
        worker.postMessage({
          id: requestId,
          patchText: nextPatchText,
          cacheKeyPrefix,
        })
      } catch (error) {
        pendingParseRequestsRef.current.delete(requestId)
        reject(error)
      }
    })
  }

  const { parsePatchFiles } = await getParsePatchFilesModule()
  try {
    const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
    return {
      files: patches.flatMap((patch) => patch.files),
      parseError: "",
    }
  } catch (error) {
    return {
      files: [],
      parseError: getErrorMessage(error),
    }
  }
}

const parseIncrementally = async () => {
  const parseStart = getNow()

const cacheKeyPrefix = `mr-${projectId}-${mergeRequestIid}`
const patchChunks = splitPatchIntoFileChunks(patchText)
setParseError("")
setParsedFiles([])
setIsParsingInitialPatch(true)
setIsParsingRemainingPatch(false)

if (patchChunks.length === 0) {
  const result = await parsePatchText(patchText, cacheKeyPrefix)
  if (cancelled) {
    return
  }
  setParsedFiles(result.files)
  setParseError(result.parseError)
  setLoadProfile((current) => ({
    ...current,
    firstParseMs: Math.round(getNow() - parseStart),
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  setIsParsingInitialPatch(false)
  return
}

const initialPatchChunk = patchChunks
  .slice(0, INITIAL_PARSE_FILE_BATCH_SIZE)
  .join("\n\n")
const initialResult = await parsePatchText(
  initialPatchChunk,
  `${cacheKeyPrefix}-batch-0`,
  true,
)
if (cancelled) {
  return
}

if (initialResult.files.length === 0 && initialResult.parseError) {
  setParsedFiles([])
  setParseError(initialResult.parseError)
  setIsParsingInitialPatch(false)
  return
}

let nextFiles = initialResult.files
let nextParseError = initialResult.parseError
setParsedFiles(nextFiles)
setCollapsedFileKeys(
  new Set(
    nextFiles
      .slice(1)
      .map((file) => getStableFileKey(file)),
  ),
)
setParseError(nextParseError)

setLoadProfile((current) => ({
  ...current,
  firstParseMs: Math.round(getNow() - parseStart),
}))
setIsParsingInitialPatch(false)

const hasRemainingChunks = patchChunks.length > INITIAL_PARSE_FILE_BATCH_SIZE
if (!hasRemainingChunks) {
  setLoadProfile((current) => ({
    ...current,
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  return
}

setIsParsingRemainingPatch(true)

for (
  let start = INITIAL_PARSE_FILE_BATCH_SIZE;
  start < patchChunks.length;
  start += BACKGROUND_PARSE_FILE_BATCH_SIZE
) {
  const nextChunk = patchChunks
    .slice(start, start + BACKGROUND_PARSE_FILE_BATCH_SIZE)
