import { copyFile, mkdir, readdir } from 'node:fs/promises'
import path from 'node:path'

const DEFAULT_REPORTS_DIR = path.join(process.cwd(), '.benchmarks', 'indexing')
const DEFAULT_BASELINE_PATH = path.join(DEFAULT_REPORTS_DIR, 'phase2-baseline.json')

const getArgValue = (flag: string): string | null => {
  const args = process.argv.slice(2)
  const index = args.indexOf(flag)
  if (index < 0) {
    return null
  }

  const next = args[index + 1]
  if (!next || next.startsWith('--')) {
    return null
  }

  return next
}

const listReportFiles = async (reportsDir: string): Promise<string[]> => {
  const entries = await readdir(reportsDir, { withFileTypes: true })
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .filter((name) => /^phase2-.*\.json$/.test(name) && name !== 'phase2-baseline.json')
    .sort()
}

const resolveLatestReportPath = async (reportsDir: string): Promise<string> => {
  const reportFiles = await listReportFiles(reportsDir)
  const latest = reportFiles[reportFiles.length - 1]
  if (!latest) {
    throw new Error(`No benchmark reports found in ${reportsDir}. Run bench:indexing:phase2 first.`)
  }

  return path.join(reportsDir, latest)
}

const main = async () => {
  const reportsDir = process.env.INDEXING_BENCH_REPORTS_DIR?.trim() || DEFAULT_REPORTS_DIR
  const baselinePath = process.env.INDEXING_BENCH_BASELINE_PATH?.trim() || DEFAULT_BASELINE_PATH
  const explicitSource = getArgValue('--source')

  await mkdir(path.dirname(baselinePath), { recursive: true })

  const sourcePath = explicitSource
    ? path.resolve(explicitSource)
    : await resolveLatestReportPath(reportsDir)

  await copyFile(sourcePath, baselinePath)
  console.log(`Baseline updated: ${baselinePath}`)
  console.log(`Source report: ${sourcePath}`)
}

main().catch((error) => {
  console.error('[indexing-benchmark:set-baseline] failed', error)
  process.exit(1)
})

import path from 'node:path'

const SKIP_DIRS = new Set(['.git', 'node_modules', 'vendor', 'dist', 'build'])
const SKIP_FILES = new Set([
  'bun.lock',
  'package-lock.json',
  'pnpm-lock.yaml',
  'yarn.lock',
  'cargo.lock',
  'composer.lock',
  'go.sum',
])

const BINARY_EXTENSIONS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.ico',
  '.pdf',
  '.zip',
  '.gz',
  '.tar',
  '.tgz',
  '.7z',
  '.exe',
  '.dll',
  '.so',
  '.dylib',
  '.woff',
  '.woff2',
  '.ttf',
  '.otf',
  '.mp3',
  '.mp4',
  '.mov',
  '.avi',
])

export const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024

export const shouldSkipPath = (relativePath: string): boolean => {
  const normalized = relativePath.replace(/\\/g, '/').toLowerCase()
  const segments = normalized.split('/').filter(Boolean)
  if (segments.some((segment) => SKIP_DIRS.has(segment))) {
    return true
  }

  const fileName = segments.at(-1)
  if (!fileName) {
    return false
  }

  return SKIP_FILES.has(fileName)
}

export const isLikelyBinary = (relativePath: string, content: Buffer): boolean => {
  const ext = path.extname(relativePath).toLowerCase()
  if (BINARY_EXTENSIONS.has(ext)) {
    return true
  }

  const checkLength = Math.min(content.length, 8_192)
  for (let i = 0; i < checkLength; i += 1) {
    if (content[i] === 0) {
      return true
    }
  }

  return false
}

export const classifySkipReason = (args: {
  relativePath: string
  content: Buffer
  maxFileSizeBytes: number
}): 'path_excluded' | 'binary' | 'file_too_large' | null => {
  if (shouldSkipPath(args.relativePath)) {
    return 'path_excluded'
  }

  if (args.content.length > args.maxFileSizeBytes) {
    return 'file_too_large'
  }

  if (isLikelyBinary(args.relativePath, args.content)) {
    return 'binary'
  }

  return null
}

