type UseOnboardingDataOptions = {
  isHydrated: boolean
  projectsCacheKey: string
  canLoadProjects: boolean
  actionBusy: boolean
  tokenTestBusy: boolean
  tokenTestFeedback: TokenTestFeedback | null
  projectSearchQuery: string
  gitlabInstance: string
  customInstance: string
  token: string
  projects: Project[]
  queryClient: QueryClient
  routePrefetchProjects: () => void
  routePrefetchMrs: () => void
  routePushProjects: () => void
  routePushMrs: () => void
  setActionBusy: Dispatch<SetStateAction<boolean>>
  setProjectsError: Dispatch<SetStateAction<string>>
  setMergeRequestsError: Dispatch<SetStateAction<string>>
  setTokenTestFeedback: Dispatch<SetStateAction<TokenTestFeedback | null>>
  setProjects: Dispatch<SetStateAction<Project[]>>
  setSelectedProjectId: Dispatch<SetStateAction<string>>
  setMergeRequests: Dispatch<SetStateAction<MergeRequest[]>>
  setSelectedMergeRequestId: Dispatch<SetStateAction<string>>
  trackEvent: (
    event: OnboardingTrackedEvent,
    metadata?: OnboardingEventMetadata,
  ) => void
}

const PROJECT_SEARCH_DEBOUNCE_MS = 300
const BOOTSTRAP_PREFETCH_FAILURE_COOLDOWN_MS = 60_000

const shouldPrefetchOnboardingQuery = ({
  queryClient,
  queryKey,
  staleTime,
}: {
  queryClient: QueryClient
  queryKey: readonly unknown[]
  staleTime: number
}) => {
  const state = queryClient.getQueryState(queryKey)
  if (!state) {
    return true
  }

  if (state.fetchStatus === "fetching") {
    return false
  }

  if (!state.dataUpdatedAt) {
    return true
  }

  return Date.now() - state.dataUpdatedAt >= staleTime
}

export function useOnboardingData({
  isHydrated,
  projectsCacheKey,
  canLoadProjects,
  actionBusy,
  tokenTestBusy,
  tokenTestFeedback,
  projectSearchQuery,
  gitlabInstance,
  customInstance,
  token,
  projects,
  queryClient,
  routePrefetchProjects,
  routePrefetchMrs,
  routePushProjects,
  routePushMrs,
  setActionBusy,
  setProjectsError,
  setMergeRequestsError,
  setTokenTestFeedback,
  setProjects,
  setSelectedProjectId,
  setMergeRequests,
  setSelectedMergeRequestId,
  trackEvent,
}: UseOnboardingDataOptions) {
  const previousProjectsCacheKeyRef = useRef<string | null>(null)
  const stableProjectsRef = useRef<Project[]>([])
  const projectSearchRunRef = useRef(0)
  const projectSearchDebounceRef = useRef<number | null>(null)
  const projectsRoutePrefetchedRef = useRef(false)
  const mrsRoutePrefetchedRef = useRef(false)
  const bootstrapPrefetchFailureAtRef = useRef({
    projects: 0,
    recentMergeRequests: 0,
  })

  const isBootstrapPrefetchCoolingDown = useCallback(
    (kind: "projects" | "recentMergeRequests") =>
      Date.now() - bootstrapPrefetchFailureAtRef.current[kind] <
      BOOTSTRAP_PREFETCH_FAILURE_COOLDOWN_MS,
    [],
  )

const callGitLab = useCallback(
  async (
    action: "projects" | "merge-requests" | "recent-merge-requests",
    options?: { projectId?: string; perPage?: number; search?: string },
  ) => {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    const normalizedToken = token.trim()
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action,
        instanceUrl: normalizedInstance,
        ...(normalizedToken ? { token: normalizedToken } : {}),
        ...(options?.projectId ? { projectId: options.projectId } : {}),
        ...(typeof options?.perPage === "number" ? { perPage: options.perPage } : {}),
        ...(options?.search ? { search: options.search } : {}),
      }),
    })

    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    if (!Array.isArray(payload?.data)) {
      throw new Error("Unexpected response from server.")
    }

    return payload.data
  },
  [customInstance, gitlabInstance, token],
)

const validateToken = useCallback(async () => {
  const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
  const normalizedToken = token.trim()
  if (!normalizedToken) {
    throw new Error("Personal access token is required.")
  }

  const response = await fetch("/api/gitlab", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      action: "validate-token",
      instanceUrl: normalizedInstance,
      token: normalizedToken,
    }),
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }
}, [customInstance, gitlabInstance, token])

const projectsQueryKey = useCallback(
  (perPage: number, search: string) =>
    QueryKeyFactory.onboarding.projects(projectsCacheKey, perPage, search),
  [projectsCacheKey],
)

const recentMergeRequestsQueryKey = useCallback(
  () => QueryKeyFactory.onboarding.recentMergeRequests(
    projectsCacheKey,
    MERGE_REQUESTS_FULL_LIMIT,
  ),
  [projectsCacheKey],
)

const mergeRequestsQueryKey = useCallback(
  (projectId: string, perPage: number) =>
    QueryKeyFactory.onboarding.mergeRequests(projectsCacheKey, projectId, perPage),
  [projectsCacheKey],
)

const applyLoadedProjects = useCallback(
  (data: Project[]) => {
    stableProjectsRef.current = data
    setProjects(data)
    setSelectedProjectId("")
    setMergeRequests([])
    setSelectedMergeRequestId("")
  },
  [setMergeRequests, setProjects, setSelectedMergeRequestId, setSelectedProjectId],
)

const fetchMergeRequests = useCallback(
  async (
    projectId: string,
    { perPage = MERGE_REQUESTS_FULL_LIMIT }: { perPage?: number } = {},
  ) => {
    const normalizedPerPage = Math.min(
      MERGE_REQUESTS_FULL_LIMIT,
      Math.max(1, Math.floor(perPage)),
    )
    if (!projectsCacheKey) {
      throw new Error("Personal access token is required.")
    }

    const queryKey = mergeRequestsQueryKey(projectId, normalizedPerPage)
    const cached = queryClient.getQueryData<MergeRequest[]>(queryKey)
    if (cached !== undefined) {
      return cached
    }

    return queryClient.fetchQuery({
      queryKey,
      queryFn: () =>
        callGitLab("merge-requests", {
          projectId,
          perPage: normalizedPerPage,
        }) as Promise<MergeRequest[]>,
      staleTime: ONBOARDING_QUERY_STALE_TIME,
      gcTime: ONBOARDING_QUERY_GC_TIME,
    })
  },
  [callGitLab, mergeRequestsQueryKey, projectsCacheKey, queryClient],
)

const fetchProjects = useCallback(
  async ({
    force = false,
    perPage = RECENT_PROJECTS_LIMIT,
    search = "",
  }: {
    force?: boolean
    perPage?: number
    search?: string
  } = {}) => {
    if (!projectsCacheKey) {
      throw new Error("Personal access token is required.")
    }

    const normalizedSearch = search.trim().toLowerCase()
    const queryKey = projectsQueryKey(perPage, normalizedSearch)
    if (force) {
      await queryClient.invalidateQueries({ queryKey, exact: true })
    }

    return queryClient.fetchQuery({
      queryKey,
      queryFn: () =>
        callGitLab("projects", {
          perPage,
          search: normalizedSearch,
        }) as Promise<Project[]>,
      staleTime: ONBOARDING_QUERY_STALE_TIME,
      gcTime: ONBOARDING_QUERY_GC_TIME,
    })
  },
  [callGitLab, projectsCacheKey, projectsQueryKey, queryClient],
)

const prefetchBootstrapData = useCallback(() => {
  if (!projectsCacheKey) {
    return
  }

  const projectsKey = projectsQueryKey(RECENT_PROJECTS_LIMIT, "")

if (
  shouldPrefetchOnboardingQuery({
    queryClient,
    queryKey: projectsKey,
    staleTime: ONBOARDING_QUERY_STALE_TIME,
  }) &&
  !isBootstrapPrefetchCoolingDown("projects")
) {
  void queryClient
    .prefetchQuery({
      queryKey: projectsKey,
      queryFn: () =>
        callGitLab("projects", {
          perPage: RECENT_PROJECTS_LIMIT,
        }) as Promise<Project[]>,
      staleTime: ONBOARDING_QUERY_STALE_TIME,
      gcTime: ONBOARDING_QUERY_GC_TIME,
      retry: false,
    })
    .then(() => {
      bootstrapPrefetchFailureAtRef.current.projects = 0
    })
    .catch(() => {
      bootstrapPrefetchFailureAtRef.current.projects = Date.now()
    })
}

const recentMergeRequestsKey = recentMergeRequestsQueryKey()

  if (
    shouldPrefetchOnboardingQuery({
      queryClient,
      queryKey: recentMergeRequestsKey,
      staleTime: ONBOARDING_QUERY_STALE_TIME,
    }) &&
    !isBootstrapPrefetchCoolingDown("recentMergeRequests")
  ) {
    void queryClient
      .prefetchQuery({
        queryKey: recentMergeRequestsKey,
        queryFn: () =>
          callGitLab("recent-merge-requests", {
            perPage: MERGE_REQUESTS_FULL_LIMIT,
          }) as Promise<MergeRequest[]>,
        staleTime: ONBOARDING_QUERY_STALE_TIME,
        gcTime: ONBOARDING_QUERY_GC_TIME,
        retry: false,
      })
      .then(() => {
        bootstrapPrefetchFailureAtRef.current.recentMergeRequests = 0
      })
      .catch(() => {
        bootstrapPrefetchFailureAtRef.current.recentMergeRequests = Date.now()
      })
  }
}, [
  callGitLab,
  isBootstrapPrefetchCoolingDown,
  projectsCacheKey,
  projectsQueryKey,
  queryClient,
  recentMergeRequestsQueryKey,
])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  if (previousProjectsCacheKeyRef.current === null) {
    previousProjectsCacheKeyRef.current = projectsCacheKey
    return
  }

  if (previousProjectsCacheKeyRef.current === projectsCacheKey) {
    return
  }

  previousProjectsCacheKeyRef.current = projectsCacheKey
  stableProjectsRef.current = []
  projectsRoutePrefetchedRef.current = false
  mrsRoutePrefetchedRef.current = false
  bootstrapPrefetchFailureAtRef.current = {
    projects: 0,
    recentMergeRequests: 0,
  }
  void queryClient.removeQueries({ queryKey: ONBOARDING_QUERY_KEY_PREFIX })
}, [isHydrated, projectsCacheKey, queryClient])

const prefetchProjectsRouteOnce = useCallback(() => {
  if (projectsRoutePrefetchedRef.current) {
    return
  }
  projectsRoutePrefetchedRef.current = true
  routePrefetchProjects()
}, [routePrefetchProjects])

const prefetchMrsRouteOnce = useCallback(() => {
  if (mrsRoutePrefetchedRef.current) {
    return
  }
  mrsRoutePrefetchedRef.current = true
  routePrefetchMrs()
}, [routePrefetchMrs])

useEffect(() => {
  if (!isHydrated || tokenTestFeedback?.kind !== "success" || !canLoadProjects) {
    return
  }

  prefetchBootstrapData()
}, [canLoadProjects, isHydrated, prefetchBootstrapData, tokenTestFeedback])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  const normalizedQuery = projectSearchQuery.trim()

  if (normalizedQuery.length < SERVER_PROJECT_SEARCH_MIN_CHARS) {
    projectSearchRunRef.current += 1
    if (projectSearchDebounceRef.current !== null) {
      window.clearTimeout(projectSearchDebounceRef.current)
      projectSearchDebounceRef.current = null
    }
    if (stableProjectsRef.current.length > 0) {
      setProjects(stableProjectsRef.current)
    }
    return
  }

  const runId = ++projectSearchRunRef.current
  if (projectSearchDebounceRef.current !== null) {
    window.clearTimeout(projectSearchDebounceRef.current)
    projectSearchDebounceRef.current = null
  }

  projectSearchDebounceRef.current = window.setTimeout(() => {
    void fetchProjects({
      perPage: SERVER_PROJECT_SEARCH_LIMIT,
      search: normalizedQuery,
    })
      .then((results) => {
        if (runId !== projectSearchRunRef.current) {
          return
        }
        setProjects(results)
        setProjectsError("")
      })
      .catch((error) => {
        if (runId !== projectSearchRunRef.current) {
          return
        }
        setProjectsError(getErrorMessage(error))
      })
  }, PROJECT_SEARCH_DEBOUNCE_MS)

  return () => {
    if (projectSearchDebounceRef.current !== null) {
      window.clearTimeout(projectSearchDebounceRef.current)
      projectSearchDebounceRef.current = null
    }
  }
}, [fetchProjects, isHydrated, projectSearchQuery, setProjects, setProjectsError])

const preloadProjectsForContinue = useCallback(() => {
  if (!canLoadProjects || actionBusy || tokenTestBusy) {
    return
  }

  prefetchProjectsRouteOnce()
  prefetchMrsRouteOnce()
  prefetchBootstrapData()
}, [
  actionBusy,
  canLoadProjects,
  prefetchMrsRouteOnce,
  prefetchBootstrapData,
  prefetchProjectsRouteOnce,
  tokenTestBusy,
])

const loadProjects = useCallback(
  async ({
    force = false,
    setBusy = true,
  }: {
    force?: boolean
    setBusy?: boolean
  } = {}) => {
    if (setBusy) {
      setActionBusy(true)
      setTokenTestFeedback(null)
    }
    setProjectsError("")
    setMergeRequestsError("")

    try {
      const data = await fetchProjects({
        force,
        perPage: RECENT_PROJECTS_LIMIT,
      })
      applyLoadedProjects(data)

      const instanceUrl = resolveGitLabInstance(gitlabInstance, customInstance)
      trackEvent("onboarding_token_validated", { instanceUrl })
      trackEvent("onboarding_projects_ready", {
        instanceUrl,
        selectedProjectCount: data.length,
      })
      prefetchMrsRouteOnce()
      prefetchBootstrapData()
      return true
    } catch (error) {
      setProjectsError(getErrorMessage(error))
      return false
    } finally {
      if (setBusy) {
        setActionBusy(false)
      }
    }
  },
  [
    applyLoadedProjects,
    customInstance,
    fetchProjects,
    gitlabInstance,
    prefetchMrsRouteOnce,
    prefetchBootstrapData,
    setActionBusy,
    setMergeRequestsError,
    setProjectsError,
    setTokenTestFeedback,
    trackEvent,
  ],
)

const loadMergeRequests = useCallback(
  async (projectId: string, options?: LoadMergeRequestsOptions) => {
    const shouldSetBusy = options?.setBusy ?? true
    if (shouldSetBusy) {
      setActionBusy(true)
    }
    setMergeRequestsError("")

    try {
      prefetchMrsRouteOnce()
      const data = await fetchMergeRequests(projectId, {
        perPage: MERGE_REQUESTS_FULL_LIMIT,
      })
      setMergeRequests(data)
      setSelectedMergeRequestId((current) => {
        if (options?.preserveSelection && data.some((mr) => mr.id === current)) {
          return current
        }
        return ""
      })

      const instanceUrl = resolveGitLabInstance(gitlabInstance, customInstance)
      trackEvent("onboarding_mrs_ready", {
        instanceUrl,
        projectId,
        mergeRequestCount: data.length,
      })

      if (!options?.skipTracking) {
        trackEvent("onboarding_projects_selected", {
          selectedProjectCount: projects.length,
          projectId,
        })
      }
      if (!options?.skipNavigation) {
        routePushMrs()
      }
    } catch (error) {
      setMergeRequestsError(getErrorMessage(error))
    } finally {
      if (shouldSetBusy) {
        setActionBusy(false)
      }
    }
  },
  [
    customInstance,
    fetchMergeRequests,
    gitlabInstance,
    prefetchMrsRouteOnce,
    projects.length,
    routePushMrs,
    setActionBusy,
    setMergeRequests,
    setMergeRequestsError,
    setSelectedMergeRequestId,
    trackEvent,
  ],
)

  const handleTokenSubmit = useCallback(
    async (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()

      if (tokenTestFeedback?.kind === "success") {
        const instanceUrl = resolveGitLabInstance(gitlabInstance, customInstance)
        trackEvent("onboarding_token_validated", { instanceUrl })
        const cachedProjects = queryClient.getQueryData<Project[]>(
          projectsQueryKey(RECENT_PROJECTS_LIMIT, ""),
        )
        if (cachedProjects) {
          applyLoadedProjects(cachedProjects)
          trackEvent("onboarding_projects_ready", {
            instanceUrl,
            selectedProjectCount: cachedProjects.length,
          })
          routePushProjects()
          preloadProjectsForContinue()
          return
        }

        prefetchProjectsRouteOnce()
        routePushProjects()
        preloadProjectsForContinue()
        void loadProjects({ setBusy: false }).catch(() => null)
        return
      }

      const success = await loadProjects()
      if (success) {
        routePushProjects()
      }
    },
    [
      applyLoadedProjects,
      customInstance,
      gitlabInstance,
      loadProjects,
      prefetchProjectsRouteOnce,
      preloadProjectsForContinue,
      projectsQueryKey,
      queryClient,
      routePushProjects,
      tokenTestFeedback,
      trackEvent,
    ],
  )

  return {
    callGitLab,
    validateToken,
    mergeRequestsQueryKey,
    fetchProjects,
    applyLoadedProjects,
    preloadProjectsForContinue,
    loadProjects,
    loadMergeRequests,
    handleTokenSubmit,
  }
}

  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobile] = React.useState(false)

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)
  const open = openProp ?? _open
  const openRef = React.useRef(open)
  React.useEffect(() => {
    openRef.current = open
  }, [open])

  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState =
        typeof value === "function" ? value(openRef.current) : value
      if (setOpenProp) {
        setOpenProp(openState)
      } else {
        _setOpen(openState)
      }
    },
    [setOpenProp]
  )

  React.useEffect(() => {
    // Keep persisted sidebar state in sync with the effective open value.
    document.cookie = `${SIDEBAR_COOKIE_NAME}=${open}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
  }, [open])

  // Helper to toggle the sidebar.
  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open)
  }, [isMobile, setOpen, setOpenMobile])

  // Adds a keyboard shortcut to toggle the sidebar.

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault()
        toggleSidebar()
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [toggleSidebar])

  // We add a state so that we can do data-state="expanded" or "collapsed".
  // This makes it easier to style the sidebar with Tailwind classes.
  const state = open ? "expanded" : "collapsed"

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <TooltipProvider delayDuration={0}>
        <div
          data-slot="sidebar-wrapper"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH,
              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
              ...style,
            } as React.CSSProperties
          }
          className={cn(
            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </TooltipProvider>
    </SidebarContext.Provider>
  )
}

function Sidebar({

  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right"
  variant?: "sidebar" | "floating" | "inset"
  collapsible?: "offcanvas" | "icon" | "none"
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
          className
        )}
        {...props}
      >
        {children}
      </div>
    )
  }

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
        <SheetContent
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as React.CSSProperties
          }
          side={side}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
          </SheetHeader>
          <div className="flex h-full w-full flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    )
  }

return (
  <div
    className="group peer text-sidebar-foreground hidden md:block"
    data-state={state}
    data-collapsible={state === "collapsed" ? collapsible : ""}
    data-variant={variant}
    data-side={side}
    data-slot="sidebar"
  >
    {/* This is what handles the sidebar gap on desktop */}
    <div
      data-slot="sidebar-gap"
      className={cn(
        "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
        "group-data-[collapsible=offcanvas]:w-0",
        "group-data-[side=right]:rotate-180",
        variant === "floating" || variant === "inset"
          ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
          : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
      )}
    />

  )
}

function SidebarTrigger({
  className,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon"
      className={cn("size-7", className)}
