export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/disconnect`,
    event: "api.gitlab.integrations.disconnect",
    context: { integrationId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const integration = await getUserIntegration(integrationId, userId)
      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const result = await disconnectGitLabIntegration({
        integration,
        userId,
      })
      invalidateUserIntegrations(userId)
      logger.set({
        scope: result.scope,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            scope: result.scope,
          },
          warning: result.warning,
        }),
      }
    },
  })
}

