/** Build a linear edge chain from an ordered list of node ids. */
const buildChainEdges = (orderedIds: string[]): Edge[] => {
  const result: Edge[] = []
  for (let i = 0; i < orderedIds.length - 1; i += 1) {
    const source = orderedIds[i]
    const target = orderedIds[i + 1]
    if (!source || !target) continue
    result.push({
      id: `edge-${source}-${target}`,
      source,
      target,
      style: edgeBaseStyle,
      type: "smoothstep",
    })
  }
  return result
}

/** Sort nodes into the visual left→right chain order. */
const getChainOrder = (allNodes: Node[]): string[] => {
  const sorted = [...allNodes].sort((a, b) => a.position.x - b.position.x)
  return sorted.map((n) => n.id)
}

