    /* Space tools evenly between trigger and output */
    const triggerX = current.find((n) => n.id === "trigger")?.position.x ?? 40
    const outputX = outputNode?.position.x ?? 920
    const gap = (outputX - triggerX) / (toolCount + 2)
    const newX = triggerX + gap * (toolCount + 1)
    const newY = 200 + (toolCount % 2) * 80

    /* Shift the output node right to make room */
    const shiftedOutput = outputNode
      ? { ...outputNode, position: { x: Math.max(outputX, newX + 280), y: outputNode.position.y } }
      : null

    const nextNode: Node = {
      id: nextId,
      type: "workflowTool",
      position: { x: newX, y: newY },
      data: {
        label: tool.name,
        description: tool.description,
        category: tool.category,
      },
    }

    const updated = current.map((n) => (n.id === "output" && shiftedOutput ? shiftedOutput : n))
    return [...updated, nextNode]
  })

  /* Rebuild edges after nodes update */
  setNodes((current) => {
    const chain = getChainOrder(current)
    setEdges(buildChainEdges(chain))
    return current
  })
},

  [setNodes, setEdges],
)

