/// <reference lib="webworker" />

import { parsePatchFiles, type FileDiffMetadata } from "@pierre/diffs"

type ParsePatchWorkerRequest = {
  id: number
  patchText: string
  cacheKeyPrefix: string
}

type ParsePatchWorkerResponse = {
  id: number
  files: FileDiffMetadata[]
  parseError: string
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "message" in value) {
    return String((value as { message?: string }).message)
  }
  return "Unable to parse merge request diff."
}

self.addEventListener("message", (event: MessageEvent<ParsePatchWorkerRequest>) => {
  const { id, patchText, cacheKeyPrefix } = event.data

  if (!patchText) {
    const response: ParsePatchWorkerResponse = {
      id,
      files: [],
      parseError: "",
    }
    self.postMessage(response)
    return
  }

  try {
    const patches = parsePatchFiles(patchText, cacheKeyPrefix)
    const files = patches.flatMap((patch) => patch.files)

    const response: ParsePatchWorkerResponse = {
      id,
      files,
      parseError: "",
    }
    self.postMessage(response)
  } catch (error) {
    const response: ParsePatchWorkerResponse = {
      id,
      files: [],
      parseError: getErrorMessage(error),
    }
    self.postMessage(response)
  }
})

export {}

import { describe, expect, test } from "bun:test"

import { errorMessage, toError } from "@argus/shared-core"

describe("shared core error utils", () => {
  test("toError preserves errors and normalizes unknown input", () => {
    const original = new Error("boom")
    expect(toError(original)).toBe(original)
    expect(toError("failed").message).toBe("failed")
    expect(toError({} as unknown, "fallback").message).toBe("fallback")
  })

  test("errorMessage resolves strings and falls back when needed", () => {
    expect(errorMessage(new Error("read failed"))).toBe("read failed")
    expect(errorMessage("bad request")).toBe("bad request")
    expect(errorMessage(null, "fallback")).toBe("fallback")
  })
})

