import { describe, expect, mock, test } from "bun:test"

const loadServiceModule = async (dbMock: {
  select: () => {
    from: () => {
      where: () => {
        orderBy: () => {
          limit: () => Promise<Array<{ createdAt: Date }>>
        }
      }
    }
  }
  insert: () => {
    values: (value: unknown) => Promise<unknown>
  }
}) => {
  mock.module("@/lib/db", () => ({ db: dbMock }))
  return import(`@/lib/onboarding/service.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
}

const createDbMock = (limitResponses: Array<Array<{ createdAt: Date }>>) => {
  const insertValues: unknown[] = []
  const queued = [...limitResponses]

  const dbMock = {
    select: () => ({
      from: () => ({
        where: () => ({
          orderBy: () => ({
            limit: () => Promise.resolve(queued.shift() ?? []),
          }),
        }),
      }),
    }),
    insert: () => ({
      values: (value: unknown) => {
        insertValues.push(value)
        return Promise.resolve([])
      },
    }),
  }

  return { dbMock, insertValues }
}

describe("onboarding service", () => {

test("records onboarding completion once and computes duration", async () => {
  const startedAt = new Date(Date.now() - 12_000)
  const { dbMock, insertValues } = createDbMock([[], [{ createdAt: startedAt }]])
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: {
      completionSource: "first_ai_review",
      findingsCount: 3,
    },
  })

  expect(result.alreadyCompleted).toBe(false)
  expect(result.onboardingDurationMs).toBeTypeOf("number")
  expect((result.onboardingDurationMs ?? 0) >= 10_000).toBe(true)
  expect(insertValues).toHaveLength(1)
  expect(insertValues[0]).toMatchObject({
    userId: "user-1",
    event: "onboarding_completed",
    metadata: expect.objectContaining({
      completionSource: "first_ai_review",
      findingsCount: 3,
    }),
  })
})

test("skips insert when onboarding is already completed", async () => {
  const completedAt = new Date(Date.now() - 5_000)
  const { dbMock, insertValues } = createDbMock([[{ createdAt: completedAt }]])
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: { completionSource: "manual" },
  })

  expect(result.alreadyCompleted).toBe(true)
  expect(result.onboardingCompletedAt).toBe(completedAt)
  expect(insertValues).toHaveLength(0)
})

  test("reports completion state", async () => {
    const completedAt = new Date()
    const completedMock = createDbMock([[{ createdAt: completedAt }]])
    const incompleteMock = createDbMock([[]])

    const completedMod = await loadServiceModule(completedMock.dbMock)
    expect(await completedMod.isOnboardingCompleted("user-1")).toBe(true)

    const incompleteMod = await loadServiceModule(incompleteMock.dbMock)
    expect(await incompleteMod.isOnboardingCompleted("user-1")).toBe(false)
  })
})

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-full border border-transparent px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&>svg]:size-3 gap-1 [&>svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
        destructive:
          "bg-destructive text-white [a&]:hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        ghost: "[a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        link: "text-primary underline-offset-4 [a&]:hover:underline",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Badge({
  className,
  variant = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "span"

  return (
    <Comp
      data-slot="badge"
