import { describe, expect, test } from "bun:test"

import {
  DEFAULT_INDEXER_RUNTIME_MODULE,
  loadWorkerRunner,
  runIndexerService,
  runIndexerServiceCli,
} from "./index"

describe("shared indexer runtime", () => {
  test("DEFAULT_INDEXER_RUNTIME_MODULE points to web runtime contract", () => {
    expect(DEFAULT_INDEXER_RUNTIME_MODULE).toBe("@argus/service-web/indexer-runtime")
  })

  test("loadWorkerRunner resolves runIndexerWorker from module import", async () => {
    const runner = await loadWorkerRunner({
      moduleId: "mock-runtime",
      importModule: async () => ({
        runIndexerWorker: async () => {
          // no-op
        },
      }),
    })
    expect(typeof runner).toBe("function")
  })

  test("loadWorkerRunner rejects when worker export is missing", async () => {
    await expect(
      loadWorkerRunner({
        moduleId: "mock-runtime",
        importModule: async () => ({}),
      }),
    ).rejects.toThrow("worker module did not export runIndexerWorker")
  })

  test("runIndexerService executes loaded worker", async () => {
    let loaded = 0
    let ran = 0

    await runIndexerService({
      loadRunner: async () => {
        loaded += 1
        return async () => {
          ran += 1
        }
      },
    })

    expect(loaded).toBe(1)
    expect(ran).toBe(1)
  })

  test("runIndexerServiceCli logs and exits on failure", async () => {
    const logs: unknown[][] = []
    const exits: number[] = []

    await runIndexerServiceCli({
      runService: async () => {
        throw new Error("boom")
      },
      logError: (...args) => {
        logs.push(args)
      },
      exit: (code) => {
        exits.push(code)
      },
    })

    expect(logs.length).toBe(1)
    expect(String(logs[0]?.[0])).toContain("[service-indexer] worker execution failed:")
    expect(exits).toEqual([1])
  })
})

