import { execFile } from 'node:child_process'
import { mkdtemp, readdir, readFile, rm } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { promisify } from 'node:util'

import { buildVectorChunks } from '@/lib/indexing/chunker'
import type {
  ArtifactStore,
  GitLabSource,
  VectorChunkRecord,
  VectorStore,
} from '@/lib/indexing/contracts'
import { embedVectorChunks } from '@/lib/indexing/embedder'
import { DEFAULT_MAX_FILE_SIZE_BYTES, classifySkipReason } from '@/lib/indexing/ignore'
import {
  clearStagedChanges,
  loadExistingStates,
  stageDelete,
  stageUpsert,
} from '@/lib/indexing/staging'
import { sha256Hex } from '@/lib/utils/hash'

const execFileAsync = promisify(execFile)

type SnapshotRunContext = {
  runId: string
  branchStateId: string
  integrationId: string
  configHash: string
  headSha: string
  artifactsPrefix: string
}

type SnapshotResult = {
  stats: Record<string, number>
}

const normalizeRelativePath = (relativePath: string) =>
  relativePath.split(path.sep).join('/')

const resolveMaxFileSizeBytes = () => {
  const raw = process.env.INDEXER_MAX_FILE_SIZE_BYTES
  if (!raw) {
    return DEFAULT_MAX_FILE_SIZE_BYTES
  }

  const parsed = Number.parseInt(raw, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return DEFAULT_MAX_FILE_SIZE_BYTES
  }

  return parsed
}

const toErrorMessage = (error: unknown) =>
  error instanceof Error ? error.message : 'Unexpected embedding failure.'

const wrapEmbeddingError = (args: {
  path: string
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  error: unknown
}) => {
  const maxChunk = args.chunks.reduce<{ chunkIndex: number; size: number } | null>(
    (largest, chunk) => {
      const size = chunk.content.length
      if (!largest || size > largest.size) {
        return {
          chunkIndex: chunk.chunkIndex,
          size,
        }
      }

      return largest
    },
    null,
  )

  const wrapped = new Error(
    `Embedding failed for ${args.path} (chunks=${args.chunks.length}, maxChunkChars=${maxChunk?.size ?? 0}): ${toErrorMessage(args.error)}`,
  )
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    stage: 'embedding',
    path: args.path,
    chunkCount: args.chunks.length,
    maxChunkChars: maxChunk?.size ?? 0,
    maxChunkIndex: maxChunk?.chunkIndex ?? null,
  }

  return wrapped
}

const findExtractedRoot = async (extractDir: string): Promise<string> => {
  const entries = await readdir(extractDir, { withFileTypes: true })
  const directories = entries.filter((entry) => entry.isDirectory())

  if (directories.length === 1) {
    return path.join(extractDir, directories[0].name)
  }

  return extractDir
}

const collectFiles = async (root: string): Promise<string[]> => {
  const files: string[] = []

  const walk = async (currentDir: string) => {
    const entries = await readdir(currentDir, { withFileTypes: true })
    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name)
      if (entry.isDirectory()) {
        await walk(fullPath)
        continue
      }

      if (entry.isFile()) {
        files.push(fullPath)
      }
    }
  }

  await walk(root)
  return files
}

const extractArchive = async (
  archivePath: string,
): Promise<{ extractDir: string; repoRoot: string }> => {
  const extractDir = await mkdtemp(path.join(os.tmpdir(), 'argus-indexer-extract-'))
  await execFileAsync('tar', ['-xzf', archivePath, '-C', extractDir])
  const repoRoot = await findExtractedRoot(extractDir)
  return { extractDir, repoRoot }
}

export const runSnapshotIngest = async (args: {
  run: SnapshotRunContext
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
}): Promise<SnapshotResult> => {
  const maxFileSizeBytes = resolveMaxFileSizeBytes()

  const stats = {
    filesScanned: 0,
    filesProcessed: 0,
    filesUnchanged: 0,
    filesIndexed: 0,
    filesSkipped: 0,
    filesDeleted: 0,
    chunksUpserted: 0,
    embeddingApiCalls: 0,
    embeddingFailures: 0,
    embeddingPromptTokens: 0,
    embeddingTotalTokens: 0,
    embeddingCostUsd: 0,
  }

  const manifestLines: string[] = []
  const changedFileLines: string[] = []

  const existingByPath = await loadExistingStates(args.run.branchStateId)

const seenPaths = new Set<string>()

await clearStagedChanges(args.run.runId)

const { archivePath } = await args.source.downloadArchive({
  integrationId: args.run.integrationId,
  sha: args.run.headSha,
})

let extractDir: string | null = null

try {
  const extracted = await extractArchive(archivePath)
  extractDir = extracted.extractDir
  const absoluteFiles = await collectFiles(extracted.repoRoot)

  for (const absolutePath of absoluteFiles) {
    const relativePath = normalizeRelativePath(
      path.relative(extracted.repoRoot, absolutePath),
    )
    if (!relativePath) {
      continue
    }

    stats.filesScanned += 1
    stats.filesProcessed += 1

    const content = await readFile(absolutePath)
    const skipReason = classifySkipReason({
      relativePath,
      content,
      maxFileSizeBytes,
    })

    if (skipReason) {
      stats.filesSkipped += 1
      manifestLines.push(
        JSON.stringify({ path: relativePath, status: 'skipped', skipReason }),
      )

      if (existingByPath.has(relativePath)) {
        await stageDelete({
          runId: args.run.runId,
          path: relativePath,
          skipReason,
        })
        stats.filesDeleted += 1
      }

      seenPaths.add(relativePath)
      continue
    }

    const fileId = sha256Hex(content)
    const existing = existingByPath.get(relativePath)

if (existing?.fileId === fileId) {
  stats.filesUnchanged += 1
  manifestLines.push(JSON.stringify({ path: relativePath, status: 'unchanged' }))
  seenPaths.add(relativePath)
  continue
}

const chunks = await buildVectorChunks({
  path: relativePath,
  content: content.toString('utf8'),
  configHash: args.run.configHash,
})

if (chunks.length === 0) {
  stats.filesSkipped += 1
  manifestLines.push(
    JSON.stringify({ path: relativePath, status: 'skipped', skipReason: 'no_chunks' }),
  )

  if (existing) {
    await stageDelete({
      runId: args.run.runId,
      path: relativePath,
      skipReason: 'no_chunks',
    })
    stats.filesDeleted += 1
  }

  seenPaths.add(relativePath)
  continue
}

let embeddedChunks: VectorChunkRecord[]
try {
  embeddedChunks = await embedVectorChunks(chunks, {
    onTelemetry: (telemetry) => {
      stats.embeddingApiCalls += telemetry.requestCount
      stats.embeddingFailures += telemetry.failureCount
      stats.embeddingPromptTokens += telemetry.promptTokens
      stats.embeddingTotalTokens += telemetry.totalTokens
      stats.embeddingCostUsd += telemetry.costUsd ?? 0
    },
  })
} catch (error) {
  throw wrapEmbeddingError({
    path: relativePath,
    chunks,
    error,
  })
}

  await args.vectorStore.upsertChunks({
    branchStateId: args.run.branchStateId,
    runId: args.run.runId,
    path: relativePath,
    fileId,
    chunks: embeddedChunks,
  })

  await stageUpsert({
    runId: args.run.runId,
    path: relativePath,
    fileId,
    sizeBytes: content.length,
  })

  stats.filesIndexed += 1
  stats.chunksUpserted += embeddedChunks.length
  manifestLines.push(
    JSON.stringify({
      path: relativePath,
      status: existing ? 'changed' : 'new',
      chunks: embeddedChunks.length,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: relativePath,
      changeType: existing ? 'modified' : 'added',
      fileId,
    }),
  )
  seenPaths.add(relativePath)
}

for (const [existingPath] of existingByPath) {
  if (seenPaths.has(existingPath)) {
    continue
  }

  await stageDelete({
    runId: args.run.runId,
    path: existingPath,
    skipReason: 'deleted',
  })

  stats.filesDeleted += 1
  changedFileLines.push(
    JSON.stringify({
      path: existingPath,
      changeType: 'deleted',
    }),
  )
}

await args.artifactStore.writeManifest({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: manifestLines,
})

await args.artifactStore.writeChangedFiles({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: changedFileLines,
})

    await args.artifactStore.writeRunJson({
      artifactsPrefix: args.run.artifactsPrefix,
      run: {
        runId: args.run.runId,
        mode: 'snapshot',
        headSha: args.run.headSha,
        stats,
      },
    })

    return {
      stats,
    }
  } finally {
    if (extractDir) {
      await rm(extractDir, { recursive: true, force: true })
    }

    await rm(path.dirname(archivePath), { recursive: true, force: true })
  }
}

export const ALPHA_ACCESS_DENIED_MESSAGE = "Access is currently limited to approved alpha testers."

type AlphaAccessConfigInput = {
  enabled?: string
  allowedEmails?: string
}

export type AlphaAccessConfig = {
  enabled: boolean
  allowedEmails: ReadonlySet<string>
  allowedDomains: ReadonlySet<string>
}

const TRUE_VALUES = new Set(["1", "true", "yes", "on"])

const parseBoolean = (value: string | undefined) =>
  value ? TRUE_VALUES.has(value.trim().toLowerCase()) : false

const normalizeEmail = (value: string) => value.trim().toLowerCase()

const parseAllowedEmailTokens = (value: string | undefined) =>
  (value ?? "")
    .split(/[,\s]+/)
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean)

export const buildAlphaAccessConfig = ({
  enabled,
  allowedEmails,
}: AlphaAccessConfigInput): AlphaAccessConfig => {
  const exactEmails = new Set<string>()
  const allowedDomains = new Set<string>()

  for (const token of parseAllowedEmailTokens(allowedEmails)) {
    if (token.startsWith("@") && token.length > 1) {
      allowedDomains.add(token.slice(1))
      continue
    }
    exactEmails.add(token)
  }

  return {
    enabled: parseBoolean(enabled),
    allowedEmails: exactEmails,
    allowedDomains,
  }
}

export const isAlphaAccessEmailAllowedForConfig = (
  config: AlphaAccessConfig,
  email: string | null | undefined,
) => {
  if (!config.enabled) {
    return true
  }

  if (!email) {
    return false
  }

  const normalizedEmail = normalizeEmail(email)
  const domain = normalizedEmail.split("@")[1]

  if (config.allowedEmails.has(normalizedEmail)) {
    return true
  }

  return Boolean(domain && config.allowedDomains.has(domain))
}

const alphaAccessConfig = buildAlphaAccessConfig({
  enabled: process.env.ALPHA_ACCESS_GATE_ENABLED,
  allowedEmails: process.env.ALPHA_ACCESS_ALLOWED_EMAILS,
})

export const isAlphaAccessGateEnabled = alphaAccessConfig.enabled

export const isAlphaAccessEmailAllowed = (email: string | null | undefined) =>
  isAlphaAccessEmailAllowedForConfig(alphaAccessConfig, email)

