        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const scope = resolveDescriptionScopeFromSearchParams(new URL(request.url).searchParams)

      if (!scope) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: "instanceUrl, projectId, and mergeRequestIid are required." },
            { status: 400 },
          ),
        }
      }

      const [{ db }, { aiReviewDescriptions }] = await Promise.all([
        import("@/lib/db"),
        import("@/lib/db/schema"),
      ])

      const rows = await db
        .select({
          id: aiReviewDescriptions.id,
          markdown: aiReviewDescriptions.markdown,
          createdAt: aiReviewDescriptions.createdAt,
        })
        .from(aiReviewDescriptions)
        .where(
          and(
            eq(aiReviewDescriptions.userId, userId),
            eq(aiReviewDescriptions.instanceUrl, scope.instanceUrl),
            eq(aiReviewDescriptions.projectId, scope.projectId),
            eq(aiReviewDescriptions.mergeRequestIid, scope.mergeRequestIid),
          ),
        )
        .orderBy(desc(aiReviewDescriptions.createdAt))
        .limit(1)

      const description = rows[0] ? toPersistedDescription(rows[0]) : null
      logger.set({
        descriptionFound: Boolean(description),
        descriptionId: description?.id ?? null,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: { description } }),
      }
    },
  })
}

