const setMockProviderResponse = (payload: unknown, status = 200) => {
  const fetchMock = mock(async () =>
    new Response(JSON.stringify(payload), {
      status,
      headers: {
        "content-type": "application/json",
      },
    }),
  )
  globalThis.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

const setMockProviderStreamResponse = (ssePayload: string, status = 200) => {
  const stream = new ReadableStream({
    start(controller) {
      controller.enqueue(new TextEncoder().encode(ssePayload))
      controller.close()
    },
  })
  const fetchMock = mock(async () =>
    new Response(stream, {
      status,
      headers: {
        "content-type": "text/event-stream",
      },
    }),
  )
  globalThis.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

const setMockProviderRejected = (error: unknown) => {
  const fetchMock = mock(async () => {
    throw error
  })
  globalThis.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

