test("returns URL-specific upstream error details for provider 404", async () =>
  withEnv(
    {
      AI_API_TOKEN: "server-token",
      AI_API_URL: "https://api.openai.com/v1",
    },
    async () => {
      setMockProviderResponse(
        {
          error: {
            message: "Not Found",
          },
        },
        404,
      )

      const { POST, loggerContext } = await loadRouteModule()

      const response = await POST(
        new Request("http://localhost/api/review/description", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ patch: "diff --git a/a.ts b/a.ts\n+const x = 1;" }),
        }),
      )
      const body = await response.json()

      expect(response.status).toBe(502)
      expect(body.code).toBe("AI_UPSTREAM_ENDPOINT")
      expect(body.providerStatus).toBe(404)
      expect(body.error).toContain("AI_API_URL/OPENAI_BASE_URL")
      expect(loggerContext.errorCode).toBe("AI_UPSTREAM_ENDPOINT")
      expect(loggerContext.providerStatus).toBe(404)
    },
  ))

  test("returns network-specific upstream error details when fetch fails", async () =>
    withEnv(
      {
        AI_API_TOKEN: "server-token",
        AI_API_URL: "https://api.openai.com/v1",
      },
      async () => {
        const networkError = new TypeError("fetch failed")
        ;(networkError as TypeError & { cause?: { code: string } }).cause = {
          code: "ENOTFOUND",
        }
        setMockProviderRejected(networkError)

        const { POST, loggerContext } = await loadRouteModule()

        const response = await POST(
          new Request("http://localhost/api/review/description", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ patch: "diff --git a/a.ts b/a.ts\n+const x = 1;" }),
          }),
        )
        const body = await response.json()

        expect(response.status).toBe(502)
        expect(body.code).toBe("AI_UPSTREAM_NETWORK")
        expect(body.providerStatus).toBeNull()
        expect(body.error).toContain("resolve AI provider host")
        expect(loggerContext.errorCode).toBe("AI_UPSTREAM_NETWORK")
        expect(loggerContext.errorCategory).toBe("network")
      },
    ))
})

