    .onConflictDoUpdate({
      target: [aiReviewGateGlobalSettings.userId],
      set: {
        strictness: settings.strictness,
        requireEvidence: settings.requireEvidence,
        securityBoost: settings.securityBoost,
        updatedAt: now,
      },
    })
}

