type PersistedGraphStore = {
  indexRunId: string
  generatedAt: string
  nodesById: Map<string, PersistedGraphNode>
  nodesByNormalizedFilePath: Map<string, PersistedGraphNode[]>
  nodeIds: string[]
  edges: PersistedGraphEdge[]
  outgoing: Map<string, PersistedGraphEdge[]>
  incoming: Map<string, PersistedGraphEdge[]>
  edgeTypes: string[]
}

let graphStoreCache: PersistedGraphStore | null = null

const resolveIndexPackDir = () => resolveCodeIntelIndexPackDir()
const resolveNodesPath = () => path.join(resolveIndexPackDir(), "graph.nodes.jsonl")
const resolveEdgesPath = () => path.join(resolveIndexPackDir(), "graph.edges.jsonl")
const normalizeGraphFilePath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const parseJsonLine = (line: string): unknown => {
  try {
    return JSON.parse(line)
  } catch {
    return null
  }
}

const readJsonl = async <T>(
  filePath: string,
  parse: (value: unknown) => T | null,
): Promise<T[]> => {
  const records: T[] = []

  const stream = createReadStream(filePath, { encoding: "utf8" })
  const rl = createInterface({ input: stream, crlfDelay: Infinity })

  try {
    for await (const line of rl) {
      const trimmed = line.trim()
      if (!trimmed) {
        continue
      }
      const parsed = parse(parseJsonLine(trimmed))
      if (parsed) {
        records.push(parsed)
      }
    }
  } catch (error) {
    throw new CodeGraphError("invalid_output", "Failed to parse persisted graph JSONL artifact.", {
      filePath,
      message: error instanceof Error ? error.message : "Unknown parsing error.",
    })
  } finally {
    rl.close()
    stream.destroy()
  }

  return records
}

const normalizeNode = (value: unknown): PersistedGraphNode | null => {
  const parsed = graphNodeRecordSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }

  return {
    id: parsed.data.id,
    kind: parsed.data.kind,
    name: parsed.data.name ?? null,
    filePath: parsed.data.filePath ?? null,
    language: parsed.data.language ?? null,
    range: parsed.data.range ?? null,
  }
}

const normalizeEdge = (value: unknown): PersistedGraphEdge | null => {
  const parsed = graphEdgeRecordSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }

  return {
    sourceId: parsed.data.sourceId,
    targetId: parsed.data.targetId,
    type: parsed.data.type,
  }
}

const sampleArray = <T>(items: T[], limit: number): T[] => {
  if (limit <= 0) {
    return []
  }
  if (items.length <= limit) {
    return [...items]
  }

  const out: T[] = []
  const step = items.length / limit
  for (let index = 0; index < limit; index += 1) {
    const sourceIndex = Math.floor(index * step)
    out.push(items[sourceIndex] as T)
  }
  return out
}

const resolveNode = (store: PersistedGraphStore, id: string): PersistedGraphNode =>
  store.nodesById.get(id) ?? {
    id,
    kind: "external",
    name: id,
    filePath: null,
    language: null,
    range: null,
  }

const normalizeEdgeTypeFilter = (edgeTypes: string[] | undefined, available: string[]) => {
  if (!edgeTypes?.length) {
    return null
  }
  const allowed = new Set(available)
  const normalized = edgeTypes
    .map((value) => value.trim())
    .filter((value) => value.length > 0 && allowed.has(value))

  return normalized.length > 0 ? new Set(normalized) : null
}

const filterEdgesByType = (
  edges: PersistedGraphEdge[],
  edgeTypeFilter: Set<string> | null,
): PersistedGraphEdge[] => {
  if (!edgeTypeFilter) {
    return edges
  }
  return edges.filter((edge) => edgeTypeFilter.has(edge.type))
}

const getPersistedGraphStore = async (): Promise<PersistedGraphStore> => {
  const summary = await getCodeGraphSummary()
  if (!summary) {
    throw new CodeGraphError("missing_index_pack", "Code graph index-pack not found. Refresh it first.", null)
  }

  if (graphStoreCache?.indexRunId === summary.indexRunId) {
    return graphStoreCache
  }

  const [nodes, edges] = await Promise.all([
    readJsonl(resolveNodesPath(), normalizeNode),
    readJsonl(resolveEdgesPath(), normalizeEdge),
  ])

  const nodesById = new Map<string, PersistedGraphNode>()
  const nodesByNormalizedFilePath = new Map<string, PersistedGraphNode[]>()
  for (const node of nodes) {
    nodesById.set(node.id, node)
    if (node.filePath) {
      const normalizedFilePath = normalizeGraphFilePath(node.filePath)
      const current = nodesByNormalizedFilePath.get(normalizedFilePath) ?? []
      current.push(node)
      nodesByNormalizedFilePath.set(normalizedFilePath, current)
    }
  }

  const outgoing = new Map<string, PersistedGraphEdge[]>()
  const incoming = new Map<string, PersistedGraphEdge[]>()
  const edgeTypeSet = new Set<string>()
  for (const edge of edges) {
    edgeTypeSet.add(edge.type)

    const out = outgoing.get(edge.sourceId) ?? []
    out.push(edge)
    outgoing.set(edge.sourceId, out)

    const inb = incoming.get(edge.targetId) ?? []
    inb.push(edge)
    incoming.set(edge.targetId, inb)
  }

  const store: PersistedGraphStore = {
    indexRunId: summary.indexRunId,
    generatedAt: summary.generatedAt,
    nodesById,
    nodesByNormalizedFilePath,
    nodeIds: [...nodesById.keys()],
    edges,
    outgoing,
    incoming,
    edgeTypes: [...edgeTypeSet].sort((a, b) => a.localeCompare(b)),
  }
  graphStoreCache = store

  return store
}

export type GraphNeighborhoodDirection = "incoming" | "outgoing" | "both"
export type GraphImpactPreset = "callers" | "callees" | "dependencies" | "dependents" | "impact"

export type PersistedGraphQueryResult = {
  indexRunId: string
  generatedAt: string
  totalNodes: number
  totalEdges: number
  availableEdgeTypes: string[]
  appliedEdgeTypes: string[]
  nodes: PersistedGraphNode[]
  edges: PersistedGraphEdge[]
}

export const getPersistedGraphEdgeTypes = async () => {
  const store = await getPersistedGraphStore()
  return {
    indexRunId: store.indexRunId,
    generatedAt: store.generatedAt,
    edgeTypes: store.edgeTypes,
  }
}

export type PersistedGraphFindingNodeMatch = {
  nodeId: string
  scope: "symbol" | "file"
  sourceFile: string
  sourceLine: number
}

type PersistedGraphTraversalDirection = "incoming" | "outgoing" | "both"

const includesLine = (node: PersistedGraphNode, lineNumber: number) => {
  if (!node.range) {
    return false
  }
  const safeLine = Math.max(1, Math.floor(lineNumber))
  const zeroBasedLine = safeLine - 1
  return zeroBasedLine >= node.range.start.row && zeroBasedLine <= node.range.end.row
}

const nodeSpanRows = (node: PersistedGraphNode) => {
  if (!node.range) {
    return Number.POSITIVE_INFINITY
  }
  return Math.max(0, node.range.end.row - node.range.start.row)
}

const nodeKindRank = (kind: string) => {
  switch (kind.toLowerCase()) {
    case "function":
    case "method":
      return 0
    case "class":
    case "interface":
    case "type":
      return 1
    case "variable":
    case "constant":
      return 2
    case "file":
      return 9
    default:
      return 4
  }
}

const pickBestNode = (nodes: PersistedGraphNode[]) => {
  if (nodes.length === 0) {
    return null
  }
  return [...nodes].sort((left, right) => {
    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    const leftName = left.name ?? ""
    const rightName = right.name ?? ""
    return leftName.localeCompare(rightName)
  })[0] ?? null
}

const collectReachableNodeIds = ({
  store,
  startNodeId,
  direction,
  edgeTypes,
  depth,
  maxNodes,
}: {
  store: PersistedGraphStore
  startNodeId: string
  direction: PersistedGraphTraversalDirection
  edgeTypes: Set<string>
  depth: number
  maxNodes: number
}) => {

  const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
  const visited = new Set<string>([startNodeId])
  const reached = new Set<string>()

  while (queue.length > 0 && reached.size < maxNodes) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= depth) {
      continue
    }

    if (direction !== "incoming") {
      const outgoing = store.outgoing.get(current.id) ?? []
      for (const edge of outgoing) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.targetId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }

    if (direction !== "outgoing") {
      const incoming = store.incoming.get(current.id) ?? []
      for (const edge of incoming) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.sourceId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }
  }

  return reached
}

export const findPersistedGraphNodeForFinding = async (options: {
  filePath: string
  line: number
  title?: string
}): Promise<PersistedGraphFindingNodeMatch | null> => {
  const normalizedFilePath = normalizeGraphFilePath(options.filePath)
  if (!normalizedFilePath) {
    return null
  }

  const store = await getPersistedGraphStore()
  const nodesInFile = store.nodesByNormalizedFilePath.get(normalizedFilePath) ?? []
  if (nodesInFile.length === 0) {
    return null
  }

  const symbolNodes = nodesInFile.filter((node) => node.kind !== "file" && includesLine(node, options.line))
  const normalizedTitle = (options.title ?? "").trim().toLowerCase()
  const symbolNameMatched = normalizedTitle
    ? symbolNodes.filter((node) => {
      const name = (node.name ?? "").trim().toLowerCase()
      return name.length > 0 && normalizedTitle.includes(name)
    })
    : []

  const symbolSourceNode = pickBestNode(symbolNameMatched) ?? pickBestNode(symbolNodes)
  if (symbolSourceNode) {
    return {
      nodeId: symbolSourceNode.id,
      scope: "symbol",
      sourceFile: symbolSourceNode.filePath ?? normalizedFilePath,
      sourceLine: options.line,
    }
  }

  const fileNode = nodesInFile.find((node) => node.kind === "file") ?? nodesInFile[0]
  if (!fileNode) {
    return null
  }

  return {
    nodeId: fileNode.id,
    scope: "file",
    sourceFile: fileNode.filePath ?? normalizedFilePath,
    sourceLine: options.line,
  }
}

export type PersistedGraphImpactSummary = {
  callersCount: number
  calleesCount: number
  dependentsCount: number
  dependenciesCount: number
  affectedFilesCount: number
  affectedSymbolsCount: number
  topImpactedFiles: Array<{ filePath: string; count: number }>
}

export const summarizePersistedGraphImpactForNode = async (options: {
  nodeId: string
  callDepth?: number
  importDepth?: number
  impactDepth?: number
  maxNodes?: number
}): Promise<PersistedGraphImpactSummary> => {
  const store = await getPersistedGraphStore()
  const nodeId = options.nodeId.trim()
  if (!nodeId) {
    throw new CodeGraphError("command_failed", "Impact summary requires a non-empty nodeId.", null)
  }

  const callDepth = Math.min(6, Math.max(1, options.callDepth ?? 2))
  const importDepth = Math.min(6, Math.max(1, options.importDepth ?? 2))
  const impactDepth = Math.min(6, Math.max(1, options.impactDepth ?? 2))
  const maxNodes = Math.min(20_000, Math.max(50, options.maxNodes ?? 4_000))

  const callers = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["CALLS"]),
    depth: callDepth,
    maxNodes,
  })
  const callees = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["CALLS"]),
    depth: callDepth,
    maxNodes,
  })
  const dependents = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["IMPORTS"]),
    depth: importDepth,
    maxNodes,
  })

const dependencies = collectReachableNodeIds({
  store,
  startNodeId: nodeId,
  direction: "outgoing",
  edgeTypes: new Set(["IMPORTS"]),
  depth: importDepth,
  maxNodes,
})
const impacted = collectReachableNodeIds({
  store,
  startNodeId: nodeId,
  direction: "both",
  edgeTypes: new Set(["CALLS", "IMPORTS", "REFERENCES"]),
  depth: impactDepth,
  maxNodes,
})

const fileCounts = new Map<string, number>()
let affectedSymbolsCount = 0
for (const impactedNodeId of impacted) {
  const node = resolveNode(store, impactedNodeId)
  if (node.kind !== "file") {
    affectedSymbolsCount += 1
  }
  if (!node.filePath) {
    continue
  }
  const normalizedFilePath = normalizeGraphFilePath(node.filePath)
  fileCounts.set(normalizedFilePath, (fileCounts.get(normalizedFilePath) ?? 0) + 1)
}

const topImpactedFiles = [...fileCounts.entries()]
  .sort((left, right) => {
    if (right[1] !== left[1]) {
      return right[1] - left[1]
    }
    return left[0].localeCompare(right[0])
  })
  .slice(0, 5)
  .map(([filePath, count]) => ({ filePath, count }))

return {
  callersCount: callers.size,
  calleesCount: callees.size,
  dependentsCount: dependents.size,
  dependenciesCount: dependencies.size,
  affectedFilesCount: fileCounts.size,
  affectedSymbolsCount,
  topImpactedFiles,
}

}

export const samplePersistedGraphForVisualization = async (options: {
  maxNodes?: number
  maxEdges?: number
  edgeTypes?: string[]
} = {}): Promise<PersistedGraphQueryResult> => {
  const store = await getPersistedGraphStore()

  const maxNodes = Math.min(2_000, Math.max(10, options.maxNodes ?? 220))
  const maxEdges = Math.min(10_000, Math.max(10, options.maxEdges ?? 420))

  const edgeTypeFilter = normalizeEdgeTypeFilter(options.edgeTypes, store.edgeTypes)
  const filteredEdges = filterEdgesByType(store.edges, edgeTypeFilter)
  const sampledEdges = sampleArray(filteredEdges, maxEdges)

  const selectedNodeIds = new Set<string>()
  const finalEdges: PersistedGraphEdge[] = []
  for (const edge of sampledEdges) {
    const hasSource = selectedNodeIds.has(edge.sourceId)
    const hasTarget = selectedNodeIds.has(edge.targetId)
    const nodesToAdd = (hasSource ? 0 : 1) + (hasTarget ? 0 : 1)

    if (selectedNodeIds.size + nodesToAdd > maxNodes) {
      continue
    }

    selectedNodeIds.add(edge.sourceId)
    selectedNodeIds.add(edge.targetId)
    finalEdges.push(edge)

    if (finalEdges.length >= maxEdges || selectedNodeIds.size >= maxNodes) {
      break
    }
  }

  const finalNodes = [...selectedNodeIds].map((id) => resolveNode(store, id))

  return {
    indexRunId: store.indexRunId,
    generatedAt: store.generatedAt,
    totalNodes: store.nodeIds.length,
    totalEdges: store.edges.length,
    availableEdgeTypes: store.edgeTypes,
    appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
    nodes: finalNodes,
    edges: finalEdges,
  }
}

export const queryPersistedGraphNeighborhood = async (options: {
  nodeId: string
  depth?: number
  direction?: GraphNeighborhoodDirection
  edgeTypes?: string[]
  maxNodes?: number
  maxEdges?: number
}): Promise<PersistedGraphQueryResult> => {
  const store = await getPersistedGraphStore()

  const nodeId = options.nodeId.trim()
  if (!nodeId) {
    throw new CodeGraphError("command_failed", "Neighborhood query requires a non-empty nodeId.", null)
  }

  const depth = Math.min(6, Math.max(1, options.depth ?? 2))
  const direction: GraphNeighborhoodDirection = options.direction ?? "both"
  const maxNodes = Math.min(2_000, Math.max(10, options.maxNodes ?? 400))
  const maxEdges = Math.min(10_000, Math.max(10, options.maxEdges ?? 900))
  const edgeTypeFilter = normalizeEdgeTypeFilter(options.edgeTypes, store.edgeTypes)

  const queue: Array<{ id: string; depth: number }> = [{ id: nodeId, depth: 0 }]
  const visited = new Set<string>([nodeId])
  const edgesByKey = new Map<string, PersistedGraphEdge>()

while (queue.length > 0 && visited.size < maxNodes && edgesByKey.size < maxEdges) {
  const current = queue.shift()
  if (!current) {
    break
  }
  if (current.depth >= depth) {
    continue
  }

  const outgoing = direction === "incoming" ? [] : store.outgoing.get(current.id) ?? []
  const incoming = direction === "outgoing" ? [] : store.incoming.get(current.id) ?? []
  const candidates = [...outgoing, ...incoming]

  for (const edge of candidates) {
    if (edgeTypeFilter && !edgeTypeFilter.has(edge.type)) {
      continue
    }
    const key = `${edge.sourceId}->${edge.targetId}:${edge.type}`
    if (!edgesByKey.has(key)) {
      edgesByKey.set(key, edge)
    }
    if (edgesByKey.size >= maxEdges) {
      break
    }

    const nextId = edge.sourceId === current.id ? edge.targetId : edge.sourceId
    if (!visited.has(nextId) && visited.size < maxNodes) {
      visited.add(nextId)
      queue.push({ id: nextId, depth: current.depth + 1 })
    }
  }
}

return {
  indexRunId: store.indexRunId,
  generatedAt: store.generatedAt,
  totalNodes: store.nodeIds.length,
  totalEdges: store.edges.length,
  availableEdgeTypes: store.edgeTypes,
  appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
  nodes: [...visited].map((id) => resolveNode(store, id)),
  edges: [...edgesByKey.values()],
}

}

export const queryPersistedGraphImpactPreset = async (options: {
  nodeId: string
  preset: GraphImpactPreset
  depth?: number
  maxNodes?: number
  maxEdges?: number
}): Promise<PersistedGraphQueryResult> => {
  const presetToQuery: Record<
    GraphImpactPreset,
    { direction: GraphNeighborhoodDirection; edgeTypes: string[] }
  > = {
    callers: { direction: "incoming", edgeTypes: ["CALLS"] },
    callees: { direction: "outgoing", edgeTypes: ["CALLS"] },
    dependencies: { direction: "outgoing", edgeTypes: ["IMPORTS"] },
    dependents: { direction: "incoming", edgeTypes: ["IMPORTS"] },
    impact: { direction: "both", edgeTypes: ["CALLS", "IMPORTS", "REFERENCES"] },
  }

  const mapping = presetToQuery[options.preset]
  return queryPersistedGraphNeighborhood({
    nodeId: options.nodeId,
    depth: options.depth,
    direction: mapping.direction,
    edgeTypes: mapping.edgeTypes,
    maxNodes: options.maxNodes,
    maxEdges: options.maxEdges,
  })
}

import { describe, expect, test } from 'bun:test'

import { __testables } from '@/lib/indexing/embedder'
import { INDEX_VECTOR_DIMENSION } from '@/lib/indexing/constants'

describe('embedder batching', () => {
  test('splits requests when estimated tokens exceed request limit', () => {
    const batches = __testables.buildEmbeddingBatches({
      inputs: ['a'.repeat(3_000), 'b'.repeat(3_000), 'c'.repeat(3_000)],
      maxBatchSize: 32,
      maxRequestTokens: 8_000,
    })

    expect(batches).toHaveLength(2)
    expect(batches[0]).toHaveLength(2)
    expect(batches[1]).toHaveLength(1)
  })

  test('still honors max batch item count', () => {
    const batches = __testables.buildEmbeddingBatches({
      inputs: ['one', 'two', 'three', 'four', 'five'],
      maxBatchSize: 2,
      maxRequestTokens: 8_000,
    })

    expect(batches).toHaveLength(3)
    expect(batches[0]).toEqual(['one', 'two'])
    expect(batches[1]).toEqual(['three', 'four'])
    expect(batches[2]).toEqual(['five'])
  })

  test('estimates tokens as utf8 byte upper bound', () => {
    expect(__testables.estimateTokenUpperBound('abc')).toBe(3)
    expect(__testables.estimateTokenUpperBound('🙂')).toBe(4)
  })

  test('dedupes misses by chunk id before cache upsert', () => {
    const misses = __testables.collectUniqueMisses({
      chunks: [
        {
          chunkId: 'same',
          chunkIndex: 0,
          content: 'hello',
          metadata: {},
        },
        {
          chunkId: 'same',
          chunkIndex: 1,
          content: 'hello',
          metadata: {},
        },
        {
          chunkId: 'other',
          chunkIndex: 2,
          content: 'world',
          metadata: {},
        },
      ],
      cached: new Map(),
      model: 'openai:test:model',
    })

    expect(misses).toHaveLength(2)
    expect(misses.map((entry) => entry.chunkId)).toEqual(['same', 'other'])
  })

  test('skips misses when cache hit model and dimension match', () => {
    const misses = __testables.collectUniqueMisses({
      chunks: [
        {
          chunkId: 'cached',
          chunkIndex: 0,
          content: 'hello',
          metadata: {},
        },
      ],
      cached: new Map([
        [
          'cached',
          {
            model: 'openai:test:model',
            embedding: Array.from({ length: INDEX_VECTOR_DIMENSION }, () => 0),
          },
        ],
      ]),
      model: 'openai:test:model',
    })

    expect(misses).toHaveLength(0)
  })
})

