#!/usr/bin/env node

import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const cwd = process.cwd();

const readSource = (relativePath) =>
  readFileSync(resolve(cwd, relativePath), "utf8");

const checks = [
  {
    id: "cache_headers_static_assets",
    description: "next config has immutable static cache headers",
    run: () => {
      const source = readSource("next.config.ts");
      return (
        source.includes('source: "/_next/static/:path*"') &&
        source.includes("max-age=31536000, immutable")
      );
    },
  },
  {
    id: "route_nav_metrics",
    description: "app layout emits route nav timing metadata",
    run: () => {
      const source = readSource("src/app/(app)/app-layout-client.tsx");
      return (
        source.includes("navDurationMs") &&
        source.includes("prefetchHit") &&
        source.includes("route_navigation")
      );
    },
  },
  {
    id: "query_defaults",
    description: "query provider uses aggressive stale/gc windows",
    run: () => {
      const source = readSource("src/components/query-provider.tsx");
      return (
        source.includes("staleTime: 10 * 60_000") &&
        source.includes("gcTime: 45 * 60_000")
      );
    },
  },
  {
    id: "mr_loading_skeleton",
    description: "merge request page uses skeleton fallback instead of blocking text loader",
    run: () => {
      const source = readSource("src/app/(app)/repos/[integrationId]/mrs/[mergeRequestIid]/page.tsx");
      return source.includes("<Skeleton");
    },
  },
];

let warnings = 0;

console.log("Performance report (warn-only):");
for (const check of checks) {
  try {
    const passed = check.run();
    if (passed) {
      console.log(`  [ok]   ${check.id} - ${check.description}`);
    } else {
      warnings += 1;
      console.log(`  [warn] ${check.id} - ${check.description}`);
    }
  } catch (error) {
    warnings += 1;
    console.log(
      `  [warn] ${check.id} - check failed to run: ${
        error instanceof Error ? error.message : "unknown error"
      }`,
    );
  }
}

console.log(
  `Summary: ${checks.length - warnings} passing, ${warnings} warnings (non-blocking).`,
);
process.exit(0);

import type { NextRequest } from "next/server"
import { NextResponse } from "next/server"
import { getSessionCookie } from "better-auth/cookies"

const PUBLIC_PATHS = new Set(["/"])
// Onboarding auth is enforced server-side in app layout; keeping it public here avoids
// proxy/session false negatives that can cause redirect loops on first-login flows.
const PUBLIC_PREFIXES = ["/sign-up", "/welcome", "/onboarding"]
const GITLAB_MERGE_REQUEST_PATH_PATTERN = /^\/(.+)\/-\/merge_requests\/([^/]+)(?:\/.*)?$/

const isPublicPath = (pathname: string) =>
  PUBLIC_PATHS.has(pathname) ||
  PUBLIC_PREFIXES.some((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`))

const parseGitLabMergeRequestPath = (pathname: string) => {
  const match = pathname.match(GITLAB_MERGE_REQUEST_PATH_PATTERN)
  if (!match) {
    return null
  }

  const projectPath = match[1]?.trim().replace(/^\/+|\/+$/g, "")
  const mergeRequestIid = match[2]?.trim()
  if (!projectPath || !mergeRequestIid) {
    return null
  }

  return { projectPath, mergeRequestIid }
}

export function proxy(request: NextRequest) {
  const { pathname, search } = request.nextUrl

  if (isPublicPath(pathname)) {
    return NextResponse.next()
  }

  const sessionToken = getSessionCookie(request)
  if (sessionToken) {
    const gitLabMergeRequestPath = parseGitLabMergeRequestPath(pathname)
    if (gitLabMergeRequestPath) {
      const bridgeUrl = new URL("/mr-bridge", request.url)
      bridgeUrl.searchParams.set("projectPath", gitLabMergeRequestPath.projectPath)
      bridgeUrl.searchParams.set("mergeRequestIid", gitLabMergeRequestPath.mergeRequestIid)
      const requestedInstance = request.nextUrl.searchParams.get("instance")
      if (requestedInstance) {
        bridgeUrl.searchParams.set("instance", requestedInstance)
      }
      return NextResponse.rewrite(bridgeUrl)
    }

    return NextResponse.next()
  }

  const redirectUrl = new URL("/", request.url)
  const nextPath = `${pathname}${search}`
  if (nextPath !== "/") {
    redirectUrl.searchParams.set("next", nextPath)
  }

  return NextResponse.redirect(redirectUrl)
}

export const config = {
  matcher: ["/((?!api|_next/static|_next/image|favicon.ico|.*\\..*).*)"],
}

