  }))

  const mod = await import(`@/lib/session.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
  return {
    ...mod,
    getSessionMock,
  }
}

describe("session helper caching", () => {
  test("reuses the same session access result across repeated calls", async () => {
    const { getSessionAccess, getSession, getSessionMock } = await loadSessionModule()

    const [accessOne, accessTwo, sessionValue] = await Promise.all([
      getSessionAccess(),
      getSessionAccess(),
      getSession(),
    ])

    expect(accessOne.session?.user?.id).toBe("user-1")
