const applyPersistedCommentPublishByKey = useCallback(
  (commentPublishByKey: Record<string, ReviewCommentPublishState>) => {
    const postedKeys = new Set<string>()
    const postingKeys = new Set<string>()
    const errorsByKey: Record<string, string> = {}

    for (const [commentKey, state] of Object.entries(commentPublishByKey)) {
      if (state.status === "succeeded") {
        postedKeys.add(commentKey)
        continue
      }
      if (state.status === "pending" || state.status === "processing") {
        postingKeys.add(commentKey)
      }
      if ((state.status === "failed" || state.status === "dead") && state.lastError.trim()) {
        errorsByKey[commentKey] = state.lastError.trim()
      }
    }

    setReviewCommentPostedToGitLabKeys(postedKeys)
    setSubmittingReviewCommentGitLabKeys(postingKeys)
    setRemovingReviewCommentGitLabKeys(new Set())
    setReviewCommentGitLabErrorByKey(errorsByKey)
  },
  [],
)

