const HOME_CACHE_TTL_MS = 20_000
const HOME_CACHE_MAX_ENTRIES = 128

type HomeCacheEntry<T> = {
  expiresAt: number
  value: Promise<T>
}

const homeOnboardingStatusCache = new Map<string, HomeCacheEntry<boolean>>()

const trimHomeCache = <T,>(cache: Map<string, HomeCacheEntry<T>>) => {
  const now = Date.now()
  for (const [key, value] of cache.entries()) {
    if (value.expiresAt <= now) {
      cache.delete(key)
    }
  }

  while (cache.size > HOME_CACHE_MAX_ENTRIES) {
    const oldestKey = cache.keys().next().value
    if (!oldestKey) {
      break
    }
    cache.delete(oldestKey)
  }
}

const getCachedHomeValue = <T,>(
  cache: Map<string, HomeCacheEntry<T>>,
  key: string,
  load: () => Promise<T>,
) => {
  const now = Date.now()
  const cached = cache.get(key)
  if (cached && cached.expiresAt > now) {
    return cached.value
  }
  if (cached) {
    cache.delete(key)
  }

  const value = load()
  cache.set(key, {
    expiresAt: now + HOME_CACHE_TTL_MS,
    value,
  })
  trimHomeCache(cache)

  value.catch(() => {
    const current = cache.get(key)
    if (current?.value === value) {
      cache.delete(key)
    }
  })

  return value
}

export default async function HomePage() {
  const { session, isAlphaDenied } = await getSessionAccess()

  if (!session?.user?.id) {
    return (
      <div className="flex min-h-dvh items-center justify-center px-4">
