import { auth } from "@/lib/auth";
import {
  ALPHA_ACCESS_DENIED_MESSAGE,
  isAlphaAccessEmailAllowed,
  isAlphaAccessGateEnabled,
} from "@/lib/alpha-access";
import { runWithApiRequestLog } from "@/lib/utils/logger";
import { NextResponse } from "next/server";
import { toNextJsHandler } from "better-auth/next-js";

const authHandlers = toNextJsHandler(auth);

type AuthRouteHandler = (typeof authHandlers)["GET"];
const EMAIL_AUTH_SUFFIXES = ["/sign-in/email", "/sign-up/email"];

const isEmailAuthRoute = (pathname: string) =>
  EMAIL_AUTH_SUFFIXES.some((suffix) => pathname.endsWith(suffix));

const extractEmailFromRequestBody = async (request: Request) => {
  try {
    const payload = await request.clone().json();
    if (
      payload &&
      typeof payload === "object" &&
      "email" in payload &&
      typeof payload.email === "string"
    ) {
      return payload.email.trim();
    }
  } catch {
    // Ignore malformed payloads and deny by default when gate is active.
  }
  return null;
};

const withAuthRequestLog =
  (method: "GET" | "POST") =>
  async (...args: Parameters<AuthRouteHandler>) => {
    const [request] = args;
    return runWithApiRequestLog({
      request,
      path: "/api/auth/[...all]",
      event: `api.auth.${method.toLowerCase()}`,
      handler: async () => {
        const pathname = new URL(request.url).pathname;
        if (method === "POST" && isAlphaAccessGateEnabled && isEmailAuthRoute(pathname)) {
          const email = await extractEmailFromRequestBody(request);
          if (!isAlphaAccessEmailAllowed(email)) {
            const response = NextResponse.json(
              {
                message: ALPHA_ACCESS_DENIED_MESSAGE,
              },
              { status: 403 },
            );
            return {
              response,
              status: response.status,
              outcome: "alpha_denied",
            };
          }
        }

        const response = await authHandlers[method](...args);
        return {
          response,
          status: response.status,
          outcome: response.ok ? "success" : "error",
        };
      },
    });
  };

export const GET = withAuthRequestLog("GET");
export const POST = withAuthRequestLog("POST");

