import { count, eq } from "drizzle-orm"

import { db } from "@/lib/db"
import { aiDefaultTokenUsage } from "@/lib/db/schema"

const DEFAULT_USAGE_LIMIT = 3

export type DefaultTokenUsageType = "review" | "description"

export type DefaultTokenUsageSummary = {
  limit: number
  used: number
  remaining: number
}

const toSafeInteger = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }

  const parsed = Number.parseInt(String(value ?? ""), 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return 0
  }
  return parsed
}

export const getDefaultTokenUsageLimit = () => {
  const parsed = Number.parseInt(process.env.AI_DEFAULT_TOKEN_USAGE_LIMIT ?? "", 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return DEFAULT_USAGE_LIMIT
  }
  return parsed
}

export const buildDefaultTokenUsageLimitMessage = (limit: number) =>
  `Default AI key limit reached (${limit} review/description runs). Add your own API token in Settings > AI to continue.`

export const getDefaultTokenUsageSummary = async (
  userId: string,
): Promise<DefaultTokenUsageSummary> => {
  const limit = getDefaultTokenUsageLimit()
  if (limit <= 0) {
    return { limit, used: 0, remaining: Number.MAX_SAFE_INTEGER }
  }

  const rows = await db
    .select({ value: count() })
    .from(aiDefaultTokenUsage)
    .where(eq(aiDefaultTokenUsage.userId, userId))

  const used = toSafeInteger(rows[0]?.value)
  return {
    limit,
    used,
    remaining: Math.max(0, limit - used),
  }
}

export const ensureDefaultTokenUsageAvailable = async ({
  userId,
  usesServerToken,
}: {
  userId: string
  usesServerToken: boolean
}) => {
  if (!usesServerToken) {
    return { limited: false as const, summary: null as DefaultTokenUsageSummary | null }
  }

  const summary = await getDefaultTokenUsageSummary(userId)
  if (summary.limit <= 0 || summary.remaining > 0) {
    return { limited: false as const, summary }
  }

  return { limited: true as const, summary }
}

export const consumeDefaultTokenUsage = async ({
  userId,
  usesServerToken,
  requestType,
}: {
  userId: string
  usesServerToken: boolean
  requestType: DefaultTokenUsageType
}) => {
  const availability = await ensureDefaultTokenUsageAvailable({ userId, usesServerToken })
  if (availability.limited || !availability.summary) {
    return availability
  }

  await db.insert(aiDefaultTokenUsage).values({
    userId,
    requestType,
  })

  return {
    limited: false as const,
    summary: {
      ...availability.summary,
      used: availability.summary.used + 1,
      remaining: Math.max(0, availability.summary.remaining - 1),
    },
  }
}

