type ReviewFinding = {
  file: string
  line: number
  side: "additions" | "deletions"
  severity: "high" | "med" | "low"
  title: string
  body: string
  confidence: number
  evidence?: string
}

type ChatCompletionsResponse = {
  choices?: Array<{
    message?: {
      content?: unknown
    }
  }>
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
  }
}

type ReviewScope = {
  instanceUrl: string
  projectId: string
  mergeRequestIid: string
}

type PersistedReview = {
  id: string
  summary: string
  findings: ReviewFinding[]
  feedback: "up" | "down" | null
  commentFeedbackByKey: Record<string, "up" | "down">
  commentPublishByKey: Record<string, {
    status: "pending" | "processing" | "failed" | "succeeded" | "dead"
    attempts: number
    lastError: string
    discussionId: string | null
    noteId: string | null
    updatedAt: string
  }>
  createdAt: string
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const isPrivateOrLocalHost = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  if (
    normalized === "localhost" ||
    normalized.endsWith(".localhost") ||
    normalized === "0.0.0.0" ||
    normalized === "::1" ||
    normalized.endsWith(".local") ||
    normalized.endsWith(".internal")
  ) {
    return true
  }

  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(normalized)) {
    const octets = normalized.split(".").map((part) => Number.parseInt(part, 10))
    if (octets.some((value) => !Number.isFinite(value) || value < 0 || value > 255)) {
      return true
    }

    const [a, b] = octets
    if (
      a === 10 ||
      a === 127 ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127)
    ) {
      return true
    }
  }

  if (
    normalized.includes(":") &&
    (normalized.startsWith("fc") || normalized.startsWith("fd") || normalized.startsWith("fe80:"))
  ) {
    return true
  }

  return false
}

const resolveReviewScopeFromSearchParams = (params: URLSearchParams): ReviewScope | null => {
  const instanceUrl = normalizeApiUrl(params.get("instanceUrl") ?? "")
  const projectId = (params.get("projectId") ?? "").trim()
  const mergeRequestIid = (params.get("mergeRequestIid") ?? "").trim()
  if (!instanceUrl || !projectId || !mergeRequestIid) {
    return null
  }
  return {
    instanceUrl,
    projectId,
    mergeRequestIid,
  }
}

const toPersistedReview = (row: {
  id: string
  summary: string
  findings: AiReviewFinding[]
  feedback: "up" | "down" | null
  createdAt: Date
}, commentFeedbackByKey: Record<string, "up" | "down">, commentPublishByKey: PersistedReview["commentPublishByKey"]): PersistedReview => ({
  id: row.id,
  summary: row.summary,
  findings: row.findings as ReviewFinding[],
  feedback: row.feedback,
  commentFeedbackByKey,
  commentPublishByKey,
  createdAt: row.createdAt.toISOString(),
})

const resolveApiUrl = (raw: string) => {
  let parsed: URL
  try {
    parsed = new URL(raw)
  } catch {
    throw new Error("AI_API_URL (or OPENAI_BASE_URL) must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("AI provider URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("AI provider URL must not include credentials.")
  }
  if (isPrivateOrLocalHost(parsed.hostname)) {
    throw new Error("AI provider URL must not target localhost or private network hosts.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

export const resolveServerApiUrl = () => resolveApiUrl(getEnvApiUrl())

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const getEnvModel = () =>
  pickFirstNonEmpty(
    process.env.AI_MODEL,
    process.env.OPENAI_MODEL,
  ) || DEFAULT_AI_MODEL

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  )

export const resolveReviewRequestInput = (
  payload: ReviewRequestPayload | null,
): ResolvedReviewRequest => {
  const serverApiUrl = resolveServerApiUrl()
  const clientApiUrl = isNonEmptyString(payload?.apiUrl)
    ? resolveApiUrl(payload.apiUrl)
    : null
  const apiUrl = clientApiUrl ?? serverApiUrl
  const hasCustomApiUrl = Boolean(clientApiUrl && normalizeApiUrl(clientApiUrl) !== serverApiUrl)

  const clientToken = isNonEmptyString(payload?.token) ? payload.token.trim() : ""
  if (hasCustomApiUrl && !clientToken) {
    throw new Error("Custom AI provider URL requires an explicit token.")
  }

  return {
    patch: isNonEmptyString(payload?.patch) ? payload.patch : "",
    apiUrl,
    model: isNonEmptyString(payload?.model) ? payload.model.trim() : getEnvModel(),
    token: clientToken || getEnvToken(),
    usesServerToken: clientToken.length === 0,
  }
}

const toReviewSide = (value: unknown): ReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()

  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }

  return "additions"
}

const toReviewSeverity = (value: unknown): ReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }

  return Math.max(0, Math.min(1, value))
}

const toEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const sanitizeAssistantContent = (content: string) => {
  const trimmed = content.trim()
  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i)
  const candidate = (fenced?.[1] ?? trimmed).trim()
  const firstBrace = candidate.indexOf("{")
  const lastBrace = candidate.lastIndexOf("}")

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return candidate.slice(firstBrace, lastBrace + 1)
  }

  return candidate
}

const parseFindings = (content: unknown): ReviewFinding[] => {
  if (!isNonEmptyString(content)) {
    return []
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(sanitizeAssistantContent(content))
  } catch {
    return []
  }

  const rawFindings = (() => {
    if (Array.isArray(parsed)) {
      return parsed
    }
    if (parsed && typeof parsed === "object") {
      const maybeFindings = (parsed as { findings?: unknown }).findings
      if (Array.isArray(maybeFindings)) {
        return maybeFindings
      }
    }
    return []
  })()

  const normalized = rawFindings
    .map<ReviewFinding | null>((value) => {
      if (!value || typeof value !== "object") {
        return null
      }

      const finding = value as Record<string, unknown>
      const line = Number(finding.line)
      const file = String(finding.file ?? "").trim()
      const title = String(finding.title ?? "").trim()
      const body = String(finding.body ?? finding.explanation ?? "").trim()

      if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
        return null
      }

      return {
        file,
        line: Math.floor(line),
        side: toReviewSide(finding.side),
        severity: toReviewSeverity(finding.severity),
        title,
        body,
        confidence: toConfidence(finding.confidence),
        evidence: toEvidence(finding.evidence),
      } satisfies ReviewFinding
    })
    .filter((finding): finding is ReviewFinding => finding !== null)

  return normalized.slice(0, MAX_FINDINGS)
}

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderError = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  return bodyText.slice(0, 400)
}

const sanitizeReviewErrorMessage = (message: string) => {
  const normalized = message.trim().replace(/\s+/g, " ")
  if (!normalized) {
    return GENERIC_AI_REVIEW_ERROR
  }

  const looksLikeRawSqlLeak =
    /failed query:/i.test(normalized) ||
    /\bparams:\b/i.test(normalized) ||
    /\binsert into\b/i.test(normalized) ||
    /\bon conflict\b/i.test(normalized)

  if (looksLikeRawSqlLeak) {
    return GENERIC_AI_REVIEW_ERROR
  }

  const MAX_ERROR_LENGTH = 220
  if (normalized.length > MAX_ERROR_LENGTH) {
    return `${normalized.slice(0, MAX_ERROR_LENGTH - 1)}…`
  }

  return normalized
}

const getReviewErrorMessage = (error: unknown) => {
  if (error instanceof Error) {
    return sanitizeReviewErrorMessage(error.message)
  }
  if (typeof error === "string") {
    return sanitizeReviewErrorMessage(error)
  }
  return GENERIC_AI_REVIEW_ERROR
}

const buildSystemPrompt = () =>
  [
    "You are a senior software code reviewer.",
    "Review a git patch and identify likely real issues only.",
    "Focus on syntax, logic bugs, regressions, null/async issues, and security risks.",
    "Avoid style-only feedback unless it materially affects maintainability or correctness.",
    "Return strictly JSON with shape:",
    '{"findings":[{"file":"path","line":1,"side":"additions|deletions","severity":"high|med|low","title":"short","body":"why it matters + fix hint","confidence":0.0,"evidence":"optional snippet/symbol proving the issue"}]}',
    "Use only file paths and changed line numbers from the patch.",
    `Limit findings to ${MAX_FINDINGS}.`,
  ].join("\n")

const requestReview = async ({
  patch,
  apiUrl,
  model,
  token,
}: {
  patch: string
  apiUrl: string
  model: string
  token: string
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, CHAT_TIMEOUT_MS)
  const startedAt = Date.now()

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.1,
      messages: [
        { role: "system", content: buildSystemPrompt() },
        { role: "user", content: `Review this patch:\n\n${patch}` },
      ],
    }),
    signal: controller.signal,
  })

  if (!response.ok) {
    const providerError = await readProviderError(response)
    throw new Error(
      `AI provider request failed (${response.status})${providerError ? `: ${providerError}` : ""}`,
    )
  }

  const payload = (await response.json()) as ChatCompletionsResponse
  const content = payload.choices?.[0]?.message?.content
  const findings = reconcileFindingLinesWithPatch({
    patch,
    findings: parseFindings(content),
  })
  const usage = extractUsageFromOpenAiCompatiblePayload(payload)
  const latencyMs = Math.max(1, Date.now() - startedAt)
  const provider = resolveLlmProviderLabel(apiUrl)
  return {
    findings,
    llmMetrics: buildLlmMetrics({
      provider,
      model,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      latencyMs,
      requestCount: 1,
    }),
  }
} catch (error) {
  if (error instanceof Error && error.name === "AbortError") {
    throw new Error("AI review timed out.")
  }
  throw error
} finally {

    clearTimeout(timeout)
  }
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff",
    event: "api.review.diff",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<ReviewRequestPayload | null>,
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
