    },
  }),
])

if (eventWriteResult.status === "rejected") {
  logger.set({
    onboardingEventWriteError:
      eventWriteResult.reason instanceof Error
        ? eventWriteResult.reason.message
        : "unknown",
  })
}

let onboardingCompletion: Awaited<
  ReturnType<typeof recordOnboardingCompletedIfMissing>
> | null = null
if (completionResult.status === "fulfilled") {
  onboardingCompletion = completionResult.value
} else {
  logger.set({
    onboardingCompletionWriteError:
      completionResult.reason instanceof Error
        ? completionResult.reason.message
        : "unknown",
  })
}

        return {
