export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff",
    event: "api.review.diff.latest",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const scope = resolveReviewScopeFromSearchParams(new URL(request.url).searchParams)
      if (!scope) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: "instanceUrl, projectId, and mergeRequestIid are required." },
            { status: 400 },
          ),
        }
      }

const gatePreferences = await resolveReviewGatePreferences({
  userId,
  scope: {
    instanceUrl: scope.instanceUrl,
    projectId: scope.projectId,
  },
})
const integration = await commentPublish.resolveManagedIntegrationForScope({
  userId,
  instanceUrl: scope.instanceUrl,
  projectId: scope.projectId,
})

const rows = await db
  .select({
    id: aiReviewRuns.id,
    summary: aiReviewRuns.summary,
    findings: aiReviewRuns.findings,
    feedback: aiReviewRuns.feedback,
    createdAt: aiReviewRuns.createdAt,
  })
  .from(aiReviewRuns)
  .where(
    and(
      eq(aiReviewRuns.userId, userId),
      eq(aiReviewRuns.instanceUrl, scope.instanceUrl),
      eq(aiReviewRuns.projectId, scope.projectId),
      eq(aiReviewRuns.mergeRequestIid, scope.mergeRequestIid),
    ),
  )
  .orderBy(desc(aiReviewRuns.createdAt))
  .limit(1)

let review: PersistedReview | null = null
let suppressedFindingsCount = 0
let suppressedByReason = {
  lowConfidence: 0,
  missingEvidence: 0,
}

if (rows[0]) {
  const gateResult = applyReviewGate({
    findings: rows[0].findings as ReviewFinding[],
    settings: gatePreferences.effectiveSettings,
  })
  suppressedFindingsCount = gateResult.suppressedFindingsCount
  suppressedByReason = gateResult.suppressedByReason

  const commentFeedbackRows = await db
    .select({
      commentKey: aiReviewCommentFeedback.commentKey,
      feedback: aiReviewCommentFeedback.feedback,
    })
    .from(aiReviewCommentFeedback)
    .where(
      and(
        eq(aiReviewCommentFeedback.reviewId, rows[0].id),
        eq(aiReviewCommentFeedback.userId, userId),
      ),
    )
  const commentFeedbackByKey = Object.fromEntries(
    commentFeedbackRows.map((row) => [row.commentKey, row.feedback]),
  )
  const commentPublishByKey = await commentPublish.getCommentPublishByKeyForReview({
    integrationId: integration?.id ?? null,
    mergeRequestIid: scope.mergeRequestIid,
    findings: gateResult.filteredFindings as AiReviewFinding[],
  })
  review = toPersistedReview(
    {
      ...rows[0],
      findings: gateResult.filteredFindings as AiReviewFinding[],
    },
    commentFeedbackByKey,
    commentPublishByKey,
  )
}

      logger.set({
        reviewFound: Boolean(review),
        reviewId: review?.id ?? null,
        commentFeedbackCount: review ? Object.keys(review.commentFeedbackByKey).length : 0,
        commentPublishCount: review ? Object.keys(review.commentPublishByKey).length : 0,
        suppressedFindingsCount,
        suppressedByReason,
        gateScopeSource: gatePreferences.effectiveSettings.scopeSource,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            review,
            suppressedFindingsCount,
            suppressedByReason,
            gateProfile: gatePreferences.effectiveSettings,
          },
        }),
      }
    },
  })
}

