  }> = []
  const createdLoggerPaths: string[] = []
  const cycleEmits: Record<string, unknown>[] = []
  let flushCalls = 0
  let batchCalls = 0

  const createScopedLogger = (args: { path: string }) => {
    createdLoggerPaths.push(args.path)
    return {
      set: (_fields: Record<string, unknown>) => {},
      emit: (fields: Record<string, unknown>) => {
        cycleEmits.push(fields)
      },
    }
  }

return {
  infoLogs,
  initCalls,
  logScopedErrorCalls,
  createdLoggerPaths,
  cycleEmits,
  getFlushCalls: () => flushCalls,
  getBatchCalls: () => batchCalls,
  deps: {
    initAppLogger: (args: Record<string, unknown>) => {
      initCalls.push(args)
    },
    appLogInfo: (fields: Record<string, unknown>) => {
      infoLogs.push(fields)
    },
    createScopedLogger,
    logScopedError: (
      _logger: { set: (fields: Record<string, unknown>) => void; emit: (fields: Record<string, unknown>) => void },
      error: unknown,
      metadata?: Record<string, unknown>,
    ) => {
      logScopedErrorCalls.push({ error, metadata })
    },
    flushAppLogger: async () => {
      flushCalls += 1
    },
    runIndexingWorkerBatch: async (_batchSize: number) => {
