export const resolvePostingToken = async ({
  userId,
  instanceUrl,
  integrationId,
}: {
  userId: string
  instanceUrl: string
  integrationId: string
}) => {
  let storedToken = null as Awaited<ReturnType<typeof getGitLabUserInstanceToken>>
  try {
    storedToken = await getGitLabUserInstanceToken(userId, instanceUrl)
  } catch {
    storedToken = null
  }

  if (storedToken && !storedToken.staleAt && storedToken.token.trim()) {
    return {
      token: storedToken.token.trim(),
      source: "stored_user" as const,
    }
  }

  const integration = await db.query.gitlabIntegrations.findFirst({
    where: eq(gitlabIntegrations.id, integrationId),
  })
  if (!integration) {
    throw new Error("Integration not found for comment publication.")
  }
  const fallbackToken = (await decryptIntegrationFallbackToken(integration)).trim()
  if (!fallbackToken) {
    throw new Error("Integration token is unavailable.")
  }

  return {
    token: fallbackToken,
    source: "integration" as const,
  }
}

const decryptIntegrationFallbackToken = async (integration: GitLabIntegrationRow) => {
  if (!integration.tokenCiphertext || !integration.tokenIv || !integration.tokenAuthTag) {
    throw new Error("Integration token is unavailable.")
  }

  const { decryptGitLabToken } = await import("@/lib/gitlab/crypto")
  return decryptGitLabToken({
    ciphertext: integration.tokenCiphertext,
    iv: integration.tokenIv,
    authTag: integration.tokenAuthTag,
  })
}

export const classifyPublishError = (error: unknown) => {
  const message = error instanceof Error ? error.message : "Unexpected publish error."

  if (error instanceof MergeRequestDiscussionError) {
    if (error.code === "missing_diff_refs") {
      return { retryable: true, message }
    }
    return { retryable: false, message }
  }

  if (error instanceof GitLabApiError) {
    if (error.status >= 500 || error.status === 429 || error.status === 408 || error.status === 409) {
      return { retryable: true, message }
    }
    return { retryable: false, message }
  }

  return { retryable: true, message }
}

