const clearPublicationPostedState = async ({
  id,
}: {
  id: string
}) => {
  await db
    .update(aiReviewCommentPublications)
    .set({
      status: "dead",
      attempts: 0,
      nextAttemptAt: nowDate(),
      lastError: null,
      gitlabDiscussionId: null,
      gitlabNoteId: null,
      postedAt: null,
      updatedAt: nowDate(),
    })
    .where(eq(aiReviewCommentPublications.id, id))
}

const markPublicationFailed = async ({
  id,
  attempts,
  retryable,
  message,
}: {
  id: string
  attempts: number
  retryable: boolean
  message: string
}) => {
  const exceededAttempts = attempts >= MAX_ATTEMPTS
  const shouldRetry = retryable && !exceededAttempts
  await db
    .update(aiReviewCommentPublications)
    .set({
      status: shouldRetry ? "failed" : "dead",
      nextAttemptAt: shouldRetry
        ? new Date(Date.now() + getRetryDelayMs(attempts))
        : nowDate(),
      lastError: message.slice(0, 500),
      updatedAt: nowDate(),
    })
    .where(eq(aiReviewCommentPublications.id, id))
}

const processClaimedPublication = async (
  publication: ClaimedPublication,
): Promise<{ status: "succeeded" | "failed" | "dead" }> => {
  try {
    const resolved = await resolvePostingToken({
      userId: publication.userId,
      instanceUrl: publication.instanceUrl,
      integrationId: publication.integrationId,
    })

    const result = await createMergeRequestDiscussion({
      instanceUrl: publication.instanceUrl,
      token: resolved.token,
      projectId: publication.projectId,
      mergeRequestIid: publication.mergeRequestIid,
      commentBody: publication.commentBody,
      commentLine: publication.commentLine,
      commentSide: publication.commentSide,
      commentFilePath: publication.commentFilePath,
      commentOldPath: publication.commentOldPath,
      commentNewPath: publication.commentNewPath,
    })

    await markPublicationSucceeded({
      id: publication.id,
      discussionId: result.discussionId,
      noteId: result.noteId,
    })
    return { status: "succeeded" }
  } catch (error) {
    const classified = classifyPublishError(error)
    await markPublicationFailed({
      id: publication.id,
      attempts: publication.attempts,
      retryable: classified.retryable,
      message: classified.message,
    })
    return { status: classified.retryable && publication.attempts < MAX_ATTEMPTS ? "failed" : "dead" }
  }
}

