import { parsePositiveIntWithFallback, parseRate } from "./logger-utils"

export type SamplingRates = {
  info: number
  warn: number
  debug: number
  error: number
}

export type KeepRule = {
  status?: number
  duration?: number
  path?: string
}

type ResolveSamplingRatesOptions = {
  environment: string
  overrides?: Partial<SamplingRates>
  env?: Record<string, string | undefined>
}

type ResolveKeepRulesOptions = {
  env?: Record<string, string | undefined>
}

export const resolveSamplingRates = ({
  environment,
  overrides,
  env = process.env,
}: ResolveSamplingRatesOptions): SamplingRates => {
  const prodDefaultDebug = environment === "production" ? 0 : 100

  return {
    info: overrides?.info ?? parseRate(env.APP_LOG_SAMPLE_INFO, 100),
    warn: overrides?.warn ?? parseRate(env.APP_LOG_SAMPLE_WARN, 100),
    debug: overrides?.debug ?? parseRate(env.APP_LOG_SAMPLE_DEBUG, prodDefaultDebug),
    error: overrides?.error ?? parseRate(env.APP_LOG_SAMPLE_ERROR, 100),
  }
}

export const resolveKeepRules = ({ env = process.env }: ResolveKeepRulesOptions = {}): KeepRule[] => {
  const keep: KeepRule[] = []

  const minStatus = parsePositiveIntWithFallback(env.APP_LOG_KEEP_MIN_STATUS, 400)
  if (minStatus > 0) {
    keep.push({ status: minStatus })
  }

  const minDuration = parsePositiveIntWithFallback(env.APP_LOG_KEEP_MIN_DURATION_MS, 1000)
  if (minDuration > 0) {
    keep.push({ duration: minDuration })
  }

  const pathPrefix = env.APP_LOG_KEEP_PATH_PREFIX?.trim()
  if (pathPrefix) {
    keep.push({ path: `${pathPrefix}/**` })
  }

  return keep
}

